window.DGT_META = {"generado":"2026-11-08","version":"2026-11-08 03:00","publica":true,"practica":{"total":407}};
window.DGT_PREGUNTAS = [{"id":"p101","src":"practica","bat":[],"t":"prioridad","q":"En una intersección sin señalizar, ¿a quién debe ceder el paso?","o":["A los vehículos que se acerquen por su derecha.","A los vehículos que se acerquen por su izquierda.","Al vehículo de mayor tamaño."],"c":0,"img":null,"e":"Sin señales ni agentes rige la regla general: se cede el paso a quien se aproxima por la derecha. El tamaño del vehículo no da preferencia y quien viene por la izquierda debe cederle a usted.","r":"RGC, art. 57.1","k":null,"d":0,"rev":null},{"id":"p102","src":"practica","bat":[],"t":"prioridad","q":"Llega a una glorieta sin señales que indiquen otra cosa. ¿Quién tiene preferencia?","o":["Usted, porque viene por la derecha de quienes circulan por ella.","Los vehículos que ya circulan dentro de la glorieta.","El vehículo que llegue antes a la línea de entrada."],"c":1,"img":null,"e":"En las glorietas, quien está dentro tiene preferencia sobre quien pretende entrar. Es una excepción a la regla de la derecha, aunque usted esté a la derecha de los que circulan por ella.","r":"RGC, art. 57.1.c","k":"Dentro manda: el que ya gira, pasa.","d":1,"rev":null},{"id":"p103","src":"practica","bat":[],"t":"prioridad","q":"Sale de una vía sin pavimentar a una carretera asfaltada sin señalizar. ¿Qué debe hacer?","o":["Pasar, si los vehículos de la carretera vienen por su izquierda.","Pasar primero, porque viene por la derecha.","Ceder el paso a los vehículos que circulan por la vía pavimentada."],"c":2,"img":null,"e":"Los vehículos que circulan por una vía pavimentada tienen preferencia sobre los que acceden desde una sin pavimentar, vengan por donde vengan. Esta excepción prevalece sobre la regla de la derecha.","r":"RGC, art. 57.1.a","k":null,"d":0,"rev":null},{"id":"p104","src":"practica","bat":[],"t":"prioridad","q":"Ante una señal de ceda el paso, si no se acerca ningún vehículo con preferencia, ¿está obligado a detenerse?","o":["No; solo debe detenerse si es necesario para ceder el paso.","Sí, siempre, como en un stop.","Solo de noche."],"c":0,"img":null,"e":"El ceda el paso obliga a ceder, no a parar: si no viene nadie con preferencia puede continuar. La detención obligatoria en todo caso es propia de la señal de stop.","r":"RGC, art. 151 (R-1)","k":"Ceda: mira y sigue si está libre. Stop: siempre a cero.","d":0,"rev":null},{"id":"p105","src":"practica","bat":[],"t":"prioridad","q":"Ante una señal de stop sin tráfico a la vista, ¿qué debe hacer?","o":["Reducir la velocidad y continuar si la vía está libre.","Detenerse por completo antes de la línea de detención y después continuar con precaución.","Detenerse solo si hay una marca vial transversal."],"c":1,"img":null,"e":"El stop obliga siempre a detenerse por completo, haya o no tráfico, en la línea de detención o, si no la hay, donde se tenga visibilidad suficiente, y después ceder el paso.","r":"RGC, art. 151 (R-2)","k":null,"d":1,"rev":null},{"id":"p106","src":"practica","bat":[],"t":"prioridad","q":"Un semáforo muestra luz amarilla fija. ¿Qué indica?","o":["Que puede pasar con precaución.","Que debe acelerar para pasar antes del rojo.","Que debe detenerse, salvo que esté tan cerca que no pueda hacerlo con seguridad."],"c":2,"img":null,"e":"El ámbar fijo obliga a detenerse en las mismas condiciones que el rojo, salvo cuando, al encenderse, el vehículo esté tan cerca que no pueda detenerse con seguridad. No es una invitación a acelerar.","r":"RGC, art. 146.b","k":null,"d":0,"rev":null},{"id":"p107","src":"practica","bat":[],"t":"prioridad","q":"Un semáforo de luz amarilla intermitente le indica…","o":["que debe extremar la precaución y, si procede, ceder el paso.","que debe detenerse siempre.","que el semáforo está averiado y puede pasar sin más."],"c":0,"img":null,"e":"El ámbar intermitente obliga a extremar la precaución y, en su caso, a ceder el paso. No obliga a detenerse si no es necesario.","r":"RGC, art. 146.c","k":null,"d":0,"rev":null},{"id":"p108","src":"practica","bat":[],"t":"prioridad","q":"Un agente de circulación levanta el brazo verticalmente. ¿Qué significa?","o":["Que todos deben acelerar para despejar el cruce.","Que deben detenerse los usuarios que se aproximan, salvo los que ya no puedan hacerlo con seguridad.","Que solo deben detenerse los peatones."],"c":1,"img":null,"e":"El brazo levantado verticalmente obliga a detenerse a todos los que se aproximan al agente, salvo a los conductores que estén tan cerca que no puedan hacerlo con seguridad. A quienes ya están dentro de una intersección no les obliga a detenerse.","r":"RGC, art. 143.1.a","k":null,"d":0,"rev":null},{"id":"p109","src":"practica","bat":[],"t":"prioridad","q":"Gira a la derecha y unos peatones están cruzando la calzada a la que se incorpora, sin paso señalizado. ¿Quién tiene preferencia?","o":["Usted, porque no hay paso de peatones.","Usted, si señalizó el giro con antelación.","Los peatones."],"c":2,"img":null,"e":"Al girar para entrar en otra vía, los conductores deben ceder el paso a los peatones que la estén cruzando, aunque no haya paso señalizado.","r":"RGC, art. 65.1.b","k":null,"d":1,"rev":null},{"id":"p110","src":"practica","bat":[],"t":"prioridad","q":"Un vehículo de emergencia se acerca con las señales luminosas y acústicas encendidas. ¿Qué debe hacer?","o":["Facilitarle el paso apartándose de forma segura, normalmente hacia la derecha.","Frenar en seco en su carril.","Acelerar para no entorpecerle."],"c":0,"img":null,"e":"Hay que facilitar el paso al vehículo prioritario en servicio, apartándose normalmente a la derecha o deteniéndose si es necesario, sin maniobras bruscas que creen nuevos peligros.","r":"RGC, arts. 67 a 69","k":null,"d":0,"rev":null},{"id":"p111","src":"practica","bat":[],"t":"prioridad","q":"En un estrechamiento de gran pendiente sin señalizar, ¿quién tiene preferencia, en general?","o":["El vehículo que circula en sentido descendente.","El vehículo que circula en sentido ascendente, salvo que el otro haya entrado antes.","El vehículo de mayor tamaño."],"c":1,"img":null,"e":"En tramos estrechos de gran pendiente tiene preferencia, en general, quien sube, salvo que el que baja haya llegado antes al estrechamiento. Arrancar cuesta arriba es más difícil y peligroso.","r":"RGC, art. 63","k":null,"d":1,"rev":null},{"id":"p112","src":"practica","bat":[],"t":"prioridad","q":"Un grupo de ciclistas está cruzando una intersección y el primero ya ha iniciado el cruce. ¿Cómo actúa?","o":["Pasa entre ellos si hay hueco.","Cede el paso solo al primero.","Espera a que pase todo el grupo, que se considera una sola unidad."],"c":2,"img":null,"e":"A efectos de prioridad, un grupo de ciclistas se considera una única unidad móvil: si el primero ha iniciado el cruce, el resto del grupo también tiene preferencia.","r":"RGC, art. 64","k":null,"d":0,"rev":null},{"id":"p113","src":"practica","bat":[],"t":"prioridad","q":"Sale de un garaje o de un aparcamiento privado a la vía pública. ¿Qué debe hacer?","o":["Ceder el paso a los vehículos y peatones que circulan por la vía.","Pasar primero si los vehículos vienen por su izquierda.","Usar la bocina para avisar y salir."],"c":0,"img":null,"e":"Quien se incorpora a la circulación desde un inmueble, garaje o zona de estacionamiento debe ceder el paso a los que circulan por la vía, incluidos los peatones de la acera.","r":"RGC, art. 72","k":null,"d":0,"rev":null},{"id":"p114","src":"practica","bat":[],"t":"prioridad","q":"Se incorpora a una autovía por el carril de aceleración. ¿Quién tiene preferencia?","o":["Usted, porque viene por la derecha.","Los vehículos que ya circulan por la autovía.","Nadie: se alternan."],"c":1,"img":null,"e":"Quien circula por la autovía tiene preferencia. Usted debe usar el carril de aceleración para adaptar su velocidad e incorporarse cuando haya hueco, cediendo el paso. Los que circulan por ella deben facilitarlo cuando puedan.","r":"RGC, arts. 57.1.d y 72","k":null,"d":0,"rev":null},{"id":"p115","src":"practica","bat":[],"t":"prioridad","q":"Un tranvía se aproxima a una intersección sin señalizar por su izquierda. ¿Quién pasa primero?","o":["Usted, porque el tranvía viene por la izquierda.","Quien llegue primero.","El tranvía, porque los vehículos que circulan sobre raíles tienen preferencia."],"c":2,"img":null,"e":"Los vehículos que circulan sobre raíles tienen preferencia de paso sobre los demás usuarios en intersecciones sin señalizar, vengan por donde vengan.","r":"RGC, art. 57.1.b","k":null,"d":0,"rev":null},{"id":"p116","src":"practica","bat":[],"t":"velocidad","q":"¿Cuál es la velocidad máxima genérica de un turismo en una carretera convencional?","o":["90 km/h.","100 km/h.","80 km/h."],"c":0,"img":null,"e":"En carreteras convencionales el límite genérico para turismos y motocicletas es de 90 km/h. El antiguo límite de 100 km/h en carreteras con arcén ancho se suprimió en 2019.","r":"RGC, art. 48","k":null,"d":0,"rev":null},{"id":"p117","src":"practica","bat":[],"t":"velocidad","q":"En una vía urbana con un único carril por sentido de circulación, la velocidad máxima genérica es…","o":["50 km/h.","30 km/h.","40 km/h."],"c":1,"img":null,"e":"Desde mayo de 2021, en vías urbanas de un único carril por sentido el límite es de 30 km/h. 50 km/h se mantiene en vías de dos o más carriles por sentido.","r":"RGC, art. 50","k":"Un carril, treinta; dos o más, cincuenta; todo a nivel, veinte.","d":0,"rev":null},{"id":"p118","src":"practica","bat":[],"t":"velocidad","q":"¿Cuál es la velocidad máxima en una vía urbana de plataforma única de calzada y acera?","o":["30 km/h.","10 km/h.","20 km/h."],"c":2,"img":null,"e":"En las vías que disponen de plataforma única de calzada y acera la velocidad máxima es de 20 km/h, y desde la reforma de 2026 el peatón tiene prioridad en ellas.","r":"RGC, art. 50","k":null,"d":0,"rev":null},{"id":"p119","src":"practica","bat":[],"t":"velocidad","q":"La velocidad máxima de un ciclomotor es de…","o":["45 km/h en cualquier vía.","50 km/h en ciudad y 70 km/h fuera.","60 km/h."],"c":0,"img":null,"e":"Los ciclomotores, por definición, tienen una velocidad máxima por construcción de 45 km/h, y ese es su límite en cualquier tipo de vía.","r":"RGC, art. 48","k":null,"d":0,"rev":null},{"id":"p120","src":"practica","bat":[],"t":"velocidad","q":"¿Puede superar en 20 km/h el límite de velocidad para adelantar en una carretera convencional?","o":["Sí, si adelanta a un vehículo lento.","No; está prohibido superar el límite también al adelantar.","Sí, durante 10 segundos como máximo."],"c":1,"img":null,"e":"El margen de 20 km/h para adelantar se suprimió. Hoy no se puede superar el límite de velocidad en ningún caso, tampoco durante un adelantamiento.","r":"RGC, art. 48 (reforma 2018)","k":null,"d":1,"rev":null},{"id":"p121","src":"practica","bat":[],"t":"velocidad","q":"Un turismo circula por una autovía. ¿Cuál es su velocidad mínima?","o":["40 km/h.","No hay mínima.","60 km/h, salvo causa justificada."],"c":2,"img":null,"e":"En autopistas y autovías no se puede circular a menos de la mitad de la velocidad genérica de la vía para cada vehículo; para un turismo, 60 km/h. Se exceptúan las causas justificadas, como la congestión o la meteorología.","r":"RGC, art. 49","k":null,"d":0,"rev":null},{"id":"p122","src":"practica","bat":[],"t":"velocidad","q":"¿En qué caso superar la velocidad máxima es delito?","o":["Cuando se supera en más de 60 km/h en vía urbana o en más de 80 km/h en vía interurbana.","Cuando se supera en más de 30 km/h en cualquier vía.","Nunca: es solo una infracción administrativa."],"c":0,"img":null,"e":"El Código Penal castiga conducir a una velocidad superior en 60 km/h en vía urbana o en 80 km/h en vía interurbana a la permitida reglamentariamente.","r":"Código Penal, art. 379.1","k":null,"d":0,"rev":null},{"id":"p123","src":"practica","bat":[],"t":"velocidad","q":"La velocidad de la vía es 90 km/h, pero su vehículo tiene un límite genérico de 80 km/h. ¿A qué velocidad puede circular como máximo?","o":["90 km/h, porque manda la señal.","80 km/h, porque siempre se aplica el límite más bajo.","85 km/h."],"c":1,"img":null,"e":"Cuando coinciden varios límites (el de la vía, el del vehículo, el de una señal…), se respeta siempre el más restrictivo.","r":"RGC, art. 48","k":null,"d":1,"rev":null},{"id":"p124","src":"practica","bat":[],"t":"velocidad","q":"¿Qué es la velocidad adecuada?","o":["La máxima permitida por la señal.","La que permite detenerse dentro de la distancia de visibilidad, ante cualquier obstáculo previsible.","La misma que lleva el resto del tráfico."],"c":1,"img":null,"e":"El conductor debe adecuar la velocidad a sus condiciones, las del vehículo, la vía, la meteorología y el tráfico, de modo que pueda detenerse ante cualquier obstáculo previsible. Puede ser bastante inferior al límite.","r":"LSV, art. 21; RGC, art. 45","k":null,"d":0,"rev":null},{"id":"p125","src":"practica","bat":[],"t":"velocidad","q":"Una forma práctica de comprobar la distancia de seguridad con buen tiempo es…","o":["dejar al menos 2 segundos con el vehículo de delante.","dejar 10 metros siempre.","verle las ruedas traseras al vehículo de delante."],"c":0,"img":null,"e":"La regla de los dos segundos: cuando el vehículo de delante pase por un punto fijo, usted no debe llegar a él antes de dos segundos. Con lluvia o suelo deslizante hay que, al menos, duplicarla.","r":"RGC, art. 54","k":"«Mil uno, mil dos»: si llegas antes de acabar, estás demasiado cerca.","d":0,"rev":null},{"id":"p126","src":"practica","bat":[],"t":"velocidad","q":"Si duplica la velocidad, la distancia de frenado…","o":["se duplica.","se reduce a la mitad.","se multiplica aproximadamente por cuatro."],"c":2,"img":null,"e":"La energía que hay que disipar al frenar crece con el cuadrado de la velocidad: al doble de velocidad, la distancia de frenado es unas cuatro veces mayor. La distancia de reacción, en cambio, solo se duplica.","r":"Física del frenado","k":null,"d":1,"rev":null},{"id":"p127","src":"practica","bat":[],"t":"velocidad","q":"¿Qué mide un radar de tramo?","o":["La velocidad en un punto concreto.","La velocidad media entre dos puntos.","La distancia con el vehículo de delante."],"c":1,"img":null,"e":"El radar de tramo registra el paso del vehículo en dos puntos y calcula la velocidad media entre ambos. Frenar solo ante una cámara no sirve.","r":"Sistemas de control de la DGT","k":null,"d":0,"rev":null},{"id":"p128","src":"practica","bat":[],"t":"velocidad","q":"¿Dónde está especialmente indicado reducir la velocidad aunque no haya señal?","o":["Al acercarse a pasos de peatones, intersecciones o zonas con niños.","Solo en autopista.","Solo cuando hay un agente."],"c":0,"img":null,"e":"Hay que moderar la velocidad y, si es preciso, detenerse cuando las circunstancias lo exijan: pasos de peatones, intersecciones, presencia de niños, ancianos o ciclistas, suelo mojado, deslumbramientos, etc.","r":"RGC, art. 46","k":null,"d":0,"rev":null},{"id":"p129","src":"practica","bat":[],"t":"velocidad","q":"Circula detrás de otro vehículo por un túnel. ¿Qué distancia mínima debe dejar un turismo?","o":["50 metros o 2 segundos.","100 metros o 4 segundos.","Basta con la distancia de seguridad normal."],"c":1,"img":null,"e":"En los túneles los turismos deben mantener una distancia mínima de 100 metros o 4 segundos con el vehículo precedente. Para vehículos de más de 3.500 kg es de 150 metros o 6 segundos.","r":"RGC, art. 54 y Anexo de túneles","k":null,"d":1,"rev":null},{"id":"p130","src":"practica","bat":[],"t":"velocidad","q":"El efecto túnel en la visión del conductor consiste en…","o":["que ve mejor al entrar en un túnel.","que se deslumbra con las luces del túnel.","que a más velocidad se estrecha el campo visual útil."],"c":2,"img":null,"e":"Al aumentar la velocidad, el conductor concentra la vista en un punto lejano y pierde percepción de lo que ocurre a los lados: su campo visual útil se reduce.","r":"Factor humano (manual DGT)","k":null,"d":0,"rev":null},{"id":"p131","src":"practica","bat":[],"t":"adelantamiento","q":"Como norma general, ¿por qué lado se adelanta?","o":["Por la izquierda.","Por la derecha.","Por el lado con más espacio."],"c":0,"img":null,"e":"El adelantamiento se hace por la izquierda. Solo se permite por la derecha en casos concretos, como cuando el de delante indica que va a girar a la izquierda y se ha desplazado a ese lado.","r":"RGC, art. 82","k":null,"d":0,"rev":null},{"id":"p132","src":"practica","bat":[],"t":"adelantamiento","q":"El vehículo de delante señaliza que va a girar a la izquierda y se ha colocado junto al eje de la calzada. ¿Cómo puede adelantarle?","o":["Por la izquierda, invadiendo el sentido contrario.","Por la derecha.","No puede adelantarle."],"c":1,"img":null,"e":"Es una de las excepciones: cuando el conductor de delante ha indicado claramente su intención de girar a la izquierda y se ha desplazado hacia ese lado, se le adelanta por la derecha.","r":"RGC, art. 82.2.a","k":null,"d":0,"rev":null},{"id":"p133","src":"practica","bat":[],"t":"adelantamiento","q":"Le están adelantando. ¿Qué debe hacer?","o":["Acelerar para no perder la posición.","Hacerle ráfagas para avisarle.","Ceñirse a la derecha y no aumentar la velocidad."],"c":2,"img":null,"e":"El conductor adelantado está obligado a ceñirse al borde derecho de la calzada y a no aumentar la velocidad ni hacer maniobras que impidan o dificulten el adelantamiento.","r":"RGC, art. 86","k":null,"d":1,"rev":null},{"id":"p134","src":"practica","bat":[],"t":"adelantamiento","q":"¿Está permitido adelantar en un paso de peatones señalizado?","o":["No, está prohibido.","Sí, si no hay peatones a la vista.","Sí, si se hace a menos de 30 km/h."],"c":0,"img":null,"e":"Adelantar en los pasos para peatones señalizados está prohibido: un vehículo detenido puede estar tapando a un peatón que cruza.","r":"RGC, art. 87.1.b","k":null,"d":0,"rev":null},{"id":"p135","src":"practica","bat":[],"t":"adelantamiento","q":"En una curva de visibilidad reducida en carretera de doble sentido con un carril por sentido…","o":["puede adelantar si va deprisa.","está prohibido adelantar invadiendo el sentido contrario.","puede adelantar si toca la bocina."],"c":1,"img":null,"e":"En curvas y cambios de rasante de visibilidad reducida está prohibido adelantar cuando haya que ocupar el sentido contrario, porque no se puede ver a quien viene de frente.","r":"RGC, art. 87.1.a","k":null,"d":0,"rev":null},{"id":"p136","src":"practica","bat":[],"t":"adelantamiento","q":"Hay una línea continua en el centro de la calzada y quiere adelantar a un turismo lento. ¿Puede rebasarla?","o":["Sí, si el turismo va a menos de 50 km/h.","Sí, si hay visibilidad suficiente.","No."],"c":2,"img":null,"e":"La línea continua no se puede pisar ni rebasar. La única excepción reglamentaria para adelantar es la de ciclos y vehículos lentos similares, cuando se puede hacer con seguridad; no se aplica a un turismo.","r":"RGC, arts. 88 y 167","k":null,"d":1,"rev":null},{"id":"p137","src":"practica","bat":[],"t":"adelantamiento","q":"Antes de adelantar, ¿qué debe comprobar?","o":["Que tiene espacio y visibilidad suficientes, que nadie le está adelantando a usted y que puede volver a su carril sin peligro.","Solo que no viene nadie de frente.","Solo que el vehículo de delante va más lento que el límite."],"c":0,"img":null,"e":"Hay que asegurarse de que hay espacio libre suficiente en el carril que se va a usar, de que ningún conductor que le sigue ha iniciado ya un adelantamiento y de que podrá reincorporarse sin obligar a otros a maniobrar bruscamente.","r":"RGC, art. 84","k":null,"d":0,"rev":null},{"id":"p138","src":"practica","bat":[],"t":"adelantamiento","q":"Un vehículo está detenido en su carril por una avería y para rebasarlo debe ocupar parte del sentido contrario. ¿Qué debe hacer?","o":["Rebasarlo deprisa para estar poco tiempo en el carril contrario.","Asegurarse de que puede hacerlo sin peligro y, si es interurbana, dejar 1,5 m y reducir 20 km/h.","Esperar siempre detrás hasta que lo retiren."],"c":1,"img":null,"e":"Rebasar un vehículo inmovilizado no es un adelantamiento, pero exige comprobar que se puede hacer sin peligro. Desde la reforma de 2026, si está inmovilizado por accidente, avería o auxilio, hay que dejar 1,5 m y reducir 20 km/h respecto al límite.","r":"RGC (reforma del RD 518/2026)","k":null,"d":0,"rev":null},{"id":"p139","src":"practica","bat":[],"t":"adelantamiento","q":"Tras adelantar, ¿cuándo debe volver a su carril?","o":["Inmediatamente, aunque obligue al adelantado a frenar.","Cuando tenga suficiente distancia con el vehículo adelantado, señalizándolo con el intermitente derecho.","Cuando deje de ver el vehículo adelantado por el retrovisor."],"c":1,"img":null,"e":"Hay que reincorporarse progresivamente, señalizando, cuando se haya dejado suficiente distancia con el adelantado para no obligarle a frenar ni a maniobrar.","r":"RGC, art. 85","k":null,"d":0,"rev":null},{"id":"p140","src":"practica","bat":[],"t":"adelantamiento","q":"¿Está permitido adelantar en un túnel con un solo carril por sentido?","o":["Sí, si la línea es discontinua y hay visibilidad.","Sí, solo a motocicletas.","No, está prohibido."],"c":2,"img":null,"e":"En los túneles y pasos inferiores en los que solo haya un carril para cada sentido está prohibido adelantar.","r":"RGC, art. 87.1.d","k":null,"d":0,"rev":null},{"id":"p141","src":"practica","bat":[],"t":"adelantamiento","q":"En una intersección de una vía con prioridad señalizada, ¿puede adelantar?","o":["Sí, si circula por la vía con prioridad y la maniobra es segura.","Nunca.","Solo por la derecha."],"c":0,"img":null,"e":"Adelantar en las intersecciones y sus proximidades está prohibido, pero hay excepciones, como circular por una vía con prioridad de paso señalizada.","r":"RGC, art. 87.1.c","k":null,"d":1,"rev":null},{"id":"p142","src":"practica","bat":[],"t":"maniobras","q":"¿Cuál es la distancia máxima que se puede recorrer marcha atrás?","o":["15 metros, sin invadir una intersección.","50 metros.","La necesaria, siempre que se señalice."],"c":0,"img":null,"e":"La marcha atrás solo se permite como maniobra complementaria, en un recorrido no superior a 15 metros y sin invadir un cruce de vías.","r":"RGC, art. 80","k":"Marcha atrás: quince y sin cruzar.","d":0,"rev":null},{"id":"p143","src":"practica","bat":[],"t":"maniobras","q":"¿Dónde está prohibida la marcha atrás?","o":["En las calles de sentido único.","En autopistas y autovías.","En los aparcamientos."],"c":1,"img":null,"e":"Está prohibido circular marcha atrás en autopistas y autovías. En el resto de vías se permite como maniobra complementaria, con los límites reglamentarios.","r":"RGC, art. 80.1","k":null,"d":0,"rev":null},{"id":"p144","src":"practica","bat":[],"t":"maniobras","q":"Para girar a la derecha, debe colocarse…","o":["en el centro de la calzada.","lo más a la izquierda posible.","lo más cerca posible del borde derecho."],"c":2,"img":null,"e":"Para girar a la derecha hay que ceñirse todo lo posible al borde derecho de la calzada, con antelación y señalizando la maniobra.","r":"RGC, art. 75.1.a","k":null,"d":0,"rev":null},{"id":"p145","src":"practica","bat":[],"t":"maniobras","q":"Para girar a la izquierda en una calzada de doble sentido, debe colocarse…","o":["junto a la marca longitudinal que separa los sentidos, sin invadir el contrario.","pegado al borde derecho.","en el sentido contrario, para girar antes."],"c":0,"img":null,"e":"En vías de doble sentido hay que ceñirse a la marca longitudinal de separación de sentidos o, si no la hay, al eje de la calzada, sin invadir la zona del sentido contrario.","r":"RGC, art. 75.1.b","k":null,"d":0,"rev":null},{"id":"p146","src":"practica","bat":[],"t":"maniobras","q":"¿Dónde está prohibido el cambio de sentido?","o":["En cualquier vía urbana.","En pasos a nivel, túneles, curvas y cambios de rasante de visibilidad reducida.","En vías de doble sentido con línea discontinua."],"c":1,"img":null,"e":"El cambio de sentido está prohibido donde se pone en peligro o se obstaculiza a otros usuarios, y expresamente en pasos a nivel, túneles, curvas y rasantes de visibilidad reducida, y en autopistas y autovías salvo en los lugares habilitados.","r":"RGC, art. 79","k":null,"d":0,"rev":null},{"id":"p147","src":"practica","bat":[],"t":"maniobras","q":"¿Para qué sirve el carril de deceleración en la salida de una autovía?","o":["Para adelantar antes de salir.","Para circular más despacio por la autovía.","Para reducir la velocidad sin molestar a quienes siguen por la autovía."],"c":2,"img":null,"e":"Hay que entrar en el carril de deceleración cuanto antes y reducir la velocidad en él, no en el carril principal, para no obstaculizar al tráfico que continúa.","r":"RGC, art. 74","k":null,"d":0,"rev":null},{"id":"p148","src":"practica","bat":[],"t":"maniobras","q":"Antes de un desplazamiento lateral o cambio de carril, ¿qué es imprescindible?","o":["Mirar los retrovisores, comprobar el ángulo muerto y señalizar con antelación.","Tocar el claxon.","Acelerar para hacerlo rápido."],"c":0,"img":null,"e":"Hay que comprobar que la maniobra es segura (retrovisores y ángulo muerto) y advertirla con el intermitente con antelación suficiente. Si alguien circula por el carril de destino, se le cede el paso.","r":"RGC, arts. 74 y 109","k":null,"d":0,"rev":null},{"id":"p149","src":"practica","bat":[],"t":"maniobras","q":"Al aproximarse a un paso a nivel, las barreras empiezan a bajar. ¿Qué hace?","o":["Pasar deprisa antes de que se cierren.","Detenerse antes de las barreras.","Pasar si no ve el tren."],"c":1,"img":null,"e":"Cuando las barreras o semibarreras están en movimiento o bajadas, o la luz roja intermitente está encendida, hay que detenerse y no cruzar.","r":"RGC, arts. 94 y 146","k":null,"d":0,"rev":null},{"id":"p150","src":"practica","bat":[],"t":"maniobras","q":"Su vehículo se queda inmovilizado sobre un paso a nivel. ¿Qué es lo primero?","o":["Intentar arrancar varias veces.","Señalizar con la V-16 y esperar dentro.","Hacer salir a los ocupantes y alejarlos de la vía."],"c":2,"img":null,"e":"Lo primero es la seguridad de las personas: desalojar el vehículo y alejarse de la vía. Después, si es posible, intentar retirarlo y avisar para que se detenga el tren.","r":"RGC, art. 95","k":null,"d":1,"rev":null},{"id":"p151","src":"practica","bat":[],"t":"maniobras","q":"Se forma una retención dentro de un túnel. ¿Cómo debe actuar?","o":["Detenerse dejando distancia con el vehículo de delante y, si la espera es larga, apagar el motor.","Dar media vuelta para salir.","Pegarse al vehículo de delante para que quepan más."],"c":0,"img":null,"e":"En caso de retención en un túnel hay que mantener una distancia de seguridad incluso parado, encender la señal de emergencia si procede y apagar el motor si la detención se prolonga. Nunca se cambia de sentido.","r":"RGC, Anexo de túneles","k":null,"d":0,"rev":null},{"id":"p152","src":"practica","bat":[],"t":"maniobras","q":"¿Cuándo debe dejar de señalizar con el intermitente?","o":["Cuando lo considere oportuno.","Al terminar la maniobra.","Nunca hace falta quitarlo: se desconecta solo."],"c":1,"img":null,"e":"La señal debe mantenerse mientras dure la maniobra y apagarse en cuanto termine. Un intermitente olvidado confunde a los demás.","r":"RGC, art. 109","k":null,"d":0,"rev":null},{"id":"p153","src":"practica","bat":[],"t":"maniobras","q":"Va a abrir la puerta de su vehículo estacionado en una calle. ¿Qué debe hacer?","o":["Abrirla de golpe para salir rápido.","Abrirla siempre por el lado de la acera.","Comprobar que no se acerca nadie, incluidos ciclistas, antes de abrirla."],"c":2,"img":null,"e":"Está prohibido abrir las puertas sin comprobar que no hay peligro para otros usuarios. Un truco es abrir con la mano más alejada de la puerta, lo que obliga a girar el cuerpo y mirar atrás.","r":"RGC, art. 114","k":"Apertura holandesa: abre con la mano contraria.","d":0,"rev":null},{"id":"p154","src":"practica","bat":[],"t":"maniobras","q":"Para incorporarse a la circulación desde el arcén, ¿qué debe hacer?","o":["Señalizar, comprobar que no viene nadie y ceder el paso a los que circulan.","Salir rápido para no estorbar.","Encender las luces de emergencia y salir."],"c":0,"img":null,"e":"Quien se incorpora desde el arcén, una vía de acceso o un estacionamiento debe señalizar, comprobar que puede hacerlo sin peligro y ceder el paso a los que circulan por la calzada.","r":"RGC, art. 72","k":null,"d":0,"rev":null},{"id":"p155","src":"practica","bat":[],"t":"maniobras","q":"Va a girar a la derecha y un ciclista circula por un carril bici a su derecha en el mismo sentido. ¿Quién tiene preferencia?","o":["Usted, porque ha señalizado.","El ciclista.","Quien vaya más rápido."],"c":1,"img":null,"e":"Al girar, los conductores deben ceder el paso a los ciclistas que circulen por un carril bici o por el arcén, o que crucen por un paso para ciclistas.","r":"RGC, art. 64","k":null,"d":1,"rev":null},{"id":"p156","src":"practica","bat":[],"t":"estacionamiento","q":"¿Qué es una parada?","o":["Una detención impuesta por el tráfico.","Inmovilizar el vehículo durante un máximo de dos minutos sin que el conductor lo abandone.","Dejar el vehículo menos de una hora."],"c":1,"img":null,"e":"La parada es la inmovilización de un vehículo durante un tiempo inferior a dos minutos, sin que el conductor pueda abandonarlo. Si es más o el conductor se va, es estacionamiento. La detención es la impuesta por el tráfico o por una señal.","r":"Anexo I LSV","k":"Parada: menos de 2 minutos y tú dentro.","d":0,"rev":null},{"id":"p157","src":"practica","bat":[],"t":"estacionamiento","q":"Una línea amarilla continua junto al bordillo indica…","o":["que está prohibido estacionar, pero se puede parar.","zona de carga y descarga.","que está prohibido parar y estacionar."],"c":2,"img":null,"e":"La línea amarilla continua en el bordillo o junto a él prohíbe la parada y el estacionamiento en ese lado. La discontinua prohíbe solo el estacionamiento.","r":"RGC, art. 171","k":"Amarilla continua: ni paro ni aparco. Discontinua: paro pero no aparco.","d":1,"rev":null},{"id":"p158","src":"practica","bat":[],"t":"estacionamiento","q":"Una línea amarilla discontinua junto al bordillo indica…","o":["que está prohibido estacionar en ese lado.","que está prohibido parar y estacionar.","que el estacionamiento es de pago."],"c":0,"img":null,"e":"La línea amarilla discontinua prohíbe el estacionamiento, pero no la parada.","r":"RGC, art. 171","k":null,"d":0,"rev":null},{"id":"p159","src":"practica","bat":[],"t":"estacionamiento","q":"Fuera de poblado, ¿dónde debe parar o estacionar?","o":["En la calzada, en el lado izquierdo.","Fuera de la calzada, en el lado derecho, en el arcén si lo hay.","En cualquier lado si enciende la emergencia."],"c":1,"img":null,"e":"En vías interurbanas la parada y el estacionamiento se hacen fuera de la calzada, en el lado derecho y dejando libre la parte transitable del arcén.","r":"RGC, art. 90","k":null,"d":0,"rev":null},{"id":"p160","src":"practica","bat":[],"t":"estacionamiento","q":"Estaciona en una pendiente descendente con un turismo de cambio manual. ¿Qué es lo correcto?","o":["Dejar el cambio en punto muerto.","Poner el freno de mano y dejar engranada la marcha atrás.","Poner el freno de mano y dejar engranada la quinta."],"c":1,"img":null,"e":"En pendiente, además del freno de estacionamiento, se deja engranada la marcha corta del sentido contrario a la pendiente: marcha atrás si baja, primera si sube. También ayuda girar las ruedas hacia el bordillo.","r":"RGC, art. 92","k":"Bajando, marcha atrás; subiendo, primera.","d":0,"rev":null},{"id":"p161","src":"practica","bat":[],"t":"estacionamiento","q":"¿Está permitido parar en un paso para peatones?","o":["Sí, para dejar a un pasajero.","Sí, de noche.","No, está prohibido."],"c":2,"img":null,"e":"Los pasos para peatones están entre los lugares donde está prohibido parar, porque se impide el paso y se tapa la visibilidad de quienes cruzan.","r":"RGC, art. 91 y 94","k":null,"d":0,"rev":null},{"id":"p162","src":"practica","bat":[],"t":"estacionamiento","q":"¿Está permitido estacionar en doble fila?","o":["No.","Sí, si deja las luces de emergencia.","Sí, durante 5 minutos."],"c":0,"img":null,"e":"Estacionar en doble fila está prohibido. Las luces de emergencia no convierten la maniobra en legal.","r":"RGC, art. 94","k":null,"d":0,"rev":null},{"id":"p163","src":"practica","bat":[],"t":"estacionamiento","q":"¿Qué señal prohíbe solo el estacionamiento, permitiendo la parada?","o":["Círculo azul con borde rojo y aspa roja.","Círculo azul con borde rojo y una sola franja roja diagonal.","Octógono rojo."],"c":1,"img":null,"e":"La señal de estacionamiento prohibido (R-308) tiene una franja roja diagonal. Con aspa roja (R-307) se prohíben la parada y el estacionamiento.","r":"RGC, art. 154","k":"Una raya: no aparco. Aspa: ni paro ni aparco.","d":0,"rev":null},{"id":"p164","src":"practica","bat":[],"t":"estacionamiento","q":"¿Puede estacionar delante de un vado señalizado de entrada de vehículos?","o":["Sí, si se queda dentro del coche.","Sí, por la noche.","No, está prohibido."],"c":2,"img":null,"e":"Está prohibido estacionar delante de los vados señalizados correctamente, porque impide la entrada y salida de vehículos.","r":"RGC, art. 94.2","k":null,"d":0,"rev":null},{"id":"p165","src":"practica","bat":[],"t":"estacionamiento","q":"En una vía urbana de doble sentido, ¿en qué lado se estaciona en general?","o":["En el lado derecho, según el sentido de la marcha.","En cualquiera de los dos lados.","Siempre en el izquierdo."],"c":0,"img":null,"e":"En vías de doble sentido se para y estaciona en el lado derecho según el sentido de la marcha. En vías de sentido único se puede hacer en ambos lados, salvo prohibición.","r":"RGC, art. 90","k":null,"d":0,"rev":null},{"id":"p166","src":"practica","bat":[],"t":"estacionamiento","q":"¿Está permitido parar en un carril reservado para el autobús?","o":["Sí, si no pasa ningún autobús.","No, salvo que una señal lo permita.","Sí, durante menos de un minuto."],"c":1,"img":null,"e":"Los carriles reservados al transporte público son lugares donde está prohibido parar, salvo que la señalización lo autorice expresamente.","r":"RGC, art. 91 y 94","k":null,"d":0,"rev":null},{"id":"p167","src":"practica","bat":[],"t":"estacionamiento","q":"¿Qué se considera estacionamiento?","o":["Detenerse en un semáforo.","Inmovilizarse por una retención.","Inmovilizar el vehículo sin ser parada ni detención."],"c":2,"img":null,"e":"El estacionamiento es toda inmovilización del vehículo que no sea detención (impuesta por el tráfico) ni parada (menos de dos minutos con el conductor dentro).","r":"Anexo I LSV","k":null,"d":0,"rev":null},{"id":"p168","src":"practica","bat":[],"t":"estacionamiento","q":"¿Puede estacionar en un lugar que impida la visibilidad de una señal?","o":["No.","Sí, si es un momento.","Sí, si la señal es de las de obras."],"c":0,"img":null,"e":"Está prohibido parar y estacionar donde se impida a otros usuarios la visión de las señales de tráfico.","r":"RGC, art. 91.2","k":null,"d":0,"rev":null},{"id":"p169","src":"practica","bat":[],"t":"estacionamiento","q":"Una marca vial amarilla en zigzag indica…","o":["zona de juegos infantiles.","que está prohibido estacionar porque es un lugar reservado para algún uso, como una parada de autobús.","zona de estacionamiento de motos."],"c":1,"img":null,"e":"El zigzag amarillo señala un lugar donde está prohibido estacionar porque está reservado para un uso determinado, como la parada de transporte público o la carga y descarga.","r":"RGC, art. 171","k":null,"d":0,"rev":null},{"id":"p170","src":"practica","bat":[],"t":"estacionamiento","q":"Deja su turismo estacionado. ¿Qué debe hacer siempre?","o":["Dejar las ventanillas abiertas.","Dejar puesta la llave por si hay que moverlo.","Parar el motor y accionar el freno de estacionamiento."],"c":2,"img":null,"e":"Al estacionar hay que parar el motor, poner el freno de estacionamiento y, si es necesario, una marcha corta, para que el vehículo no pueda moverse.","r":"RGC, art. 92","k":null,"d":0,"rev":null},{"id":"p171","src":"practica","bat":[],"t":"estacionamiento","q":"¿Puede estacionar en una acera?","o":["No, salvo que esté expresamente autorizado.","Sí, si deja 1,5 m para peatones.","Sí, si es una moto."],"c":0,"img":null,"e":"La acera es para los peatones. Estacionar en ella está prohibido salvo autorización expresa mediante señalización u ordenanza municipal.","r":"RGC, art. 94; ordenanzas municipales","k":null,"d":0,"rev":null},{"id":"p172","src":"practica","bat":[],"t":"circulacion","q":"En una autovía con tres carriles por sentido, ¿por qué carril debe circular normalmente?","o":["Por el central.","Por el de la derecha, usando los demás para adelantar cuando sea necesario.","Por el izquierdo, que es el más rápido."],"c":1,"img":null,"e":"Fuera de poblado se circula por el carril de la derecha; los demás se usan para adelantar o cuando las circunstancias del tráfico lo justifiquen. Ir por el izquierdo sin motivo es una infracción.","r":"RGC, art. 31","k":null,"d":0,"rev":null},{"id":"p173","src":"practica","bat":[],"t":"circulacion","q":"¿Quién NO puede circular por una autopista?","o":["Las motocicletas.","Los turismos con remolque.","Las bicicletas, los ciclomotores y los peatones."],"c":2,"img":null,"e":"Por autopistas no pueden circular peatones, animales, vehículos de tracción animal, bicicletas, ciclomotores ni vehículos para personas con movilidad reducida.","r":"RGC, art. 38","k":null,"d":0,"rev":null},{"id":"p174","src":"practica","bat":[],"t":"circulacion","q":"¿Puede un ciclista mayor de 14 años circular por el arcén de una autovía?","o":["Sí, salvo que una señal lo prohíba.","No, nunca.","Sí, pero solo de día."],"c":0,"img":null,"e":"Los ciclistas mayores de 14 años pueden circular por el arcén de las autovías, salvo que la autoridad lo prohíba por razones de seguridad. En las autopistas, no.","r":"RGC, art. 38.3","k":null,"d":1,"rev":null},{"id":"p175","src":"practica","bat":[],"t":"circulacion","q":"¿Cómo pueden circular los ciclistas en vías interurbanas?","o":["Siempre en fila de uno.","En columna de a dos, en paralelo, y en hilera cuando haya poca visibilidad o se formen aglomeraciones.","Ocupando todo el carril."],"c":1,"img":null,"e":"Los ciclistas pueden circular en columna de a dos, lo más a la derecha posible, y deben colocarse en hilera en tramos sin visibilidad o cuando se formen aglomeraciones de tráfico.","r":"RGC, art. 36","k":null,"d":0,"rev":null},{"id":"p176","src":"practica","bat":[],"t":"circulacion","q":"Un peatón circula por una carretera sin acera ni arcén practicable. ¿Por dónde debe ir, en general?","o":["Por la derecha, en el sentido de los vehículos.","Por el centro de la calzada.","Por la izquierda, de frente a los vehículos."],"c":2,"img":null,"e":"Fuera de poblado, los peatones circulan por la izquierda para ver de frente a los vehículos que se acercan, salvo que haya razones de seguridad que justifiquen hacerlo por la derecha.","r":"RGC, art. 122","k":null,"d":0,"rev":null},{"id":"p177","src":"practica","bat":[],"t":"circulacion","q":"En un carril VAO (vehículos de alta ocupación) pueden circular…","o":["los vehículos con el número mínimo de ocupantes que indique la señal.","solo los autobuses.","cualquier vehículo en hora punta."],"c":0,"img":null,"e":"Los carriles VAO están reservados a vehículos con un número mínimo de ocupantes, que indica la señalización, además de los que esta autorice expresamente.","r":"RGC, art. 35","k":null,"d":0,"rev":null},{"id":"p178","src":"practica","bat":[],"t":"circulacion","q":"Llevar el móvil sujeto con la mano mientras conduce supone…","o":["una infracción leve sin puntos.","la pérdida de 6 puntos y multa.","nada si es para usar el navegador."],"c":1,"img":null,"e":"Conducir sujetando con la mano el teléfono móvil supone la pérdida de 6 puntos y 200 € de multa. También está prohibido manipular el navegador u otros dispositivos mientras se conduce.","r":"RGC, art. 18; LSV, Anexo II","k":null,"d":0,"rev":null},{"id":"p179","src":"practica","bat":[],"t":"circulacion","q":"¿Pueden circular los patinetes eléctricos (VMP) por las aceras?","o":["Sí, a paso de persona.","Sí, si no hay carril bici.","No, la acera es para los peatones."],"c":2,"img":null,"e":"Los vehículos de movilidad personal tienen prohibido circular por aceras y zonas peatonales. Tampoco pueden ir por vías interurbanas, travesías, autopistas, autovías ni túneles urbanos.","r":"RGC, art. 121 (RD 518/2026)","k":null,"d":0,"rev":null},{"id":"p180","src":"practica","bat":[],"t":"circulacion","q":"En una calle residencial señalizada (S-28), ¿cuál es la velocidad máxima?","o":["20 km/h y los peatones pueden usar toda la calzada.","30 km/h.","40 km/h."],"c":0,"img":null,"e":"En las calles residenciales la velocidad máxima es de 20 km/h, los peatones pueden usar toda la zona de circulación y los niños pueden jugar en ella. Los conductores deben dejarles paso.","r":"RGC, art. 159 (S-28)","k":null,"d":0,"rev":null},{"id":"p181","src":"practica","bat":[],"t":"circulacion","q":"¿Está permitido usar auriculares conectados a un reproductor mientras conduce?","o":["Sí, a bajo volumen.","No; supone la pérdida de 3 puntos.","Sí, en un solo oído."],"c":1,"img":null,"e":"Está prohibido conducir con cascos o auriculares conectados a aparatos receptores o reproductores de sonido. Supone 200 € y 3 puntos.","r":"RGC, art. 18.2","k":null,"d":0,"rev":null},{"id":"p182","src":"practica","bat":[],"t":"circulacion","q":"En vías urbanas con varios carriles en el mismo sentido delimitados por marcas…","o":["solo se puede circular por el derecho.","solo se puede circular por el izquierdo.","se puede usar el carril que mejor convenga al destino, sin cambiar de carril sin motivo."],"c":2,"img":null,"e":"En poblado, con carriles delimitados en el mismo sentido, se puede utilizar el que mejor convenga al destino, sin cambiar de carril si no es para preparar un giro o un adelantamiento.","r":"RGC, art. 33","k":null,"d":0,"rev":null},{"id":"p183","src":"practica","bat":[],"t":"circulacion","q":"Al circular por un carril de una autovía detrás de una retención, debe formar un carril de emergencia. En una vía de dos carriles…","o":["el izquierdo se aparta a la izquierda y el derecho a la derecha.","ambos se apartan a la derecha.","ambos se apartan a la izquierda."],"c":0,"img":null,"e":"Con dos carriles, los del carril izquierdo se orillan a la izquierda y los del derecho a la derecha, dejando el paso libre por el centro. Con tres carriles, el izquierdo va a la izquierda y los otros dos a la derecha.","r":"RGC (RD 518/2026)","k":null,"d":0,"rev":null},{"id":"p184","src":"practica","bat":[],"t":"senales","q":"¿Qué indica una señal con forma de triángulo con el vértice hacia arriba y borde rojo?","o":["Una obligación.","Un peligro.","Una prohibición."],"c":1,"img":null,"e":"Las señales triangulares con borde rojo son de advertencia de peligro. Las circulares con borde rojo prohíben y las circulares azules obligan.","r":"RGC, art. 149","k":null,"d":0,"rev":null},{"id":"p185","src":"practica","bat":[],"t":"senales","q":"Una señal de obras de fondo amarillo contradice a una señal vertical fija. ¿Cuál obedece?","o":["La fija, porque es permanente.","La que esté más cerca.","La de obras, porque la señalización circunstancial prevalece."],"c":2,"img":null,"e":"Las señales de balizamiento y obras modifican temporalmente el régimen normal de la vía y prevalecen sobre las señales verticales fijas y las marcas viales.","r":"RGC, art. 133","k":null,"d":0,"rev":null},{"id":"p186","src":"practica","bat":[],"t":"senales","q":"¿Qué indica una línea blanca transversal continua en la calzada?","o":["Dónde debe detenerse ante un stop, un semáforo o un agente.","Un paso de peatones.","Que puede pasar sin detenerse."],"c":0,"img":null,"e":"La línea transversal continua es la línea de detención: marca el lugar donde detenerse ante un stop, un semáforo o la orden de un agente. La discontinua indica dónde ceder el paso.","r":"RGC, art. 168","k":null,"d":0,"rev":null},{"id":"p187","src":"practica","bat":[],"t":"senales","q":"Una zona de la calzada pintada con franjas oblicuas blancas (cebreado) significa…","o":["que puede estacionar en ella.","que no se debe entrar en ella.","un carril para ciclistas."],"c":1,"img":null,"e":"El cebreado delimita una zona por la que no se debe circular; se usa, por ejemplo, para separar carriles en bifurcaciones o incorporaciones.","r":"RGC, art. 171","k":null,"d":0,"rev":null},{"id":"p188","src":"practica","bat":[],"t":"senales","q":"¿Qué indica una señal de fin de prohibición?","o":["Tiene borde rojo y fondo azul.","Es un octógono.","Es circular, de fondo blanco y con una banda diagonal negra o gris."],"c":2,"img":null,"e":"Las señales de fin de prohibición o restricción son circulares, de fondo blanco, con el símbolo atenuado y una banda diagonal negra o gris.","r":"RGC, art. 154","k":null,"d":0,"rev":null},{"id":"p189","src":"practica","bat":[],"t":"senales","q":"En un semáforo de carril, un aspa roja sobre un carril indica…","o":["que está prohibido circular por ese carril.","que el carril es de alta velocidad.","que hay que cambiar de carril hacia la izquierda."],"c":0,"img":null,"e":"Los semáforos de carril con aspa roja prohíben ocupar el carril sobre el que se encuentran. Una flecha verde hacia abajo permite circular por él.","r":"RGC, art. 147","k":null,"d":0,"rev":null},{"id":"p190","src":"practica","bat":[],"t":"senales","q":"Unas flechas blancas pintadas en un carril antes de una intersección indican…","o":["una recomendación.","la dirección o direcciones que obligatoriamente deben seguir los vehículos de ese carril.","la dirección del viento."],"c":1,"img":null,"e":"Las flechas de selección de carriles obligan a seguir la dirección o direcciones indicadas por el carril en el que se circula.","r":"RGC, art. 169","k":null,"d":0,"rev":null},{"id":"p191","src":"practica","bat":[],"t":"senales","q":"¿Qué indica una línea longitudinal discontinua cuyos trazos son más largos y sus separaciones más cortas de lo normal?","o":["Que está prohibido cambiar de carril.","Que se aproxima una línea continua o un tramo peligroso.","Que es el borde de la calzada."],"c":1,"img":null,"e":"Cuando los trazos de la línea discontinua se alargan o las separaciones se acortan, se avisa de la proximidad de una línea continua o de un tramo que requiere precaución; es el momento de no iniciar adelantamientos.","r":"RGC, art. 167","k":null,"d":0,"rev":null},{"id":"p201","src":"practica","bat":[],"t":"alumbrado","q":"¿En qué casos es obligatorio llevar encendida la luz de corto alcance (cruce) durante el día?","o":["Nunca: de día no hacen falta luces.","En túneles señalizados, carriles reversibles o adicionales y en carriles en sentido contrario al habitual.","Solo en autopistas."],"c":1,"img":null,"e":"De día es obligatoria la luz de cruce en túneles y pasos inferiores señalizados, en carriles reversibles, adicionales o en sentido contrario al normal, y siempre en motocicletas.","r":"RGC, art. 104 y 106","k":null,"d":0,"rev":null},{"id":"p202","src":"practica","bat":[],"t":"alumbrado","q":"¿Cuándo está prohibido usar la luz de largo alcance (carretera)?","o":["De noche en vías interurbanas sin iluminar.","En vías interurbanas con buena visibilidad.","Cuando pueda deslumbrar a otros usuarios o el vehículo esté parado o estacionado."],"c":2,"img":null,"e":"La luz de carretera se usa de noche en vías insuficientemente iluminadas, pero está prohibida cuando puede deslumbrar a otros usuarios (al cruzarse, al seguir a otro vehículo) y con el vehículo parado o estacionado.","r":"RGC, art. 100","k":null,"d":0,"rev":null},{"id":"p203","src":"practica","bat":[],"t":"alumbrado","q":"¿Cuándo se puede encender la luz antiniebla trasera?","o":["Solo con condiciones meteorológicas o ambientales especialmente desfavorables, como niebla espesa o lluvia muy intensa.","Siempre que llueva.","Siempre que se circule de noche."],"c":0,"img":null,"e":"La antiniebla trasera solo se usa con niebla espesa, lluvia muy intensa, nevada densa o nubes de humo o polvo. Usada sin necesidad deslumbra al que viene detrás.","r":"RGC, art. 106.3","k":null,"d":1,"rev":null},{"id":"p204","src":"practica","bat":[],"t":"alumbrado","q":"De noche, en una vía urbana suficientemente iluminada, ¿qué luz debe llevar?","o":["Solo la de posición.","La de cruce (corto alcance).","La de carretera."],"c":1,"img":null,"e":"Se puede circular de noche por poblado bien iluminado con la luz de cruce. Circular solo con la luz de posición no está permitido, y la de carretera está prohibida en vías urbanas iluminadas.","r":"RGC, arts. 99 y 101","k":null,"d":0,"rev":null},{"id":"p205","src":"practica","bat":[],"t":"alumbrado","q":"Le deslumbra un vehículo que viene de frente. ¿Qué es lo más adecuado?","o":["Responder con las largas para que las quite.","Cerrar los ojos un instante.","Reducir la velocidad y dirigir la mirada al borde derecho de la calzada."],"c":2,"img":null,"e":"Ante un deslumbramiento hay que reducir la velocidad, incluso detenerse si es necesario, y mirar hacia el borde derecho para mantener la trayectoria sin mirar directamente a las luces.","r":"RGC, art. 100.3","k":null,"d":0,"rev":null},{"id":"p206","src":"practica","bat":[],"t":"alumbrado","q":"Fuera de poblado, ¿cómo puede advertir que va a adelantar?","o":["Con la señal acústica o con ráfagas de luz.","Solo con el claxon, de forma prolongada.","Con la luz antiniebla."],"c":0,"img":null,"e":"Fuera de poblado se puede advertir al conductor de delante de la intención de adelantar con una señal acústica breve o con ráfagas de luz, sin deslumbrar.","r":"RGC, arts. 108 y 110","k":null,"d":0,"rev":null},{"id":"p207","src":"practica","bat":[],"t":"alumbrado","q":"En vía urbana, ¿cuándo se puede usar el claxon?","o":["Para saludar.","Solo para evitar un posible accidente.","Para avisar de que el semáforo se ha puesto en verde."],"c":1,"img":null,"e":"En poblado, las señales acústicas están prohibidas salvo para evitar un posible accidente. No se usan para meter prisa ni para saludar.","r":"RGC, art. 110","k":null,"d":0,"rev":null},{"id":"p208","src":"practica","bat":[],"t":"alumbrado","q":"Su vehículo queda inmovilizado en el arcén de noche, en una vía mal iluminada. ¿Qué luces deben estar encendidas?","o":["Ninguna, para no gastar batería.","Las largas, para que le vean.","Las de posición y la señal de emergencia, además de la V-16."],"c":2,"img":null,"e":"Un vehículo inmovilizado en la calzada o el arcén de una vía insuficientemente iluminada debe tener encendidas las luces de posición y, si procede, la señal de emergencia; además se señaliza con la baliza V-16.","r":"RGC, arts. 104 y 130","k":null,"d":0,"rev":null},{"id":"p209","src":"practica","bat":[],"t":"alumbrado","q":"¿Qué luces debe llevar encendidas una motocicleta durante el día?","o":["La de corto alcance (cruce).","Ninguna.","La antiniebla trasera."],"c":0,"img":null,"e":"Las motocicletas deben circular siempre con la luz de corto alcance encendida, también de día, para ser más visibles.","r":"RGC, art. 104","k":null,"d":0,"rev":null},{"id":"p210","src":"practica","bat":[],"t":"alumbrado","q":"¿Para qué sirve la señal de emergencia (todos los intermitentes a la vez) con el vehículo en marcha?","o":["Para indicar que va a estacionar en doble fila.","Para advertir a los que vienen detrás de un peligro, como una retención inesperada.","Para pedir paso en un adelantamiento."],"c":1,"img":null,"e":"En marcha, la señal de emergencia sirve para advertir a quienes siguen de un peligro, como una retención brusca o una frenada fuerte. No legaliza parar en doble fila.","r":"RGC, art. 109","k":null,"d":0,"rev":null},{"id":"p211","src":"practica","bat":[],"t":"alumbrado","q":"Con niebla espesa de día, ¿qué luz es la más adecuada delante?","o":["La de carretera, para ver más lejos.","Ninguna, porque es de día.","La antiniebla delantera o la de cruce."],"c":2,"img":null,"e":"Con niebla, la luz de carretera rebota en las gotas y empeora la visión. Lo adecuado es la antiniebla delantera, si se lleva, o la de cruce; y si es espesa, también la antiniebla trasera.","r":"RGC, arts. 102 y 106","k":null,"d":0,"rev":null},{"id":"p212","src":"practica","bat":[],"t":"alumbrado","q":"¿Puede circular de noche solo con las luces de posición encendidas?","o":["No.","Sí, en ciudad.","Sí, si hay luna llena."],"c":0,"img":null,"e":"Las luces de posición sirven para ser visto, no para ver. De noche hay que circular con la de cruce o la de carretera, según el caso.","r":"RGC, art. 99","k":null,"d":0,"rev":null},{"id":"p213","src":"practica","bat":[],"t":"alumbrado","q":"De noche, alcanza a otro vehículo y circula detrás de él a corta distancia. ¿Qué luz usa?","o":["La de carretera, para ver mejor.","La de cruce, para no deslumbrarle por los retrovisores.","Solo la de posición."],"c":1,"img":null,"e":"Hay que sustituir la luz de carretera por la de cruce cuando se sigue a otro vehículo a una distancia en la que se le pueda deslumbrar por el retrovisor.","r":"RGC, art. 100","k":null,"d":0,"rev":null},{"id":"p214","src":"practica","bat":[],"t":"alumbrado","q":"¿Qué elementos de visibilidad debe llevar una bicicleta que circula de noche?","o":["Ninguno si lleva casco.","Solo un timbre.","Luz delantera, luz trasera y catadióptrico trasero; en interurbana, además, una prenda reflectante el ciclista."],"c":2,"img":null,"e":"De noche o con poca visibilidad la bicicleta debe llevar luz de posición delantera y trasera y catadióptrico trasero; fuera de poblado, el ciclista debe vestir además una prenda reflectante.","r":"RGC, art. 98; RGV, Anexo XI","k":null,"d":0,"rev":null},{"id":"p215","src":"practica","bat":[],"t":"alumbrado","q":"¿Cuándo debe encender el intermitente para un giro?","o":["Con antelación suficiente antes de iniciar la maniobra.","Justo cuando gire el volante.","Solo si hay vehículos detrás."],"c":0,"img":null,"e":"Las maniobras deben advertirse con antelación suficiente para que los demás puedan reaccionar, y la señal se mantiene mientras dura la maniobra, haya o no otros vehículos.","r":"RGC, art. 109","k":null,"d":0,"rev":null},{"id":"p216","src":"practica","bat":[],"t":"alumbrado","q":"Un vehículo circula de día por un túnel señalizado. ¿Qué luz debe llevar?","o":["Ninguna, porque está iluminado.","La de corto alcance.","La antiniebla trasera."],"c":1,"img":null,"e":"En los túneles y pasos inferiores señalizados es obligatorio llevar la luz de corto alcance, aunque sea de día y el túnel esté iluminado.","r":"RGC, art. 104","k":null,"d":0,"rev":null},{"id":"p217","src":"practica","bat":[],"t":"alcohol","q":"¿Cuál es la tasa máxima de alcohol en aire espirado para un conductor en general?","o":["0,50 mg/l.","0,15 mg/l.","0,25 mg/l."],"c":2,"img":null,"e":"Para la mayoría de conductores el límite es 0,25 mg/l en aire espirado (0,5 g/l en sangre). Para noveles y profesionales es 0,15 mg/l (0,3 g/l).","r":"RGC, art. 20","k":"General 0,25; novel 0,15; el doble del general (0,50) ya es infracción muy grave de 6 puntos.","d":0,"rev":null},{"id":"p218","src":"practica","bat":[],"t":"alcohol","q":"Durante sus dos primeros años de permiso, ¿cuál es su tasa máxima de alcohol en aire espirado?","o":["0,15 mg/l.","0,25 mg/l.","0,00 mg/l."],"c":0,"img":null,"e":"Los conductores noveles, durante los dos años siguientes a obtener el permiso, tienen una tasa máxima de 0,15 mg/l en aire (0,3 g/l en sangre), igual que los profesionales.","r":"RGC, art. 20","k":null,"d":0,"rev":null},{"id":"p219","src":"practica","bat":[],"t":"alcohol","q":"Negarse a someterse a las pruebas de alcohol o drogas que le pide un agente…","o":["es solo una infracción leve.","es un delito.","está permitido si no ha bebido."],"c":1,"img":null,"e":"Negarse a las pruebas legalmente establecidas para comprobar las tasas de alcohol o la presencia de drogas es un delito castigado con prisión y privación del derecho a conducir.","r":"Código Penal, art. 383","k":null,"d":0,"rev":null},{"id":"p220","src":"practica","bat":[],"t":"alcohol","q":"¿Qué tiempo mínimo debe pasar entre las dos pruebas de alcoholemia en aire espirado?","o":["1 minuto.","1 hora.","10 minutos."],"c":2,"img":null,"e":"Si la primera prueba es positiva, se realiza una segunda con un intervalo mínimo de 10 minutos entre ambas. El conductor puede pedir además un análisis de sangre como contraste.","r":"RGC, art. 23","k":null,"d":1,"rev":null},{"id":"p221","src":"practica","bat":[],"t":"alcohol","q":"¿Qué acelera la eliminación del alcohol del organismo?","o":["Nada: solo el paso del tiempo.","Tomar café.","Hacer ejercicio o ducharse con agua fría."],"c":0,"img":null,"e":"El alcohol se elimina principalmente en el hígado a un ritmo que no se puede acelerar. Café, duchas o ejercicio pueden hacer sentirse más despierto, pero no bajan la tasa.","r":"Manual DGT, alcohol y conducción","k":null,"d":0,"rev":null},{"id":"p222","src":"practica","bat":[],"t":"alcohol","q":"¿Cuál de estos efectos produce el alcohol en el conductor?","o":["Mejora la visión nocturna.","Produce una falsa sensación de seguridad y aumenta el tiempo de reacción.","Reduce el tiempo de reacción."],"c":1,"img":null,"e":"El alcohol aumenta el tiempo de reacción, reduce el campo visual, altera la percepción de distancias y velocidades y da una falsa sensación de seguridad que lleva a asumir más riesgos.","r":"Manual DGT, alcohol y conducción","k":null,"d":0,"rev":null},{"id":"p223","src":"practica","bat":[],"t":"alcohol","q":"¿En qué situación el alcohol pasa más rápido a la sangre?","o":["Bebiendo después de una comida copiosa.","Bebiendo despacio.","Bebiendo en ayunas o con bebidas gaseosas."],"c":2,"img":null,"e":"El alcohol se absorbe más deprisa con el estómago vacío y mezclado con bebidas carbonatadas. La comida retrasa la absorción, pero no impide que el alcohol llegue a la sangre.","r":"Manual DGT, alcohol y conducción","k":null,"d":0,"rev":null},{"id":"p224","src":"practica","bat":[],"t":"alcohol","q":"Conducir con presencia de drogas en el organismo supone, como infracción administrativa…","o":["1.000 € y la pérdida de 6 puntos.","200 € sin pérdida de puntos.","Solo una advertencia."],"c":0,"img":null,"e":"Conducir con presencia de drogas es una infracción muy grave sancionada con 1.000 € y 6 puntos. Si además se conduce bajo su influencia, puede ser delito.","r":"LSV, arts. 14 y 80; Anexo II","k":null,"d":0,"rev":null},{"id":"p225","src":"practica","bat":[],"t":"alcohol","q":"Superar la tasa permitida sin llegar al doble supone…","o":["6 puntos y 1.000 €.","4 puntos y 500 €.","No resta puntos."],"c":1,"img":null,"e":"Superar la tasa sin llegar al doble supone 500 € y 4 puntos. Superar el doble de la tasa permitida, o reincidir en el año anterior, supone 1.000 € y 6 puntos.","r":"LSV, art. 80; Anexo II","k":null,"d":0,"rev":null},{"id":"p226","src":"practica","bat":[],"t":"alcohol","q":"Un medicamento lleva en el envase un pictograma de un coche dentro de un triángulo. ¿Qué indica?","o":["Que es un medicamento para el mareo en el coche.","Que puede tomarlo sin problema si conduce.","Que puede afectar a la capacidad de conducción: consulte al médico o farmacéutico."],"c":2,"img":null,"e":"Ese pictograma advierte de que el medicamento puede afectar a la capacidad para conducir. Hay que leer el prospecto y consultar con el médico o el farmacéutico.","r":"RD 1345/2007 (etiquetado de medicamentos)","k":null,"d":0,"rev":null},{"id":"p227","src":"practica","bat":[],"t":"alcohol","q":"Mezclar alcohol con otras drogas o medicamentos…","o":["multiplica los efectos negativos sobre la conducción.","anula los efectos del alcohol.","no tiene ningún efecto especial."],"c":0,"img":null,"e":"La combinación de alcohol con drogas o con medicamentos como ansiolíticos o antihistamínicos potencia sus efectos: más somnolencia, peores reflejos y más riesgo de accidente.","r":"Manual DGT, drogas y medicamentos","k":null,"d":0,"rev":null},{"id":"p228","src":"practica","bat":[],"t":"alcohol","q":"¿Están obligados los ciclistas a someterse a las pruebas de alcoholemia?","o":["No, solo los conductores de vehículos a motor.","Sí, como el resto de conductores.","Solo en vías urbanas."],"c":1,"img":null,"e":"Todos los conductores de cualquier vehículo, incluidos los ciclistas, están obligados a someterse a las pruebas de detección de alcohol y drogas, y se les aplican las mismas tasas.","r":"RGC, arts. 20 y 21","k":null,"d":0,"rev":null},{"id":"p229","src":"practica","bat":[],"t":"alcohol","q":"El cannabis al volante suele producir…","o":["una mejor concentración.","una reducción del tiempo de reacción.","alteraciones de la percepción, somnolencia y un aumento del tiempo de reacción."],"c":2,"img":null,"e":"El cannabis altera la percepción del tiempo y las distancias, reduce la atención y la coordinación y aumenta el tiempo de reacción.","r":"Manual DGT, drogas","k":null,"d":0,"rev":null},{"id":"p230","src":"practica","bat":[],"t":"alcohol","q":"Un conductor da positivo en un control de alcoholemia. ¿Qué puede hacer el agente con el vehículo?","o":["Inmovilizarlo, salvo que otra persona habilitada se haga cargo de la conducción.","Nada: debe dejarle seguir.","Retirarle la matrícula."],"c":0,"img":null,"e":"Si el resultado es positivo, el agente puede inmovilizar el vehículo, salvo que otra persona habilitada y en condiciones se haga cargo de conducirlo.","r":"RGC, art. 25; LSV, art. 104","k":null,"d":0,"rev":null},{"id":"p231","src":"practica","bat":[],"t":"alcohol","q":"La alcoholemia máxima tras beber se alcanza…","o":["inmediatamente.","entre 30 y 90 minutos después de beber.","al día siguiente."],"c":1,"img":null,"e":"La concentración de alcohol en sangre alcanza su máximo entre media hora y hora y media después de beber. Coger el coche «antes de que suba» no es una solución.","r":"Manual DGT, alcohol y conducción","k":null,"d":0,"rev":null},{"id":"p232","src":"practica","bat":[],"t":"alcohol","q":"La cocaína al volante suele provocar…","o":["un exceso de prudencia.","sueño inmediato.","sobrevaloración de las propias capacidades y conducción más agresiva y arriesgada."],"c":2,"img":null,"e":"Los estimulantes como la cocaína producen euforia y sobreconfianza que llevan a una conducción agresiva; cuando pasa el efecto aparecen el cansancio y la somnolencia.","r":"Manual DGT, drogas","k":null,"d":0,"rev":null},{"id":"p233","src":"practica","bat":[],"t":"factor","q":"En un viaje largo, ¿cada cuánto se recomienda descansar?","o":["Cada 2 horas o 200 km, aproximadamente.","Cada 6 horas.","Solo cuando se tenga sueño."],"c":0,"img":null,"e":"La DGT recomienda parar a descansar unos 20 minutos cada dos horas o cada 200 km, aproximadamente, aunque no se sienta cansancio.","r":"Recomendaciones DGT","k":null,"d":0,"rev":null},{"id":"p234","src":"practica","bat":[],"t":"factor","q":"Nota bostezos frecuentes, parpadeos y pesadez de ojos mientras conduce. ¿Qué es lo correcto?","o":["Abrir la ventanilla y subir la música.","Parar en un lugar seguro y descansar o dormir.","Acelerar para llegar antes."],"c":1,"img":null,"e":"Son señales de sueño. La única solución eficaz es detenerse y descansar. Abrir la ventanilla o poner música alta solo engaña unos minutos y no evita los microsueños.","r":"Manual DGT, fatiga y sueño","k":null,"d":0,"rev":null},{"id":"p235","src":"practica","bat":[],"t":"factor","q":"¿Qué es un microsueño?","o":["Una siesta corta recomendada antes de conducir.","Un tipo de sueño profundo.","Un periodo de pocos segundos en el que el conductor se queda dormido sin darse cuenta."],"c":2,"img":null,"e":"Los microsueños son pérdidas de conciencia de unos segundos. A 100 km/h, en tres segundos se recorren más de 80 metros sin control.","r":"Manual DGT, fatiga y sueño","k":null,"d":0,"rev":null},{"id":"p236","src":"practica","bat":[],"t":"factor","q":"Utilizar el teléfono con manos libres mientras conduce…","o":["está permitido, pero también distrae.","está prohibido.","no influye en la conducción."],"c":0,"img":null,"e":"El manos libres está permitido, pero la conversación sigue restando atención a la conducción. Lo prudente es limitar las llamadas o parar para hablar.","r":"RGC, art. 18.2","k":null,"d":0,"rev":null},{"id":"p237","src":"practica","bat":[],"t":"factor","q":"Después de una comida copiosa…","o":["se conduce mejor porque se tiene más energía.","aumenta la somnolencia durante la digestión.","mejoran los reflejos."],"c":1,"img":null,"e":"Las comidas abundantes, sobre todo con grasas, favorecen la somnolencia durante la digestión. Antes de conducir conviene comer ligero.","r":"Manual DGT, fatiga y sueño","k":null,"d":0,"rev":null},{"id":"p238","src":"practica","bat":[],"t":"factor","q":"¿Cuál es la temperatura recomendada en el interior del vehículo?","o":["Entre 15 y 17 ºC.","Por encima de 27 ºC.","Entre 21 y 23 ºC, aproximadamente."],"c":2,"img":null,"e":"Una temperatura interior entre 21 y 23 ºC ayuda a mantener la atención. El calor excesivo provoca somnolencia y aumenta los errores.","r":"Recomendaciones DGT","k":null,"d":0,"rev":null},{"id":"p239","src":"practica","bat":[],"t":"factor","q":"La conducción monótona por autovía durante mucho tiempo puede producir…","o":["hipnosis de la carretera, una disminución peligrosa de la atención.","más atención, porque hay menos tráfico.","mejora de los reflejos."],"c":0,"img":null,"e":"La monotonía de un trayecto largo y recto puede provocar un estado de somnolencia y desatención conocido como hipnosis de la carretera. Ayudan los descansos y la buena ventilación.","r":"Manual DGT, factor humano","k":null,"d":0,"rev":null},{"id":"p240","src":"practica","bat":[],"t":"factor","q":"¿Cuánto dura aproximadamente el tiempo de reacción de un conductor descansado y atento?","o":["Unos 3 segundos.","Entre 0,75 y 1 segundo.","Menos de 0,1 segundos."],"c":1,"img":null,"e":"En condiciones normales el tiempo de reacción ronda entre 0,75 y 1 segundo. El alcohol, el sueño, las distracciones o algunos medicamentos lo aumentan mucho.","r":"Manual DGT, factor humano","k":null,"d":0,"rev":null},{"id":"p241","src":"practica","bat":[],"t":"factor","q":"Un conductor está muy enfadado tras una discusión. ¿Qué es lo más prudente?","o":["Conducir más rápido para despejarse.","Conducir, porque las emociones no influyen.","Esperar a calmarse antes de conducir."],"c":2,"img":null,"e":"Las emociones intensas como la ira, la tristeza o la ansiedad reducen la atención y favorecen conductas arriesgadas o agresivas. Es mejor esperar a recuperar la calma.","r":"Manual DGT, factor humano","k":null,"d":0,"rev":null},{"id":"p242","src":"practica","bat":[],"t":"factor","q":"Tras ser deslumbrado de noche, la vista tarda en recuperarse…","o":["unos segundos, y más en personas mayores.","nada: se recupera al instante.","varias horas."],"c":0,"img":null,"e":"Tras un deslumbramiento el ojo necesita unos segundos para recuperarse, durante los cuales se ve muy poco. Con la edad este tiempo aumenta.","r":"Manual DGT, visión","k":null,"d":0,"rev":null},{"id":"p243","src":"practica","bat":[],"t":"factor","q":"¿Está permitido manipular el navegador GPS mientras conduce?","o":["Sí, si va despacio.","No; hay que programarlo con el vehículo detenido.","Sí, en autopista."],"c":1,"img":null,"e":"Está prohibido utilizar manualmente dispositivos como el navegador mientras se conduce. Hay que programarlo antes de salir o con el vehículo detenido en un lugar seguro.","r":"RGC, art. 18.2","k":null,"d":0,"rev":null},{"id":"p244","src":"practica","bat":[],"t":"factor","q":"¿Qué es la percepción del riesgo?","o":["Conducir siempre por debajo de 50 km/h.","El miedo a conducir.","La capacidad de detectar a tiempo situaciones que pueden convertirse en peligrosas."],"c":2,"img":null,"e":"Percibir el riesgo es anticipar: ver al niño que puede salir entre coches, la puerta que puede abrirse, el vehículo que puede incorporarse. Cuanto antes se detecta, más tiempo hay para reaccionar.","r":"Manual DGT, percepción del riesgo","k":null,"d":0,"rev":null},{"id":"p245","src":"practica","bat":[],"t":"factor","q":"Un conductor joven y con poca experiencia tiende a…","o":["sobrevalorar su capacidad y subestimar los riesgos.","conducir siempre demasiado despacio.","percibir mejor el riesgo que los veteranos."],"c":0,"img":null,"e":"Los conductores jóvenes suelen tener buenos reflejos, pero menos experiencia para anticipar peligros y tienden a sobrevalorar su capacidad, lo que aumenta su riesgo.","r":"Manual DGT, factor humano","k":null,"d":0,"rev":null},{"id":"p246","src":"practica","bat":[],"t":"factor","q":"¿Cuánto multiplica aproximadamente el riesgo de accidente hablar por el móvil mientras se conduce?","o":["No lo aumenta.","Por cuatro, según la DGT.","Lo reduce, porque mantiene despierto."],"c":1,"img":null,"e":"Según la DGT, hablar por el móvil mientras se conduce multiplica por cuatro el riesgo de sufrir un accidente, y escribir mensajes lo aumenta todavía más.","r":"Campañas DGT sobre distracciones","k":null,"d":0,"rev":null},{"id":"p247","src":"practica","bat":[],"t":"factor","q":"Leer o escribir un mensaje en el móvil a 100 km/h durante 5 segundos supone recorrer…","o":["unos 20 metros.","unos 50 metros.","unos 140 metros sin mirar la carretera."],"c":2,"img":null,"e":"A 100 km/h se recorren unos 28 metros por segundo: en 5 segundos son casi 140 metros conduciendo a ciegas.","r":"Cálculo: 100 km/h ≈ 27,8 m/s","k":null,"d":0,"rev":null},{"id":"p248","src":"practica","bat":[],"t":"factor","q":"¿Qué conviene hacer si se va a conducir de noche un trayecto largo?","o":["Haber descansado bien antes de salir y parar con frecuencia.","Tomar varias bebidas energéticas.","Conducir del tirón para llegar antes."],"c":0,"img":null,"e":"Entre las 3 y las 6 de la madrugada y tras la comida el cuerpo tiende al sueño. Salir descansado y hacer pausas frecuentes es la mejor prevención.","r":"Manual DGT, fatiga y sueño","k":null,"d":0,"rev":null},{"id":"p249","src":"practica","bat":[],"t":"seguridad","q":"¿Quién debe usar el cinturón de seguridad?","o":["Solo el conductor y el acompañante.","El conductor y todos los pasajeros, en cualquier vía y asiento que lo tenga.","Solo en vías interurbanas."],"c":1,"img":null,"e":"El cinturón es obligatorio para el conductor y todos los pasajeros, delante y detrás, en vías urbanas e interurbanas. Desde 2026 se eliminan también exenciones como la de los taxistas.","r":"RGC, art. 117 (RD 518/2026)","k":null,"d":0,"rev":null},{"id":"p250","src":"practica","bat":[],"t":"seguridad","q":"¿A qué altura debe colocarse el reposacabezas?","o":["A la altura del cuello.","Lo más bajo posible.","Con su borde superior a la altura de la parte superior de la cabeza."],"c":2,"img":null,"e":"El reposacabezas protege del latigazo cervical si su parte superior queda a la altura de la parte alta de la cabeza y lo más cerca posible de ella. A la altura del cuello puede agravar las lesiones.","r":"Manual DGT, seguridad pasiva","k":null,"d":0,"rev":null},{"id":"p251","src":"practica","bat":[],"t":"seguridad","q":"¿Qué niños deben viajar en un sistema de retención infantil homologado?","o":["Los que midan 135 cm o menos.","Solo los menores de 3 años.","Los menores de 12 años que pesen menos de 20 kg."],"c":0,"img":null,"e":"Los menores de estatura igual o inferior a 135 cm deben usar un sistema de retención infantil homologado adaptado a su talla y peso, y como norma general en los asientos traseros.","r":"RGC, art. 117","k":null,"d":0,"rev":null},{"id":"p252","src":"practica","bat":[],"t":"seguridad","q":"¿Se puede instalar una silla infantil a contramarcha en el asiento delantero?","o":["Sí, siempre.","Solo si el airbag frontal del acompañante está desactivado.","No, nunca."],"c":1,"img":null,"e":"Una silla a contramarcha delante solo es posible con el airbag del acompañante desactivado: si se dispara, golpearía la silla con gran violencia.","r":"RGC, art. 117","k":null,"d":1,"rev":null},{"id":"p253","src":"practica","bat":[],"t":"seguridad","q":"¿Cuál de estos es un elemento de seguridad pasiva?","o":["El sistema antibloqueo de frenos (ABS).","Los neumáticos.","El cinturón de seguridad."],"c":2,"img":null,"e":"La seguridad pasiva reduce las consecuencias de un accidente: cinturón, airbag, reposacabezas, carrocería deformable. La activa ayuda a evitarlo: frenos, ABS, ESP, neumáticos, dirección o alumbrado.","r":"Manual DGT, seguridad activa y pasiva","k":"Activa evita el golpe; pasiva protege en el golpe.","d":0,"rev":null},{"id":"p254","src":"practica","bat":[],"t":"seguridad","q":"¿Para qué sirve el ESP (control de estabilidad)?","o":["Para ayudar a corregir derrapes frenando ruedas de forma individual.","Para aparcar solo.","Para reducir el consumo."],"c":0,"img":null,"e":"El ESP detecta pérdidas de trayectoria y frena ruedas concretas o reduce la potencia para ayudar a mantener el control. Es un sistema de seguridad activa, pero no vence las leyes de la física.","r":"Manual DGT, seguridad activa","k":null,"d":0,"rev":null},{"id":"p255","src":"practica","bat":[],"t":"seguridad","q":"¿Sustituye el airbag al cinturón de seguridad?","o":["Sí, si el vehículo tiene airbag delantero.","No: es complementario y está diseñado para funcionar junto al cinturón.","Sí, en trayectos urbanos."],"c":1,"img":null,"e":"El airbag es un sistema complementario. Sin cinturón, el ocupante se desplaza hacia el airbag mientras se infla y puede sufrir lesiones graves.","r":"Manual DGT, seguridad pasiva","k":null,"d":0,"rev":null},{"id":"p256","src":"practica","bat":[],"t":"seguridad","q":"¿Quiénes se consideran usuarios vulnerables de la vía?","o":["Los conductores de camiones.","Los conductores noveles.","Peatones, ciclistas, motoristas y usuarios de patinete."],"c":2,"img":null,"e":"Son vulnerables quienes carecen de carrocería que los proteja: peatones, ciclistas, motoristas y usuarios de VMP. Ante ellos hay que extremar la precaución.","r":"LSV; RD 518/2026","k":null,"d":0,"rev":null},{"id":"p257","src":"practica","bat":[],"t":"seguridad","q":"¿Desde cuándo y dónde es obligatorio el casco para todos los ciclistas tras la reforma de 2026?","o":["Desde el 1 de octubre de 2026, en vías interurbanas, sin excepciones.","Solo en ciudad.","Solo para menores de 16 años."],"c":0,"img":null,"e":"La reforma del Reglamento elimina las exenciones: todos los ciclistas deben llevar casco en vías interurbanas. En vías urbanas sigue siendo obligatorio para menores de 16 años.","r":"RGC, art. 118 (RD 518/2026)","k":null,"d":0,"rev":null},{"id":"p258","src":"practica","bat":[],"t":"seguridad","q":"¿Por qué es peligroso llevar objetos sueltos en el interior del vehículo?","o":["Porque aumentan el consumo.","Porque en una frenada brusca o un choque salen despedidos con mucha fuerza.","No es peligroso."],"c":1,"img":null,"e":"En un choque los objetos sueltos multiplican su peso efectivo y pueden golpear a los ocupantes. Deben ir sujetos o en el maletero.","r":"Manual DGT, carga del vehículo","k":null,"d":0,"rev":null},{"id":"p259","src":"practica","bat":[],"t":"seguridad","q":"Si un peatón es atropellado a 50 km/h en lugar de a 30 km/h…","o":["el riesgo es parecido.","el riesgo es menor.","la probabilidad de que muera es mucho mayor."],"c":2,"img":null,"e":"A 30 km/h la mayoría de peatones atropellados sobrevive; a 50 km/h la probabilidad de muerte se multiplica. Es la razón del límite de 30 en calles de un carril por sentido.","r":"Datos de seguridad vial (DGT, OMS)","k":null,"d":0,"rev":null},{"id":"p260","src":"practica","bat":[],"t":"seguridad","q":"¿Qué edad mínima exige la reforma de 2026 para conducir un patinete eléctrico (VMP)?","o":["15 años.","12 años.","18 años."],"c":0,"img":null,"e":"Desde el 1 de octubre de 2026, los usuarios de VMP deben tener al menos 15 años y llevar casco, y chaleco reflectante de noche o con poca visibilidad.","r":"RD 518/2026","k":null,"d":0,"rev":null},{"id":"p261","src":"practica","bat":[],"t":"documentacion","q":"¿A qué edad se puede obtener el permiso de la clase B?","o":["A los 16 años.","A los 18 años.","A los 17 años con acompañante."],"c":1,"img":null,"e":"La edad mínima para obtener el permiso B es de 18 años.","r":"RGCond, art. 4","k":null,"d":0,"rev":null},{"id":"p262","src":"practica","bat":[],"t":"documentacion","q":"¿Con qué saldo de puntos comienza un conductor novel?","o":["12 puntos.","15 puntos.","8 puntos."],"c":2,"img":null,"e":"El conductor novel empieza con 8 puntos. Si en los dos primeros años no pierde ninguno, pasa a tener 12.","r":"LSV, Anexo II","k":null,"d":0,"rev":null},{"id":"p263","src":"practica","bat":[],"t":"documentacion","q":"¿Durante cuánto tiempo debe llevar la placa «L» un conductor novel?","o":["Durante el primer año.","Durante los dos primeros años.","Durante seis meses."],"c":0,"img":null,"e":"La señal V-13 de conductor novel se lleva durante el primer año desde la obtención del permiso. La tasa de alcohol reducida, en cambio, se aplica durante los dos primeros años.","r":"RGCond; RGV, Anexo XI","k":null,"d":1,"rev":null},{"id":"p264","src":"practica","bat":[],"t":"documentacion","q":"¿Cada cuánto se renueva el permiso B de un conductor menor de 65 años?","o":["Cada 5 años.","Cada 10 años.","Cada 15 años."],"c":1,"img":null,"e":"El permiso B tiene una vigencia de 10 años hasta los 65; a partir de esa edad se renueva cada 5 años.","r":"RGCond, art. 12","k":null,"d":0,"rev":null},{"id":"p265","src":"practica","bat":[],"t":"documentacion","q":"¿Qué vehículos permite conducir el permiso B?","o":["Cualquier camión.","Autobuses de hasta 20 plazas.","Automóviles de hasta 3.500 kg de masa máxima autorizada y hasta 8 plazas además del conductor."],"c":2,"img":null,"e":"El permiso B autoriza a conducir automóviles con MMA no superior a 3.500 kg y diseñados para no más de 8 pasajeros además del conductor, con remolque de hasta 750 kg (o más si el conjunto no supera 3.500 kg).","r":"RGCond, art. 4","k":null,"d":0,"rev":null},{"id":"p266","src":"practica","bat":[],"t":"documentacion","q":"¿Puede conducir una motocicleta de 125 cc con el permiso B?","o":["Sí, si tiene el permiso B con más de 3 años de antigüedad, solo en España.","Sí, desde el primer día.","No, nunca."],"c":0,"img":null,"e":"Con el permiso B de más de tres años de antigüedad se pueden conducir en España motocicletas de hasta 125 cc y 11 kW.","r":"RGCond, art. 4","k":null,"d":1,"rev":null},{"id":"p267","src":"practica","bat":[],"t":"documentacion","q":"Si paga una multa de tráfico en los 20 días naturales siguientes a la notificación…","o":["no tiene ningún beneficio.","tiene un 50 % de descuento.","se anulan los puntos."],"c":1,"img":null,"e":"El pago en los 20 días naturales siguientes a la notificación reduce la multa un 50 %, aunque supone renunciar a alegar y no evita la pérdida de puntos.","r":"LSV, art. 94","k":null,"d":0,"rev":null},{"id":"p268","src":"practica","bat":[],"t":"documentacion","q":"Conducir habiendo perdido la totalidad de los puntos…","o":["es una infracción leve.","está permitido si se ha pedido el curso.","es un delito."],"c":2,"img":null,"e":"Conducir un vehículo a motor tras perder la vigencia del permiso por pérdida total de puntos, o sin haberlo obtenido nunca, es un delito.","r":"Código Penal, art. 384","k":null,"d":0,"rev":null},{"id":"p269","src":"practica","bat":[],"t":"documentacion","q":"Circular con un vehículo que no tiene el seguro obligatorio…","o":["es una infracción y el vehículo puede ser inmovilizado.","está permitido si el conductor tiene seguro propio.","solo se sanciona en autopista."],"c":0,"img":null,"e":"Todo vehículo a motor debe tener el seguro obligatorio. Circular sin él es una infracción grave y los agentes pueden inmovilizar el vehículo.","r":"RDL 8/2004 (seguro obligatorio)","k":null,"d":0,"rev":null},{"id":"p270","src":"practica","bat":[],"t":"documentacion","q":"¿Qué permite conducir el permiso B además de turismos?","o":["Camiones de 7.500 kg.","Ciclomotores (los vehículos de la clase AM).","Autobuses."],"c":1,"img":null,"e":"El permiso B autoriza también a conducir los vehículos para los que se exige el permiso AM, como los ciclomotores.","r":"RGCond, art. 4","k":null,"d":0,"rev":null},{"id":"p271","src":"practica","bat":[],"t":"documentacion","q":"Una infracción grave tiene una multa de…","o":["100 €.","1.000 €.","200 €."],"c":2,"img":null,"e":"Con carácter general las infracciones leves se sancionan con hasta 100 €, las graves con 200 € y las muy graves con 500 €, salvo cuantías específicas (por ejemplo, 1.000 € en algunas de alcohol y drogas).","r":"LSV, art. 80","k":null,"d":0,"rev":null},{"id":"p272","src":"practica","bat":[],"t":"documentacion","q":"¿Qué ocurre si pierde todos sus puntos?","o":["Pierde la vigencia del permiso y debe esperar 6 meses, hacer un curso y aprobar el examen teórico.","Le devuelven 4 puntos automáticamente.","Solo paga una multa."],"c":0,"img":null,"e":"Con la pérdida total de puntos el permiso pierde su vigencia. Para recuperarlo hay que esperar 6 meses (3 para profesionales), realizar el curso de sensibilización y reeducación y superar una prueba teórica.","r":"LSV, art. 63","k":null,"d":0,"rev":null},{"id":"p273","src":"practica","bat":[],"t":"documentacion","q":"¿Cuántos puntos se pueden recuperar con un curso de recuperación parcial?","o":["Todos.","4 puntos.","2 puntos."],"c":1,"img":null,"e":"El curso de recuperación parcial permite recuperar 4 puntos, y solo se puede hacer una vez cada dos años (cada año para profesionales).","r":"Orden INT/914/2024","k":null,"d":0,"rev":null},{"id":"p274","src":"practica","bat":[],"t":"documentacion","q":"Ha cambiado de domicilio. ¿Debe comunicarlo?","o":["No, no es necesario.","Solo si cambia de provincia.","Sí, a la DGT, porque allí se le envían las notificaciones."],"c":2,"img":null,"e":"Los titulares de permisos y vehículos deben comunicar el cambio de domicilio, que es donde se envían las notificaciones de tráfico. Al empadronarse en el ayuntamiento también puede comunicarse.","r":"RGCond, art. 10; RGV, art. 30","k":null,"d":0,"rev":null},{"id":"p275","src":"practica","bat":[],"t":"mantenimiento","q":"¿Cuál es la profundidad mínima del dibujo de los neumáticos de un turismo?","o":["1,6 mm.","0,5 mm.","3 mm."],"c":0,"img":null,"e":"La profundidad mínima legal del dibujo en las ranuras principales es de 1,6 mm, aunque con menos de 3 mm empeora notablemente la evacuación del agua.","r":"RGV, Anexo VII","k":null,"d":0,"rev":null},{"id":"p276","src":"practica","bat":[],"t":"mantenimiento","q":"¿Cuándo debe comprobarse la presión de los neumáticos?","o":["Después de un viaje largo, con ellos calientes.","Con los neumáticos fríos.","Solo en la ITV."],"c":1,"img":null,"e":"La presión se mide con los neumáticos fríos, porque al calentarse aumenta y la lectura no es fiable. Conviene revisarla al menos una vez al mes y antes de viajes largos.","r":"Manual DGT, neumáticos","k":null,"d":0,"rev":null},{"id":"p277","src":"practica","bat":[],"t":"mantenimiento","q":"Un neumático con presión inferior a la recomendada…","o":["agarra mejor y consume menos.","se desgasta más por el centro.","aumenta el consumo y se desgasta más por los bordes."],"c":2,"img":null,"e":"La presión baja aumenta la superficie de contacto y la resistencia a la rodadura: más consumo, desgaste en los laterales y peor estabilidad. Una presión excesiva desgasta más el centro.","r":"Manual DGT, neumáticos","k":null,"d":0,"rev":null},{"id":"p278","src":"practica","bat":[],"t":"mantenimiento","q":"Un turismo particular nuevo debe pasar su primera ITV…","o":["a los 4 años de su matriculación.","al año.","a los 10 años."],"c":0,"img":null,"e":"Los turismos de uso particular pasan la primera ITV a los 4 años, después cada 2 años hasta los 10 años y a partir de entonces cada año.","r":"RD 920/2017 (ITV)","k":"4 - 2 - 1: a los 4 años, cada 2 hasta los 10, y luego cada año.","d":0,"rev":null},{"id":"p279","src":"practica","bat":[],"t":"mantenimiento","q":"Se enciende en el cuadro un testigo de color rojo mientras conduce. ¿Qué indica?","o":["Información sin importancia.","Una avería o situación de peligro: hay que detenerse en cuanto sea seguro.","Que hay que repostar pronto."],"c":1,"img":null,"e":"Los testigos rojos indican avería grave o peligro (frenos, temperatura, presión de aceite…) y obligan a detenerse cuanto antes con seguridad. Los ámbar avisan de algo que hay que revisar pronto.","r":"Manual DGT, testigos","k":null,"d":0,"rev":null},{"id":"p280","src":"practica","bat":[],"t":"mantenimiento","q":"Con un vehículo equipado con ABS, ante una frenada de emergencia…","o":["hay que bombear el pedal de freno.","no hay que frenar.","hay que pisar el freno a fondo y mantenerlo, sin dejar de dirigir el vehículo."],"c":2,"img":null,"e":"El ABS evita que las ruedas se bloqueen y permite seguir girando el volante. Hay que pisar a fondo y mantener la presión; es normal notar vibraciones en el pedal.","r":"Manual DGT, frenos","k":null,"d":0,"rev":null},{"id":"p281","src":"practica","bat":[],"t":"mantenimiento","q":"¿Cómo se comprueba correctamente el nivel de aceite del motor?","o":["Con el vehículo en llano y el motor parado y, preferiblemente, frío.","Con el motor en marcha.","Solo en el taller."],"c":0,"img":null,"e":"El nivel de aceite se mide con el vehículo en una superficie horizontal y el motor parado un tiempo, para que el aceite baje al cárter. Debe estar entre las marcas de mínimo y máximo de la varilla.","r":"Manual del vehículo","k":null,"d":0,"rev":null},{"id":"p282","src":"practica","bat":[],"t":"mantenimiento","q":"Unos amortiguadores en mal estado…","o":["mejoran la comodidad.","aumentan la distancia de frenado y empeoran la estabilidad.","no afectan a la seguridad."],"c":1,"img":null,"e":"Los amortiguadores mantienen las ruedas en contacto con el suelo. Si están gastados aumenta la distancia de frenado, el vehículo se balancea más y empeora la estabilidad en curvas.","r":"Manual DGT, suspensión","k":null,"d":0,"rev":null},{"id":"p283","src":"practica","bat":[],"t":"mantenimiento","q":"Si el motor se ha calentado en exceso, ¿qué no debe hacer?","o":["Detenerse en lugar seguro.","Esperar a que se enfríe.","Abrir el tapón del circuito de refrigeración con el motor caliente."],"c":2,"img":null,"e":"Con el motor caliente el líquido refrigerante está a presión y muy caliente: abrir el tapón puede provocar quemaduras graves. Hay que esperar a que se enfríe.","r":"Manual del vehículo","k":null,"d":0,"rev":null},{"id":"p284","src":"practica","bat":[],"t":"mantenimiento","q":"¿Dónde deben colocarse las cadenas para la nieve?","o":["En las ruedas motrices.","Siempre en las ruedas delanteras.","Siempre en las traseras."],"c":0,"img":null,"e":"Las cadenas se colocan en las ruedas de tracción (motrices), que son las que transmiten la fuerza al suelo. Con cadenas no hay que superar la velocidad indicada por el fabricante.","r":"RGC, art. 12; manual del vehículo","k":null,"d":0,"rev":null},{"id":"p285","src":"practica","bat":[],"t":"mantenimiento","q":"¿Qué es el aquaplaning?","o":["Un sistema de limpieza del parabrisas.","La pérdida de contacto de los neumáticos con el suelo por una capa de agua.","Un tipo de neumático de lluvia."],"c":1,"img":null,"e":"Con agua abundante y velocidad elevada, el neumático no puede evacuarla y «flota». Favorecen el aquaplaning la velocidad, los neumáticos gastados y la presión baja.","r":"Manual DGT, neumáticos","k":null,"d":0,"rev":null},{"id":"p286","src":"practica","bat":[],"t":"mantenimiento","q":"Nota que el vehículo hace aquaplaning. ¿Qué debe hacer?","o":["Frenar a fondo.","Girar bruscamente el volante.","Soltar suavemente el acelerador y sujetar el volante con firmeza, sin frenar bruscamente."],"c":2,"img":null,"e":"Hay que dejar de acelerar suavemente, sujetar el volante recto y esperar a que los neumáticos recuperen el contacto. Frenar o girar bruscamente puede provocar la pérdida de control.","r":"Manual DGT, conducción con lluvia","k":null,"d":0,"rev":null},{"id":"p287","src":"practica","bat":[],"t":"mantenimiento","q":"¿Por qué hay que cambiar periódicamente el líquido de frenos?","o":["Porque absorbe humedad y pierde eficacia con el tiempo.","Porque se evapora en una semana.","No hace falta cambiarlo nunca."],"c":0,"img":null,"e":"El líquido de frenos es higroscópico: absorbe humedad, lo que reduce su punto de ebullición y puede hacer que los frenos pierdan eficacia tras un uso intenso.","r":"Manual DGT, frenos","k":null,"d":0,"rev":null},{"id":"p288","src":"practica","bat":[],"t":"mantenimiento","q":"Una rueda de repuesto de uso temporal («de galleta»)…","o":["se puede usar indefinidamente.","se usa provisionalmente y sin superar la velocidad que indica.","solo se usa en el eje trasero."],"c":1,"img":null,"e":"Las ruedas de repuesto de uso temporal tienen limitaciones de uso y de velocidad máxima, indicadas en la propia rueda. Hay que reparar o sustituir el neumático original cuanto antes.","r":"RGV; manual del vehículo","k":null,"d":0,"rev":null},{"id":"p289","src":"practica","bat":[],"t":"mantenimiento","q":"Las escobillas del limpiaparabrisas dejan marcas y no limpian bien. ¿Qué indica?","o":["Que hay que poner más líquido.","Nada importante.","Que están desgastadas y conviene sustituirlas."],"c":2,"img":null,"e":"Las escobillas se deterioran con el sol y el uso. Si dejan franjas, ruido o agua sin retirar, hay que cambiarlas: una buena visibilidad es seguridad activa.","r":"Manual DGT, mantenimiento","k":null,"d":0,"rev":null},{"id":"p290","src":"practica","bat":[],"t":"mantenimiento","q":"El dibujo de los neumáticos de un mismo eje…","o":["debe ser del mismo tipo y medida.","puede ser distinto sin problema.","solo importa en invierno."],"c":0,"img":null,"e":"Los neumáticos de un mismo eje deben ser iguales en medida, tipo y estructura para garantizar un comportamiento homogéneo en frenada y en curva.","r":"RGV, Anexo VII","k":null,"d":0,"rev":null},{"id":"p291","src":"practica","bat":[],"t":"eficiente","q":"Al arrancar un vehículo moderno, para conducir de forma eficiente…","o":["hay que esperar unos minutos con el motor en marcha para que se caliente.","se inicia la marcha inmediatamente, sin acelerar en parado.","se acelera fuerte en punto muerto."],"c":1,"img":null,"e":"Los motores actuales no necesitan calentarse en parado: se arranca sin pisar el acelerador y se inicia la marcha enseguida, de forma suave.","r":"IDAE, conducción eficiente","k":null,"d":0,"rev":null},{"id":"p292","src":"practica","bat":[],"t":"eficiente","q":"Para ahorrar combustible, conviene circular…","o":["en marchas cortas y a altas revoluciones.","siempre en punto muerto en las bajadas.","en la marcha más larga posible y a bajas revoluciones, con velocidad uniforme."],"c":2,"img":null,"e":"Las marchas largas a bajas revoluciones y una velocidad uniforme, anticipándose al tráfico, reducen el consumo. Ir en punto muerto gasta más que bajar con una marcha engranada.","r":"IDAE, conducción eficiente","k":null,"d":0,"rev":null},{"id":"p293","src":"practica","bat":[],"t":"eficiente","q":"En una bajada, ¿qué consume menos combustible?","o":["Ir con una marcha engranada sin pisar el acelerador.","Ir en punto muerto.","Ir pisando ligeramente el acelerador."],"c":0,"img":null,"e":"Con una marcha engranada y sin acelerar, la inyección se corta y el consumo es prácticamente nulo. En punto muerto el motor consume para mantenerse al ralentí, y además se pierde el freno motor.","r":"IDAE, conducción eficiente","k":null,"d":1,"rev":null},{"id":"p294","src":"practica","bat":[],"t":"eficiente","q":"En una detención prolongada (de más de un minuto, aproximadamente)…","o":["conviene dejar el motor en marcha.","conviene apagar el motor.","conviene acelerar de vez en cuando."],"c":1,"img":null,"e":"En detenciones de más de un minuto, aproximadamente, apagar el motor ahorra combustible. Muchos vehículos lo hacen solos con el sistema start-stop.","r":"IDAE, conducción eficiente","k":null,"d":0,"rev":null},{"id":"p295","src":"practica","bat":[],"t":"eficiente","q":"¿Qué etiqueta ambiental de la DGT corresponde a los vehículos eléctricos de batería?","o":["La etiqueta C, verde.","La etiqueta ECO.","La etiqueta 0 emisiones, azul."],"c":2,"img":null,"e":"Los vehículos eléctricos de batería, de autonomía extendida e híbridos enchufables con más de 40 km de autonomía eléctrica llevan la etiqueta azul de 0 emisiones.","r":"Clasificación ambiental DGT","k":null,"d":0,"rev":null},{"id":"p296","src":"practica","bat":[],"t":"eficiente","q":"Circular con las ventanillas bajadas a velocidad elevada…","o":["aumenta la resistencia aerodinámica y el consumo.","reduce el consumo respecto al aire acondicionado siempre.","no influye en el consumo."],"c":0,"img":null,"e":"A velocidades altas las ventanillas abiertas aumentan mucho la resistencia al aire. A esas velocidades, un uso moderado del climatizador con las ventanillas cerradas puede ser más eficiente.","r":"IDAE, conducción eficiente","k":null,"d":0,"rev":null},{"id":"p297","src":"practica","bat":[],"t":"eficiente","q":"Llevar una baca o un portaequipajes vacío en el techo…","o":["no afecta al consumo.","aumenta el consumo por la resistencia aerodinámica.","mejora la estabilidad."],"c":1,"img":null,"e":"Los accesorios en el techo empeoran la aerodinámica y aumentan el consumo incluso vacíos. Conviene quitarlos cuando no se usan.","r":"IDAE, conducción eficiente","k":null,"d":0,"rev":null},{"id":"p298","src":"practica","bat":[],"t":"eficiente","q":"Una conducción eficiente se caracteriza por…","o":["frenar tarde y acelerar fuerte.","cambiar de marcha lo más tarde posible.","anticiparse al tráfico, mantener una velocidad uniforme y evitar frenazos y acelerones."],"c":2,"img":null,"e":"La clave es anticipar: ver con antelación lo que va a pasar, levantar el pie a tiempo y aprovechar la inercia. Así se ahorra combustible y se gana en seguridad.","r":"IDAE, conducción eficiente","k":null,"d":0,"rev":null},{"id":"p299","src":"practica","bat":[],"t":"eficiente","q":"¿Para qué sirven las zonas de bajas emisiones (ZBE)?","o":["Para limitar el acceso de los vehículos más contaminantes según su etiqueta ambiental.","Para aparcar gratis.","Para circular a más velocidad."],"c":0,"img":null,"e":"Las ZBE son áreas, normalmente urbanas, donde se restringe el acceso o la circulación de vehículos según su clasificación ambiental para mejorar la calidad del aire.","r":"Ley 7/2021 de cambio climático","k":null,"d":0,"rev":null},{"id":"p300","src":"practica","bat":[],"t":"eficiente","q":"Un vehículo de gasolina antiguo sin etiqueta ambiental…","o":["tiene la etiqueta ECO.","no tiene distintivo ambiental y puede tener restringido el acceso a las ZBE.","tiene la etiqueta 0."],"c":1,"img":null,"e":"Los vehículos más antiguos que no cumplen las normas de emisiones exigidas para la etiqueta B no tienen distintivo y son los primeros en ver restringido el acceso a las zonas de bajas emisiones.","r":"Clasificación ambiental DGT","k":null,"d":0,"rev":null},{"id":"p301","src":"practica","bat":[],"t":"eficiente","q":"Respecto al consumo, ¿qué influencia tiene circular a más velocidad?","o":["Ninguna.","Lo reduce, porque se llega antes.","El consumo aumenta mucho, porque la resistencia del aire crece con la velocidad."],"c":2,"img":null,"e":"La resistencia aerodinámica aumenta con el cuadrado de la velocidad, por lo que a partir de cierta velocidad el consumo crece de forma notable.","r":"IDAE, conducción eficiente","k":null,"d":0,"rev":null},{"id":"p302","src":"practica","bat":[],"t":"eficiente","q":"¿Cuál es una práctica de conducción eficiente al detenerse en un semáforo que ve en rojo desde lejos?","o":["Levantar el pie del acelerador con antelación y dejar rodar el vehículo con la marcha engranada.","Acelerar hasta el semáforo y frenar fuerte.","Poner punto muerto desde lejos."],"c":0,"img":null,"e":"Anticiparse y dejar que el vehículo ruede con la marcha engranada aprovecha el corte de inyección y la inercia. Además, si el semáforo cambia, puede no ser necesario detenerse.","r":"IDAE, conducción eficiente","k":null,"d":0,"rev":null},{"id":"p303","src":"practica","bat":[],"t":"accidentes","q":"¿Cuál es el orden correcto de actuación ante un accidente?","o":["Socorrer, avisar y proteger.","Proteger, avisar y socorrer.","Avisar, socorrer y proteger."],"c":1,"img":null,"e":"La conducta PAS: primero Proteger (para que no haya más víctimas), después Avisar a los servicios de emergencia (112) y por último Socorrer a los heridos.","r":"Manual DGT, primeros auxilios","k":"PAS: Proteger, Avisar, Socorrer.","d":0,"rev":null},{"id":"p304","src":"practica","bat":[],"t":"accidentes","q":"¿Qué número de teléfono debe marcar para avisar de un accidente?","o":["El 091.","El 060.","El 112."],"c":2,"img":null,"e":"El 112 es el número único de emergencias en toda la Unión Europea, gratuito y operativo las 24 horas, también sin cobertura de su operador.","r":"Manual DGT, primeros auxilios","k":null,"d":0,"rev":null},{"id":"p305","src":"practica","bat":[],"t":"accidentes","q":"Un herido está inconsciente pero respira y no hay sospecha de lesión de columna. ¿En qué posición se le coloca?","o":["En posición lateral de seguridad.","Boca arriba con las piernas elevadas.","Sentado."],"c":0,"img":null,"e":"La posición lateral de seguridad mantiene libre la vía aérea y evita que se ahogue si vomita. Si se sospecha lesión de columna, solo se moverá si es imprescindible.","r":"Manual DGT, primeros auxilios","k":null,"d":0,"rev":null},{"id":"p306","src":"practica","bat":[],"t":"accidentes","q":"Un herido presenta una hemorragia abundante en un brazo. ¿Qué es lo primero que debe hacer?","o":["Ponerle un torniquete inmediatamente.","Presionar directamente sobre la herida con un apósito o tela limpia.","Darle agua."],"c":1,"img":null,"e":"La compresión directa sobre la herida es la técnica básica para detener una hemorragia. El torniquete se reserva para casos extremos y por personal formado.","r":"Manual DGT, primeros auxilios","k":null,"d":0,"rev":null},{"id":"p307","src":"practica","bat":[],"t":"accidentes","q":"¿Se debe quitar el casco a un motorista herido?","o":["Sí, siempre, para que respire mejor.","Sí, si se queja de dolor.","No, salvo que sea imprescindible para mantenerle con vida y por alguien que sepa hacerlo."],"c":2,"img":null,"e":"Quitar el casco puede agravar una lesión cervical. Solo debe retirarse si es imprescindible (por ejemplo, porque no respira o vomita) y siguiendo la técnica adecuada.","r":"Manual DGT, primeros auxilios","k":null,"d":0,"rev":null},{"id":"p308","src":"practica","bat":[],"t":"accidentes","q":"¿Se puede dar de beber a un herido?","o":["No.","Sí, agua.","Sí, una bebida alcohólica para reanimarlo."],"c":0,"img":null,"e":"No se debe dar de beber ni de comer a un herido: puede necesitar una intervención y podría atragantarse si pierde la consciencia.","r":"Manual DGT, primeros auxilios","k":null,"d":0,"rev":null},{"id":"p309","src":"practica","bat":[],"t":"accidentes","q":"Un herido tiene una quemadura y la ropa pegada a la piel. ¿Qué hace?","o":["Arrancar la ropa para limpiar la zona.","No despegar la ropa adherida y enfriar la quemadura con agua.","Aplicar aceite."],"c":1,"img":null,"e":"No hay que despegar la ropa adherida a la quemadura. Se enfría con agua abundante y se cubre con un paño limpio. No se aplican pomadas ni remedios caseros.","r":"Manual DGT, primeros auxilios","k":null,"d":0,"rev":null},{"id":"p310","src":"practica","bat":[],"t":"accidentes","q":"Al llegar a un accidente en una carretera, antes de bajar del vehículo debe…","o":["hacer una foto.","bajar rápido para ayudar.","ponerse el chaleco reflectante."],"c":2,"img":null,"e":"Antes de salir del vehículo en una vía interurbana hay que ponerse el chaleco reflectante para ser visible. Antes, se estaciona en un lugar seguro y se enciende la señal de emergencia.","r":"RGC, art. 118","k":null,"d":0,"rev":null},{"id":"p311","src":"practica","bat":[],"t":"accidentes","q":"Desde el 1 de enero de 2026, ¿cómo se preseñaliza un vehículo inmovilizado en la calzada?","o":["Con la baliza V-16 conectada.","Con los dos triángulos.","Con la luz antiniebla trasera."],"c":0,"img":null,"e":"Desde el 1 de enero de 2026 es obligatoria la baliza V-16 conectada a la plataforma DGT 3.0, que sustituye a los triángulos.","r":"RD 159/2021","k":null,"d":0,"rev":null},{"id":"p312","src":"practica","bat":[],"t":"accidentes","q":"No prestar ayuda a una persona herida y en peligro grave, pudiendo hacerlo sin riesgo propio…","o":["no tiene consecuencias.","puede ser delito de omisión del deber de socorro.","solo es una falta de educación."],"c":1,"img":null,"e":"El Código Penal castiga a quien no socorre a una persona desamparada y en peligro grave cuando puede hacerlo sin riesgo propio ni de terceros, o no pide auxilio.","r":"Código Penal, art. 195","k":null,"d":0,"rev":null},{"id":"p313","src":"practica","bat":[],"t":"accidentes","q":"¿Para qué sirve la declaración amistosa de accidente (parte amistoso)?","o":["Para pagar las multas.","Para avisar al 112.","Para que los conductores implicados describan juntos cómo ocurrió el accidente ante sus aseguradoras."],"c":2,"img":null,"e":"El parte amistoso recoge de mutuo acuerdo los datos de los vehículos, conductores y circunstancias del accidente para que las aseguradoras gestionen los daños.","r":"Práctica aseguradora","k":null,"d":0,"rev":null},{"id":"p314","src":"practica","bat":[],"t":"accidentes","q":"Un herido está consciente, pálido, sudoroso y con el pulso acelerado. ¿Qué puede indicar?","o":["Un shock: hay que abrigarle, tranquilizarle y avisar al 112.","Que tiene calor.","Que está bien."],"c":0,"img":null,"e":"Palidez, sudor frío y pulso rápido pueden indicar un estado de shock. Hay que abrigarle, tranquilizarle, no darle de beber y avisar a los servicios de emergencia.","r":"Manual DGT, primeros auxilios","k":null,"d":0,"rev":null},{"id":"p401","src":"practica","bat":[],"t":"senales","q":"¿Qué indica esta señal?","o":["Velocidad máxima recomendada de 90 km/h.","Prohibido circular a más de 90 km/h.","Velocidad mínima obligatoria de 90 km/h."],"c":1,"img":"img/senales/r301-90.svg","e":"Las señales circulares de borde rojo prohíben. Con un número, prohíben superar esa velocidad. La velocidad mínima se indica con un círculo azul y la recomendada con un cuadrado azul.","r":"RGC, art. 154 (R-301)","k":null,"d":0,"rev":null},{"id":"p402","src":"practica","bat":[],"t":"senales","q":"¿Qué significa esta señal?","o":["Velocidad mínima: obliga a circular al menos a 60 km/h, salvo causa justificada.","Velocidad máxima de 60 km/h.","Velocidad aconsejada de 60 km/h."],"c":0,"img":"img/senales/r411-60.svg","e":"Las señales circulares de fondo azul son de obligación. Con un número indican la velocidad mínima a la que hay que circular, salvo que las circunstancias lo impidan.","r":"RGC, art. 155 (R-411)","k":"Rojo prohíbe pasar de; azul obliga a llegar a.","d":1,"rev":null},{"id":"p403","src":"practica","bat":[],"t":"senales","q":"¿Qué indica esta señal?","o":["Que está prohibido estacionar.","Que la entrada está prohibida solo a camiones.","Que está prohibida la circulación de toda clase de vehículos en ambos sentidos."],"c":2,"img":"img/senales/r100.svg","e":"El círculo blanco con borde rojo y sin símbolo prohíbe la circulación de cualquier vehículo en ambos sentidos. No confundir con la entrada prohibida (fondo rojo con barra blanca).","r":"RGC, art. 154 (R-100)","k":null,"d":0,"rev":null},{"id":"p404","src":"practica","bat":[],"t":"senales","q":"¿Qué indica esta señal?","o":["Entrada prohibida a toda clase de vehículos.","Calle sin salida.","Prohibido parar."],"c":0,"img":"img/senales/r101.svg","e":"La señal de entrada prohibida (fondo rojo con una franja blanca horizontal) prohíbe el acceso a todos los vehículos por ese lado; suele marcar el final de una calle de sentido único.","r":"RGC, art. 154 (R-101)","k":null,"d":0,"rev":null},{"id":"p405","src":"practica","bat":[],"t":"senales","q":"¿Qué prohíbe esta señal?","o":["Girar a la izquierda.","Girar a la derecha.","Cambiar de sentido."],"c":1,"img":"img/senales/r302.svg","e":"La flecha que gira a la derecha, tachada, prohíbe girar a la derecha en la próxima intersección.","r":"RGC, art. 154 (R-302)","k":null,"d":0,"rev":null},{"id":"p406","src":"practica","bat":[],"t":"senales","q":"Ante esta señal, ¿qué maniobra no puede hacer en la próxima intersección?","o":["Seguir recto.","Girar a la derecha.","Girar a la izquierda."],"c":2,"img":"img/senales/r303.svg","e":"La señal prohíbe girar a la izquierda. Seguir recto o girar a la derecha están permitidos si no hay otra prohibición.","r":"RGC, art. 154 (R-303)","k":null,"d":0,"rev":null},{"id":"p407","src":"practica","bat":[],"t":"senales","q":"¿Qué indica esta señal?","o":["Adelantamiento prohibido a partir de la señal.","Prohibido circular a dos turismos juntos.","Adelantamiento permitido solo a turismos."],"c":0,"img":"img/senales/r305.svg","e":"Prohíbe adelantar a los vehículos de motor que circulen por la calzada, salvo a los de dos ruedas, desde la señal hasta la de fin de prohibición. Adelantar a ciclos o ciclomotores de dos ruedas sí está permitido si se hace con seguridad.","r":"RGC, art. 154 (R-305)","k":null,"d":1,"rev":null},{"id":"p408","src":"practica","bat":[],"t":"senales","q":"¿Qué significa esta señal?","o":["Prohibido adelantar.","Fin de todas las prohibiciones impuestas antes por señales a los vehículos en movimiento.","Zona de obras."],"c":1,"img":"img/senales/r500.svg","e":"El círculo blanco con franjas diagonales grises y una banda negra indica el fin de todas las prohibiciones específicas señalizadas para vehículos en movimiento.","r":"RGC, art. 154 (R-500)","k":null,"d":0,"rev":null},{"id":"p409","src":"practica","bat":[],"t":"senales","q":"Tras pasar esta señal, ¿qué velocidad máxima debe respetar?","o":["60 km/h.","Ninguna: no hay límite.","La genérica de la vía y del vehículo, salvo otra señal."],"c":2,"img":"img/senales/r501-60.svg","e":"Indica el fin de la limitación de 60 km/h. A partir de ella rige la velocidad genérica correspondiente a la vía y al vehículo, no «sin límite».","r":"RGC, art. 154 (R-501)","k":null,"d":1,"rev":null},{"id":"p410","src":"practica","bat":[],"t":"senales","q":"¿Qué indica esta señal?","o":["Obligación de seguir en la dirección que indica la flecha.","Recomendación de girar a la derecha.","Que la vía de la derecha tiene prioridad."],"c":0,"img":"img/senales/r400.svg","e":"Las señales circulares azules son de obligación: la flecha indica la única dirección que se puede tomar.","r":"RGC, art. 155 (R-400)","k":null,"d":0,"rev":null},{"id":"p411","src":"practica","bat":[],"t":"senales","q":"¿Qué indica esta señal, colocada sobre una isleta o un obstáculo?","o":["Que está prohibido pasar por la derecha.","Que es obligatorio pasar por el lado que indica la flecha.","Que hay una curva peligrosa."],"c":1,"img":"img/senales/r401.svg","e":"Es una señal de paso obligatorio: obliga a dejar el obstáculo o la isleta por el lado que indica la flecha.","r":"RGC, art. 155 (R-401)","k":null,"d":0,"rev":null},{"id":"p412","src":"practica","bat":[],"t":"senales","q":"Circula en el sentido de la flecha blanca y llega a un estrechamiento con esta señal. ¿Quién tiene preferencia?","o":["Los vehículos que vienen en sentido contrario.","Quien llegue primero.","Usted, frente a los que vienen en sentido contrario."],"c":2,"img":"img/senales/r6.svg","e":"El cuadrado azul con la flecha blanca grande hacia arriba indica prioridad respecto al sentido contrario: usted pasa primero. La flecha roja es la del sentido que debe ceder.","r":"RGC, art. 151 (R-6)","k":"Cuadrado azul = te favorece; círculo con borde rojo = te obliga a ceder.","d":1,"rev":null},{"id":"p413","src":"practica","bat":[],"t":"senales","q":"¿Qué advierte esta señal?","o":["Intersección con prioridad: usted tiene preferencia sobre la vía que cruza.","Intersección en la que debe ceder el paso.","Hospital próximo."],"c":0,"img":"img/senales/p1.svg","e":"La señal de peligro con una cruz cuyo trazo vertical es más grueso advierte de una intersección en la que la vía por la que usted circula tiene prioridad sobre la otra.","r":"RGC, art. 149 (P-1)","k":null,"d":0,"rev":null},{"id":"p414","src":"practica","bat":[],"t":"senales","q":"¿Qué advierte esta señal?","o":["Un paso a nivel.","La proximidad de una intersección o tramo regulado por semáforos.","Que el semáforo está averiado."],"c":1,"img":"img/senales/p3.svg","e":"Avisa de que más adelante hay semáforos, normalmente en lugares donde el conductor no espera encontrarlos.","r":"RGC, art. 149 (P-3)","k":null,"d":0,"rev":null},{"id":"p415","src":"practica","bat":[],"t":"senales","q":"¿Qué advierte esta señal?","o":["Un cambio de sentido obligatorio.","Que hay que dar la vuelta.","Una intersección con circulación giratoria (glorieta)."],"c":2,"img":"img/senales/p4.svg","e":"Advierte de la proximidad de una intersección donde la circulación se realiza de forma giratoria, en el sentido de las flechas. No confundir con la señal circular azul, que obliga a ese sentido de giro.","r":"RGC, art. 149 (P-4)","k":null,"d":0,"rev":null},{"id":"p416","src":"practica","bat":[],"t":"senales","q":"¿Qué advierte esta señal?","o":["Una curva peligrosa hacia la derecha.","Que es obligatorio girar a la derecha.","Un desvío por obras."],"c":0,"img":"img/senales/p13a.svg","e":"La señal triangular con una flecha curvada advierte de una curva peligrosa en el sentido indicado. Hay que adecuar la velocidad antes de llegar a ella.","r":"RGC, art. 149 (P-13a)","k":null,"d":0,"rev":null},{"id":"p417","src":"practica","bat":[],"t":"senales","q":"¿Qué peligro anuncia esta señal?","o":["Un puente móvil.","Un estrechamiento de la calzada.","Un carril adicional."],"c":1,"img":"img/senales/p17.svg","e":"Advierte de que la calzada se estrecha más adelante. Hay que moderar la velocidad y prestar atención a los vehículos que vienen de frente.","r":"RGC, art. 149 (P-17)","k":null,"d":0,"rev":null},{"id":"p418","src":"practica","bat":[],"t":"senales","q":"¿Qué indica esta señal?","o":["Prohibido el paso.","Final de la vía.","Un peligro distinto de los indicados por otras señales; suele llevar un panel que lo explica."],"c":2,"img":"img/senales/p50.svg","e":"Es la señal de «otros peligros». Avisa de un peligro que no tiene señal propia; un panel complementario suele indicar cuál es.","r":"RGC, art. 149 (P-50)","k":null,"d":0,"rev":null},{"id":"p419","src":"practica","bat":[],"t":"senales","q":"Ante esta señal, sin vehículos a la vista, ¿qué debe hacer?","o":["Detenerse por completo y después continuar con precaución.","Reducir la velocidad y pasar sin detenerse.","Detenerse solo de noche."],"c":0,"img":"img/senales/r2.svg","e":"La señal de stop obliga siempre a detenerse por completo antes de la línea de detención, aunque no venga nadie, y después ceder el paso.","r":"RGC, art. 151 (R-2)","k":null,"d":0,"rev":null},{"id":"p420","src":"practica","bat":[],"t":"senales","q":"¿Qué obliga a hacer esta señal?","o":["A detenerse siempre.","A ceder el paso a los vehículos que circulen por la vía a la que se aproxima.","A girar a la derecha."],"c":1,"img":"img/senales/r1.svg","e":"El triángulo invertido obliga a ceder el paso. Solo hay que detenerse si es necesario para ceder el paso.","r":"RGC, art. 151 (R-1)","k":null,"d":0,"rev":null},{"id":"p421","src":"practica","bat":[],"t":"senales","q":"¿Qué prohíbe esta señal?","o":["Solo el estacionamiento.","La circulación.","La parada y el estacionamiento."],"c":2,"img":"img/senales/r307.svg","e":"El aspa roja sobre fondo azul prohíbe parar y estacionar en el lado de la vía donde está la señal.","r":"RGC, art. 154 (R-307)","k":"Aspa: ni paro ni aparco.","d":0,"rev":null},{"id":"p422","src":"practica","bat":[],"t":"senales","q":"¿Qué prohíbe esta señal?","o":["El estacionamiento, pero se permite la parada.","La parada y el estacionamiento.","La circulación de turismos."],"c":0,"img":"img/senales/r308.svg","e":"La franja diagonal roja sobre fondo azul prohíbe estacionar, pero permite parar (menos de dos minutos sin abandonar el vehículo).","r":"RGC, art. 154 (R-308)","k":"Una raya: paro pero no aparco.","d":0,"rev":null},{"id":"p423","src":"practica","bat":[],"t":"senales","q":"¿Qué indica esta señal circular azul?","o":["Que se aproxima una glorieta, sin más obligación.","Intersección de sentido giratorio obligatorio: hay que circular en el sentido de las flechas.","Que está prohibido cambiar de sentido."],"c":1,"img":"img/senales/r402.svg","e":"Es una señal de obligación: en la intersección hay que circular en el sentido que indican las flechas.","r":"RGC, art. 155 (R-402)","k":null,"d":0,"rev":null},{"id":"p424","src":"practica","bat":[],"t":"senales","q":"¿Qué indica esta señal cuadrada azul?","o":["Que está prohibido el paso de peatones.","Una zona escolar.","La situación de un paso para peatones."],"c":2,"img":"img/senales/s13.svg","e":"Las señales cuadradas o rectangulares azules son de indicación. Esta indica dónde está un paso para peatones, en el que estos tienen preferencia.","r":"RGC, art. 159 (S-13)","k":null,"d":0,"rev":null},{"id":"p425","src":"practica","bat":[],"t":"senales","q":"Esta señal está en una calle de un carril por sentido. ¿Qué significa?","o":["Que no se puede superar los 30 km/h.","Que hay que circular exactamente a 30 km/h.","Que se recomiendan 30 km/h."],"c":0,"img":"img/senales/r301-30.svg","e":"Prohíbe superar los 30 km/h, que además es el límite genérico de las vías urbanas con un carril por sentido. No obliga a circular a esa velocidad.","r":"RGC, arts. 50 y 154","k":null,"d":0,"rev":null},{"id":"p426","src":"practica","bat":[],"t":"senales","q":"Esta señal está en una autovía. Usted conduce un turismo con remolque. ¿Puede circular a 120 km/h?","o":["Sí, porque lo indica la señal.","No: debe respetar el límite más bajo, que es el genérico de su vehículo.","Sí, si el remolque está vacío."],"c":1,"img":"img/senales/r301-120.svg","e":"La señal fija un máximo para la vía, pero cada vehículo tiene además su límite genérico. Siempre se aplica el más restrictivo, y el de un turismo con remolque es inferior a 120 km/h.","r":"RGC, art. 48","k":null,"d":1,"rev":null},{"id":"p427","src":"practica","bat":[],"t":"senales","q":"Pasa una señal de velocidad máxima de 50 km/h. Si no hay otra señal que la anule, ¿hasta dónde rige en general?","o":["Hasta la siguiente intersección o hasta una señal que la anule.","Hasta el final de la carretera.","Solo 100 metros."],"c":0,"img":"img/senales/r301-50.svg","e":"Las prohibiciones de las señales verticales rigen, en general, desde la señal hasta la próxima intersección o hasta otra señal que establezca el fin o un límite distinto.","r":"RGC, art. 154","k":null,"d":1,"rev":null},{"id":"p428","src":"practica","bat":[],"t":"senales","q":"¿Qué advierte esta señal?","o":["Un paso para peatones regulado por semáforo.","La proximidad de un lugar frecuentado por peatones o un paso para peatones.","Una calle peatonal en la que no se puede entrar."],"c":1,"img":"img/senales/p20.svg","e":"Avisa de la proximidad de un paso para peatones o de un lugar con presencia frecuente de peatones. Hay que moderar la velocidad y extremar la atención.","r":"RGC, art. 149 (P-20)","k":null,"d":0,"rev":null},{"id":"p429","src":"practica","bat":[],"t":"senales","q":"Esta señal está en una calle donde acera y calzada están al mismo nivel. ¿Qué debe hacer?","o":["Circular a 30 km/h, que es el límite urbano.","Circular a 20 km/h como mínimo.","No superar los 20 km/h y respetar la prioridad de los peatones."],"c":2,"img":"img/senales/r301-20.svg","e":"Las vías de plataforma única tienen un límite de 20 km/h y, desde la reforma de 2026, los peatones tienen prioridad en ellas.","r":"RGC, art. 50 (RD 518/2026)","k":null,"d":0,"rev":null},{"id":"p430","src":"practica","bat":[],"t":"senales","q":"Hay una retención en el carril y no puede llegar a la velocidad que indica esta señal. ¿Comete una infracción?","o":["No, porque existe una causa justificada.","Sí, siempre.","Sí, salvo que encienda la señal de emergencia."],"c":0,"img":"img/senales/r411-60.svg","e":"La velocidad mínima obliga salvo que las circunstancias del tráfico, de la vía o meteorológicas lo impidan. Una retención es una causa justificada.","r":"RGC, arts. 49 y 155","k":null,"d":0,"rev":null},{"id":"p501","src":"practica","bat":[],"t":"prioridad","q":"Usted conduce el vehículo A. En esta intersección no hay señales ni agentes. ¿Quién pasa primero?","o":["A, porque va recto.","B, porque se aproxima por la derecha de A.","El que llegue antes."],"c":1,"img":"img/escenas/e01.svg","e":"Sin señales ni agentes se cede el paso a quien se aproxima por la derecha. B viene por la derecha de A, así que B pasa primero.","r":"RGC, art. 57.1","k":null,"d":0,"rev":null},{"id":"p502","src":"practica","bat":[],"t":"prioridad","q":"Usted conduce el vehículo A. No hay señales. El vehículo C se acerca por su izquierda. ¿Quién pasa primero?","o":["A, porque C debe cederle el paso al tenerle a su derecha.","C, porque circula por una vía más ancha.","C, porque llega por la izquierda."],"c":0,"img":"img/escenas/e02.svg","e":"Para C, el vehículo A se aproxima por su derecha, así que C debe cederle el paso. A pasa primero.","r":"RGC, art. 57.1","k":null,"d":0,"rev":null},{"id":"p503","src":"practica","bat":[],"t":"prioridad","q":"En esta intersección sin señalizar los tres vehículos siguen recto. ¿En qué orden pasan?","o":["A, B y C.","C, A y B.","B, A y C."],"c":2,"img":"img/escenas/e03.svg","e":"B no tiene a nadie a su derecha, así que pasa primero. Después A, que solo tenía que esperar a B. Por último C, que tiene a A a su derecha.","r":"RGC, art. 57.1","k":"Busca al que no tiene a nadie a su derecha: ese empieza.","d":1,"rev":null},{"id":"p504","src":"practica","bat":[],"t":"prioridad","q":"Usted conduce A y tiene una señal de stop. El vehículo C llega por su izquierda. ¿Qué debe hacer?","o":["Pasar primero, porque C viene por la izquierda.","Detenerse y ceder el paso a C.","Pasar sin detenerse si C está lejos."],"c":1,"img":"img/escenas/e04.svg","e":"La señal prevalece sobre la regla general: con un stop hay que detenerse siempre y ceder el paso a quien circula por la otra vía, venga por la derecha o por la izquierda.","r":"RGC, arts. 56 y 151","k":null,"d":1,"rev":null},{"id":"p505","src":"practica","bat":[],"t":"prioridad","q":"Usted conduce A y va a girar a la izquierda. El vehículo D viene de frente y sigue recto. No hay señales. ¿Quién pasa primero?","o":["A, porque ya ha señalizado el giro.","Pasan a la vez.","D, porque A debe ceder el paso a los vehículos que vienen de frente cuando gira a la izquierda."],"c":2,"img":"img/escenas/e05.svg","e":"Quien gira a la izquierda debe ceder el paso a los vehículos que circulan en sentido contrario. Señalizar no da preferencia.","r":"RGC, cambios de dirección (cesión de paso al girar a la izquierda)","k":null,"d":0,"rev":null},{"id":"p506","src":"practica","bat":[],"t":"prioridad","q":"El vehículo B sale de un camino de tierra por la derecha de A, que circula por una vía asfaltada. ¿Quién pasa primero?","o":["A, porque circula por una vía pavimentada.","B, porque viene por la derecha.","El más rápido."],"c":0,"img":"img/escenas/e06.svg","e":"Quien circula por una vía pavimentada tiene preferencia sobre quien sale de una sin pavimentar, aunque este venga por la derecha.","r":"RGC, art. 57.1.a","k":null,"d":1,"rev":null},{"id":"p507","src":"practica","bat":[],"t":"prioridad","q":"Usted conduce A y va a entrar en la glorieta. El vehículo B ya circula por ella. ¿Qué debe hacer?","o":["Entrar, porque B viene por su izquierda.","Ceder el paso a B.","Tocar la bocina y entrar."],"c":1,"img":"img/escenas/e07.svg","e":"Los vehículos que ya circulan por la glorieta tienen preferencia sobre los que van a entrar, y además A tiene una señal de ceda el paso.","r":"RGC, art. 57.1.c","k":null,"d":0,"rev":null},{"id":"p508","src":"practica","bat":[],"t":"prioridad","q":"Usted conduce A. Por su izquierda se acerca una ambulancia (B) con las luces y la sirena encendidas. ¿Quién pasa primero?","o":["A, porque la ambulancia viene por la izquierda.","Quien llegue antes.","La ambulancia: hay que facilitarle el paso."],"c":2,"img":"img/escenas/e08.svg","e":"Un vehículo prioritario en servicio de urgencia, con las señales luminosas y acústicas encendidas, tiene preferencia aunque venga por la izquierda. Hay que facilitarle el paso.","r":"RGC, arts. 67 y 68","k":null,"d":0,"rev":null},{"id":"p509","src":"practica","bat":[],"t":"prioridad","q":"Usted conduce A. Un tranvía (B) se acerca por su izquierda a la intersección sin señalizar. ¿Quién pasa primero?","o":["El tranvía.","A, porque el tranvía viene por la izquierda.","Quien llegue antes."],"c":0,"img":"img/escenas/e09.svg","e":"Los vehículos que circulan sobre raíles tienen preferencia en las intersecciones sin señalizar, vengan por donde vengan.","r":"RGC, art. 57.1.b","k":null,"d":0,"rev":null},{"id":"p510","src":"practica","bat":[],"t":"prioridad","q":"Usted conduce A y sale de un garaje a la calle. El vehículo B circula por la calle. ¿Qué debe hacer?","o":["Salir primero, porque B le ve.","Ceder el paso a B y a los peatones de la acera.","Salir marcha atrás."],"c":1,"img":"img/escenas/e10.svg","e":"Quien se incorpora a la circulación desde un inmueble o garaje debe ceder el paso a los vehículos que circulan por la vía y a los peatones que pasan por la acera.","r":"RGC, art. 72","k":null,"d":0,"rev":null},{"id":"p511","src":"practica","bat":[],"t":"circulacion","q":"¿Está permitido circular por el carril izquierdo de una autovía si el derecho está libre?","o":["Sí, si va al límite de velocidad.","No: hay que circular por el carril derecho y usar los demás para adelantar.","Sí, de noche."],"c":1,"img":null,"e":"Fuera de poblado se circula por el carril de la derecha. Ocupar el carril izquierdo sin necesidad entorpece y es sancionable.","r":"RGC, art. 31","k":null,"d":0,"rev":null},{"id":"p512","src":"practica","bat":[],"t":"velocidad","q":"Una señal limita a 80 km/h en una autovía. ¿Hasta qué velocidad puede circular un turismo?","o":["Hasta 120 km/h, el límite genérico.","Hasta 100 km/h.","Hasta 80 km/h."],"c":2,"img":null,"e":"Las señales de velocidad máxima prevalecen sobre los límites genéricos de la vía. Si la señal marca 80, ese es el máximo.","r":"RGC, arts. 48 y 154","k":null,"d":0,"rev":null},{"id":"p513","src":"practica","bat":[],"t":"estacionamiento","q":"Para dejar a un pasajero, ¿puede detenerse 30 segundos en doble fila con el conductor dentro?","o":["No, también está prohibido parar en doble fila.","Sí, porque es una parada de menos de dos minutos.","Sí, si enciende la emergencia."],"c":0,"img":null,"e":"La parada en doble fila está prohibida aunque sea breve y el conductor no abandone el vehículo. La señal de emergencia no lo legaliza.","r":"RGC, art. 94","k":null,"d":1,"rev":null},{"id":"p514","src":"practica","bat":[],"t":"alumbrado","q":"Circula de día por un túnel bien iluminado. ¿Debe llevar alguna luz encendida?","o":["No, porque está iluminado.","Solo la de posición.","Sí, al menos la de corto alcance."],"c":2,"img":null,"e":"En túneles y pasos inferiores señalizados es obligatorio llevar al menos la luz de corto alcance, aunque estén iluminados.","r":"RGC, art. 104","k":null,"d":1,"rev":null},{"id":"p515","src":"practica","bat":[],"t":"adelantamiento","q":"El vehículo que le precede circula a 70 km/h en una carretera de 90 km/h. Para adelantarle, ¿puede llegar a 100 km/h?","o":["No, nunca se puede superar el límite.","Sí, porque el margen para adelantar es de 20 km/h.","Sí, durante 15 segundos."],"c":0,"img":null,"e":"El margen de 20 km/h para adelantar desapareció en 2019. Si no puede adelantar sin superar el límite, no adelante.","r":"RGC, art. 48","k":null,"d":1,"rev":null},{"id":"p516","src":"practica","bat":[],"t":"alcohol","q":"Lleva un año con el carné y le hacen un control. Da 0,20 mg/l en aire espirado. ¿Comete una infracción?","o":["No, porque el límite es 0,25.","Sí, porque como novel su límite es 0,15 mg/l.","Solo si conduce de noche."],"c":1,"img":null,"e":"Durante los dos primeros años de permiso la tasa máxima es 0,15 mg/l en aire espirado. Con 0,20 se supera.","r":"RGC, art. 20","k":null,"d":1,"rev":null},{"id":"p517","src":"practica","bat":[],"t":"senales","q":"Un agente le indica que siga, pero el semáforo está en rojo. ¿Qué hace?","o":["Se detiene, porque el semáforo es automático.","Espera a que cambie a verde.","Obedece al agente."],"c":2,"img":null,"e":"Las indicaciones de los agentes prevalecen sobre cualquier otra señal, semáforos incluidos.","r":"RGC, art. 133","k":"Agente manda sobre todo.","d":0,"rev":null},{"id":"p518","src":"practica","bat":[],"t":"senales","q":"Hay una línea continua y una señal de obras amarilla que permite adelantar. ¿Qué prevalece?","o":["La señal de obras, porque la señalización circunstancial prevalece sobre las marcas viales.","La línea continua, porque está en el suelo.","Ninguna: está prohibido circular."],"c":0,"img":null,"e":"El orden de prevalencia es: agentes, señalización circunstancial, semáforos, señales verticales y marcas viales. La señalización de obras va por delante de las marcas.","r":"RGC, art. 133","k":null,"d":1,"rev":null},{"id":"p519","src":"practica","bat":[],"t":"documentacion","q":"Le han retirado el permiso por pérdida total de puntos y conduce igualmente. ¿Qué comete?","o":["Una infracción leve.","Un delito.","Nada si no tiene accidentes."],"c":1,"img":null,"e":"Conducir tras perder la vigencia del permiso por pérdida total de puntos es un delito contra la seguridad vial.","r":"Código Penal, art. 384","k":null,"d":0,"rev":null},{"id":"p520","src":"practica","bat":[],"t":"seguridad","q":"En un trayecto de 5 minutos por ciudad, ¿deben los pasajeros de atrás usar el cinturón?","o":["No, solo en carretera.","Solo los niños.","Sí, siempre."],"c":2,"img":null,"e":"El cinturón es obligatorio en todos los asientos que lo tengan, en vías urbanas e interurbanas y sea cual sea la distancia. La mayoría de accidentes ocurren en trayectos cortos y conocidos.","r":"RGC, art. 117","k":null,"d":0,"rev":null},{"id":"p521","src":"practica","bat":[],"t":"maniobras","q":"Se ha pasado la salida de la autovía. ¿Qué debe hacer?","o":["Seguir hasta la siguiente salida.","Dar marcha atrás por el arcén con precaución.","Detenerse en el arcén y esperar."],"c":0,"img":null,"e":"En autopistas y autovías la marcha atrás y el cambio de sentido están prohibidos salvo en los lugares habilitados. Hay que continuar hasta la siguiente salida.","r":"RGC, arts. 79 y 80","k":null,"d":0,"rev":null},{"id":"p522","src":"practica","bat":[],"t":"factor","q":"Lleva dos horas conduciendo y se siente bien. ¿Qué es lo recomendable?","o":["Seguir, porque no está cansado.","Parar unos minutos a descansar igualmente.","Tomar un café y seguir sin parar."],"c":1,"img":null,"e":"La fatiga aparece antes de que se note. La recomendación es descansar cada dos horas o 200 km, aunque uno se encuentre bien.","r":"Recomendaciones DGT","k":null,"d":0,"rev":null},{"id":"p523","src":"practica","bat":[],"t":"accidentes","q":"Llega el primero a un accidente con heridos. ¿Qué es lo primero que debe hacer?","o":["Sacar a los heridos de los vehículos.","Llamar al 112 sin bajar del coche.","Proteger la zona para evitar nuevos accidentes."],"c":2,"img":null,"e":"La conducta PAS empieza por Proteger: estacionar en lugar seguro, señal de emergencia, chaleco y V-16. Después Avisar y, por último, Socorrer. Mover a los heridos puede agravar sus lesiones.","r":"Manual DGT, primeros auxilios","k":null,"d":0,"rev":null},{"id":"p524","src":"practica","bat":[],"t":"mantenimiento","q":"Las ruedas delanteras están más gastadas que las traseras. Al cambiar solo dos neumáticos nuevos, ¿dónde se recomienda montarlos?","o":["En el eje trasero.","Da igual.","En el eje delantero siempre."],"c":0,"img":null,"e":"Los fabricantes recomiendan montar los neumáticos nuevos o en mejor estado en el eje trasero, porque así el coche conserva la estabilidad y es menos propenso a derrapar de atrás en curva o con agua.","r":"Recomendaciones de fabricantes de neumáticos","k":null,"d":1,"rev":null},{"id":"p525","src":"practica","bat":[],"t":"eficiente","q":"¿Qué consume menos al bajar un puerto de montaña?","o":["Ir en punto muerto.","Ir con una marcha engranada sin pisar el acelerador.","Ir en la marcha más larga pisando un poco el acelerador."],"c":1,"img":null,"e":"Con una marcha engranada y sin acelerar, la inyección se corta y el consumo es prácticamente cero; además el freno motor ayuda a no recalentar los frenos.","r":"IDAE, conducción eficiente","k":null,"d":0,"rev":null},{"id":"p601","src":"practica","bat":[],"t":"documentacion","q":"Con el permiso B, ¿puede arrastrar un remolque de 1.000 kg de MMA con un turismo de 2.000 kg de MMA?","o":["Sí, porque el conjunto no supera los 3.500 kg.","No, porque el remolque supera los 750 kg.","Solo si el remolque va vacío."],"c":0,"img":null,"e":"El permiso B permite remolques de más de 750 kg siempre que la MMA del conjunto no supere los 3.500 kg. Aquí son 3.000 kg. La MMA cuenta aunque el remolque vaya vacío.","r":"RGCond, art. 4","k":"Remolque ligero (≤750 kg): siempre. Más pesado: el conjunto ≤3.500 kg.","d":1,"rev":null},{"id":"p602","src":"practica","bat":[],"t":"documentacion","q":"Con el permiso B, ¿puede arrastrar un remolque de 750 kg de MMA con un turismo de 3.200 kg de MMA?","o":["No, porque el conjunto supera los 3.500 kg.","Sí, porque el remolque no supera los 750 kg.","Solo con el permiso BE."],"c":1,"img":null,"e":"Un remolque de hasta 750 kg de MMA se puede llevar con el permiso B sea cual sea el conjunto, siempre que el vehículo tractor sea de la clase B. El límite de 3.500 kg del conjunto solo se aplica a remolques de más de 750 kg.","r":"RGCond, art. 4","k":null,"d":1,"rev":null},{"id":"p603","src":"practica","bat":[],"t":"alcohol","q":"Un taxista conduce su turismo particular un domingo, fuera de su trabajo. ¿Qué tasa máxima de alcohol en aire espirado se le aplica?","o":["0,15 mg/l, porque es conductor profesional.","0,00 mg/l.","0,25 mg/l, la general, porque no conduce un vehículo de servicio público."],"c":2,"img":null,"e":"La tasa reducida de profesionales depende del vehículo que se conduce (servicio público, transporte de viajeros o mercancías, urgencias…), no de la profesión. Con su coche particular rige la general, salvo que sea novel.","r":"RGC, art. 20","k":null,"d":1,"rev":null},{"id":"p604","src":"practica","bat":[],"t":"seguridad","q":"Un niño de 10 años mide 140 cm. ¿Puede viajar en el asiento delantero?","o":["Sí, utilizando el cinturón de seguridad.","No, ningún menor de 12 años puede ir delante.","Solo con una silla infantil."],"c":0,"img":null,"e":"La norma no se basa en la edad sino en la estatura: los menores de 135 cm o menos deben ir detrás en un sistema de retención. Con 140 cm puede viajar delante con el cinturón.","r":"RGC, art. 117","k":null,"d":1,"rev":null},{"id":"p605","src":"practica","bat":[],"t":"seguridad","q":"¿En qué caso puede viajar delante un niño de 120 cm, en su sistema de retención?","o":["Nunca.","Si los asientos traseros están ocupados por otros menores de su estatura o no se puede instalar allí el sistema de retención.","Si el viaje es corto y urbano."],"c":1,"img":null,"e":"Excepcionalmente puede viajar delante, con su sistema de retención homologado, si el vehículo no tiene asientos traseros, si todos están ocupados por menores de 135 cm o menos, o si no es posible instalar en ellos el sistema.","r":"RGC, art. 117","k":null,"d":1,"rev":null},{"id":"p606","src":"practica","bat":[],"t":"estacionamiento","q":"Se detiene ante un semáforo en rojo. ¿Cómo se llama esa inmovilización?","o":["Parada.","Estacionamiento.","Detención."],"c":2,"img":null,"e":"La detención es la inmovilización por necesidades de la circulación o para cumplir una norma (semáforo, retención, señal). La parada es voluntaria y de menos de dos minutos con el conductor dentro.","r":"Anexo I LSV","k":"Detención: te obligan. Parada: tú quieres, menos de 2 minutos.","d":1,"rev":null},{"id":"p607","src":"practica","bat":[],"t":"senales","q":"Un agente tiene los brazos extendidos horizontalmente. ¿Quiénes deben detenerse?","o":["Los que se acerquen desde direcciones que corten la indicada por los brazos extendidos.","Todos los que se acerquen al agente.","Solo los peatones."],"c":0,"img":null,"e":"Con el brazo o los brazos extendidos horizontalmente deben detenerse quienes se acerquen al agente desde direcciones que corten la línea de los brazos, es decir, los que vienen de frente o por detrás de él.","r":"RGC, art. 143.1.b","k":null,"d":1,"rev":null},{"id":"p608","src":"practica","bat":[],"t":"senales","q":"Un semáforo muestra la luz roja circular y, a la vez, una flecha verde hacia la derecha. ¿Qué puede hacer?","o":["Nada: debe esperar a que se ponga verde.","Girar a la derecha, cediendo el paso a los peatones que crucen.","Seguir recto con precaución."],"c":1,"img":null,"e":"La flecha verde permite seguir en la dirección que indica aunque esté encendida la luz roja. Hay que ceder el paso a los peatones que crucen la vía a la que se gira.","r":"RGC, art. 146","k":null,"d":1,"rev":null},{"id":"p609","src":"practica","bat":[],"t":"velocidad","q":"Fuera de poblado, circula detrás de otro vehículo sin intención de adelantarle. ¿Qué distancia debe dejar?","o":["La mínima posible para que nadie se meta.","No hay ninguna obligación.","La que permita a quien le siga adelantarle y colocarse delante con seguridad."],"c":2,"img":null,"e":"Además de la distancia de seguridad, fuera de poblado quien circula detrás de otro sin intención de adelantar debe dejar un hueco que permita a quien le siga adelantarle con seguridad, salvo en caso de congestión o donde esté prohibido adelantar.","r":"RGC, art. 54","k":null,"d":1,"rev":null},{"id":"p610","src":"practica","bat":[],"t":"velocidad","q":"Circula por una calle urbana de sentido único con dos carriles. ¿Cuál es la velocidad máxima genérica?","o":["50 km/h, porque tiene dos carriles en el mismo sentido.","30 km/h, porque es una calle urbana.","40 km/h."],"c":0,"img":null,"e":"El límite de 30 km/h se aplica a las vías urbanas con un único carril por sentido. Una calle de sentido único con dos carriles tiene dos carriles en ese sentido: el límite genérico es 50 km/h.","r":"RGC, art. 50","k":null,"d":1,"rev":null},{"id":"p611","src":"practica","bat":[],"t":"senales","q":"¿Qué indica una doble línea longitudinal discontinua?","o":["Que está prohibido adelantar.","Un carril reversible, cuyo sentido puede cambiar mediante semáforos de carril.","El borde de la calzada."],"c":1,"img":null,"e":"La doble línea discontinua delimita los carriles reversibles, en los que el sentido de circulación se regula con semáforos de carril. Por ellos hay que llevar encendida la luz de corto alcance.","r":"RGC, art. 167","k":null,"d":1,"rev":null},{"id":"p612","src":"practica","bat":[],"t":"senales","q":"Una flecha blanca oblicua pintada en su carril, apuntando hacia la derecha, indica…","o":["que puede girar a la derecha.","que hay una salida próxima.","que debe volver al carril de la derecha porque se acerca una línea continua o una reducción de carriles."],"c":2,"img":null,"e":"Es una flecha de retorno: avisa de que hay que volver al carril de la derecha, normalmente porque termina la zona donde se permite adelantar.","r":"RGC, art. 169","k":null,"d":1,"rev":null},{"id":"p613","src":"practica","bat":[],"t":"circulacion","q":"¿Cuándo puede circular un turismo por el arcén?","o":["Solo en caso de emergencia o por indicación de los agentes.","Cuando vaya más despacio que el resto.","Para adelantar por la derecha en caso de retención."],"c":0,"img":null,"e":"El arcén es para peatones, ciclos, ciclomotores y vehículos lentos. Los turismos no pueden usarlo para circular salvo en emergencias o por indicación de los agentes, y nunca para adelantar.","r":"RGC, art. 36","k":null,"d":1,"rev":null},{"id":"p614","src":"practica","bat":[],"t":"circulacion","q":"¿Puede llevar como pasajero en una motocicleta a un niño de 8 años?","o":["No, nunca.","Sí, si el conductor es su padre, madre o tutor, o una persona mayor de edad autorizada por ellos, y lleva casco homologado.","Sí, siempre que se agarre bien."],"c":1,"img":null,"e":"Como norma, los menores de 12 años no pueden ir de pasajeros en motocicletas. Se permite a partir de los 7 años si el conductor es su padre, madre o tutor, o un adulto autorizado por ellos, y con casco homologado.","r":"RGC, art. 12","k":null,"d":1,"rev":null},{"id":"p615","src":"practica","bat":[],"t":"seguridad","q":"Una mujer embarazada, ¿está exenta de usar el cinturón de seguridad?","o":["Sí, a partir del sexto mes.","Sí, siempre.","No: debe usarlo, con la banda inferior por debajo del vientre."],"c":2,"img":null,"e":"El embarazo no exime del cinturón. Hay que colocar la banda inferior por debajo del vientre, sobre los huesos de la cadera, y la diagonal entre los pechos.","r":"RGC, art. 117","k":null,"d":1,"rev":null},{"id":"p616","src":"practica","bat":[],"t":"circulacion","q":"Está detenido en un semáforo en rojo. ¿Puede leer un mensaje en el móvil sujetándolo con la mano?","o":["No: el vehículo sigue en circulación y se considera que está conduciendo.","Sí, porque el vehículo está parado.","Sí, si tiene el freno de mano puesto."],"c":0,"img":null,"e":"Detenido en un semáforo o en un atasco el conductor sigue conduciendo. Usar el móvil sujeto con la mano supone 200 € y 6 puntos.","r":"RGC, art. 18.2","k":null,"d":1,"rev":null},{"id":"p617","src":"practica","bat":[],"t":"maniobras","q":"Su turismo se avería. ¿Puede remolcarlo otro turismo con una cuerda hasta el taller?","o":["Sí, si van despacio.","No; los vehículos averiados deben ser remolcados por vehículos destinados a ello, como una grúa.","Sí, si es dentro de poblado."],"c":1,"img":null,"e":"El remolque de vehículos averiados está reservado a vehículos especialmente destinados a ese fin. Hay que llamar a la asistencia en carretera.","r":"RGC (remolque de vehículos averiados)","k":null,"d":1,"rev":null},{"id":"p618","src":"practica","bat":[],"t":"accidentes","q":"Tiene un accidente leve sin heridos y los vehículos obstaculizan la circulación. ¿Qué debe hacer?","o":["No moverlos hasta que llegue la policía.","Dejarlos y llamar a la aseguradora.","Señalizar y apartarlos cuanto antes para restablecer la circulación."],"c":2,"img":null,"e":"Si no hay heridos y los vehículos pueden moverse, hay que señalizar el peligro y apartarlos lo antes posible para no crear nuevos riesgos. Los datos se pueden tomar después en un lugar seguro.","r":"LSV, art. 51; RGC, art. 129","k":null,"d":1,"rev":null},{"id":"p619","src":"practica","bat":[],"t":"accidentes","q":"¿Dónde se coloca la baliza V-16?","o":["En la parte más alta del vehículo, normalmente el techo.","A 50 metros por detrás del vehículo.","En el salpicadero."],"c":0,"img":null,"e":"La V-16 se coloca en la parte más alta del vehículo para que se vea desde lejos, sin necesidad de caminar por la calzada.","r":"RD 159/2021","k":null,"d":1,"rev":null},{"id":"p620","src":"practica","bat":[],"t":"documentacion","q":"No respetar un semáforo en rojo supone…","o":["2 puntos.","4 puntos y 200 €.","6 puntos y 500 €."],"c":1,"img":null,"e":"No respetar la luz roja de un semáforo, una señal de stop o de ceda el paso es una infracción grave con 200 € y pérdida de 4 puntos.","r":"LSV, Anexo II","k":null,"d":1,"rev":null},{"id":"p621","src":"practica","bat":[],"t":"documentacion","q":"Conducir con temeridad manifiesta poniendo en peligro concreto la vida de las personas…","o":["es solo una infracción grave.","es una infracción leve si no hay accidente.","es un delito."],"c":2,"img":null,"e":"La conducción con temeridad manifiesta que ponga en concreto peligro la vida o la integridad de las personas es un delito castigado con prisión y privación del permiso.","r":"Código Penal, art. 380","k":null,"d":1,"rev":null},{"id":"p622","src":"practica","bat":[],"t":"seguridad","q":"Viaja con su perro en el coche. ¿Qué dice la norma?","o":["Debe ir colocado de forma que no interfiera en la conducción.","Puede ir suelto si es pequeño.","Solo puede ir en el maletero."],"c":0,"img":null,"e":"Los animales deben ir debidamente colocados para que no interfieran en la conducción. Lo más seguro es un transportín sujeto, un arnés al cinturón o una rejilla separadora.","r":"RGC, art. 18","k":null,"d":1,"rev":null},{"id":"p623","src":"practica","bat":[],"t":"factor","q":"¿Las bebidas energéticas o el café eliminan la fatiga al volante?","o":["Sí, durante varias horas.","No: pueden enmascararla un rato, pero no sustituyen al descanso.","Sí, si se toman con azúcar."],"c":1,"img":null,"e":"Los estimulantes retrasan la sensación de sueño, pero no eliminan la fatiga. Cuando su efecto pasa, el cansancio aparece de golpe. La única solución es descansar.","r":"Manual DGT, fatiga y sueño","k":null,"d":1,"rev":null},{"id":"p624","src":"practica","bat":[],"t":"adelantamiento","q":"En una carretera con línea continua le precede un tractor agrícola a 20 km/h. ¿Puede adelantarle invadiendo el sentido contrario?","o":["Sí, porque es un vehículo lento.","Sí, si la línea es amarilla.","No, la línea continua lo prohíbe; la excepción solo es para ciclos."],"c":2,"img":null,"e":"La excepción para rebasar la línea continua al adelantar es para bicicletas y vehículos similares. Un tractor no entra en esa excepción.","r":"RGC, arts. 88 y 167","k":null,"d":1,"rev":null},{"id":"p625","src":"practica","bat":[],"t":"alumbrado","q":"Circula por un carril reversible de día. ¿Qué luz debe llevar?","o":["La de corto alcance.","Ninguna.","La de largo alcance."],"c":0,"img":null,"e":"En los carriles reversibles, adicionales o habilitados para circular en sentido contrario al normal es obligatorio llevar la luz de corto alcance también de día.","r":"RGC, art. 106","k":null,"d":1,"rev":null},{"id":"p626","src":"practica","bat":[],"t":"prioridad","q":"Una vía tiene una señal de ceda el paso y la otra no tiene ninguna. Usted está en la que no tiene señal, y el otro vehículo viene por su derecha. ¿Quién pasa?","o":["El otro, porque viene por la derecha.","Usted, porque el otro tiene la señal de ceda el paso.","El que llegue primero."],"c":1,"img":null,"e":"La señal prevalece sobre la regla de la derecha: quien tiene el ceda el paso debe cederlo, aunque usted se acerque por su izquierda.","r":"RGC, art. 56","k":null,"d":1,"rev":null},{"id":"p627","src":"practica","bat":[],"t":"estacionamiento","q":"¿Puede estacionar a la izquierda en una vía urbana de sentido único?","o":["No, nunca.","Solo motocicletas.","Sí, salvo que esté prohibido por la señalización."],"c":2,"img":null,"e":"En las vías de sentido único se puede parar y estacionar en ambos lados, salvo prohibición. En las de doble sentido, solo en el lado derecho.","r":"RGC, art. 90","k":null,"d":1,"rev":null},{"id":"p628","src":"practica","bat":[],"t":"mantenimiento","q":"Al frenar, el vehículo se desvía hacia un lado. ¿Qué puede indicar?","o":["Que los frenos o los neumáticos de un lado están en distinto estado que los del otro.","Que el depósito está casi vacío.","Que el motor está frío."],"c":0,"img":null,"e":"Si al frenar el vehículo tira hacia un lado, puede haber un desgaste desigual de frenos, una avería en un circuito o diferente presión o desgaste en los neumáticos. Hay que revisarlo cuanto antes.","r":"Manual DGT, frenos","k":null,"d":1,"rev":null},{"id":"p629","src":"practica","bat":[],"t":"velocidad","q":"Una ambulancia en servicio de urgencia con las señales encendidas, ¿debe respetar los límites de velocidad?","o":["Sí, siempre.","No está obligada a respetarlos, pero debe extremar la precaución para no poner en peligro a nadie.","Solo en vías urbanas."],"c":1,"img":null,"e":"Los vehículos prioritarios en servicio urgente pueden no cumplir algunas normas, como los límites de velocidad, pero siempre sin poner en peligro a los demás usuarios.","r":"RGC, art. 68","k":null,"d":1,"rev":null},{"id":"p630","src":"practica","bat":[],"t":"alcohol","q":"Ha bebido y espera dos horas antes de conducir. ¿Puede estar seguro de no superar la tasa?","o":["Sí, en dos horas siempre se elimina.","Sí, si ha comido.","No: depende de lo que haya bebido, de su peso y de su organismo; la única tasa segura es cero."],"c":2,"img":null,"e":"El ritmo de eliminación es lento y varía según la persona, lo que se ha bebido y cómo. No hay un tiempo de espera que garantice estar por debajo del límite.","r":"Manual DGT, alcohol y conducción","k":null,"d":1,"rev":null},{"id":"p631","src":"practica","bat":[],"t":"prioridad","q":"Usted conduce A y tiene la señal azul que se ve junto a la calzada. B viene de frente por el estrechamiento. ¿Quién pasa primero?","o":["A, porque la señal le da prioridad respecto al sentido contrario.","B, porque ya está más cerca del estrechamiento.","Quien encienda antes las luces."],"c":0,"img":"img/escenas/e11.svg","e":"La señal cuadrada azul con la flecha blanca grande hacia arriba indica prioridad respecto al sentido contrario: A pasa primero y B debe esperar.","r":"RGC, art. 151 (R-6)","k":null,"d":1,"rev":null},{"id":"p632","src":"practica","bat":[],"t":"senales","q":"El agente tiene los brazos extendidos en la dirección de la calle por la que circula B. Usted conduce A. ¿Qué debe hacer?","o":["Seguir, porque el agente no le mira.","Detenerse, porque se acerca al agente desde una dirección que corta la de sus brazos.","Girar a la derecha."],"c":1,"img":"img/escenas/e12.svg","e":"Con los brazos extendidos horizontalmente deben detenerse quienes se acercan desde direcciones que cortan la línea de los brazos. A llega de frente al costado del agente, así que debe detenerse; B circula en la dirección de los brazos y puede pasar.","r":"RGC, art. 143.1.b","k":null,"d":1,"rev":null},{"id":"p633","src":"practica","bat":[],"t":"prioridad","q":"Usted conduce A y gira a la derecha. Dos peatones cruzan la calle a la que se incorpora. ¿Qué hace?","o":["Pasa delante de ellos si hay hueco.","Toca la bocina para que se aparten.","Cede el paso a los peatones."],"c":2,"img":"img/escenas/e13.svg","e":"Al girar para entrar en otra vía, el conductor debe ceder el paso a los peatones que la están cruzando, aunque no haya paso señalizado.","r":"RGC, art. 65.1.b","k":null,"d":1,"rev":null},{"id":"p634","src":"practica","bat":[],"t":"prioridad","q":"Un grupo de ciclistas cruza la intersección y el primero ya ha entrado en ella. Usted conduce A. ¿Qué hace?","o":["Espera a que pase todo el grupo.","Pasa cuando haya cruzado el primero.","Pasa entre dos ciclistas si hay espacio."],"c":0,"img":"img/escenas/e14.svg","e":"Un grupo de ciclistas se considera una única unidad móvil a efectos de prioridad: si el primero ha iniciado el cruce, el resto también tiene preferencia.","r":"RGC, art. 64","k":null,"d":1,"rev":null},{"id":"p635","src":"practica","bat":[],"t":"maniobras","q":"Usted conduce A y se incorpora a la autovía. B circula por el carril derecho. ¿Qué es lo correcto?","o":["Detenerse al final del carril de aceleración y esperar.","Usar el carril de aceleración para adaptar la velocidad y ceder el paso a B.","Incorporarse delante de B, porque tiene preferencia quien se incorpora."],"c":1,"img":"img/escenas/e15.svg","e":"El carril de aceleración sirve para alcanzar una velocidad adecuada e incorporarse sin obligar a nadie a frenar. Quien circula por la autovía tiene preferencia. Detenerse al final del carril solo debe hacerse si no hay otra opción.","r":"RGC, art. 72","k":null,"d":1,"rev":null},{"id":"p701","src":"practica","bat":[],"t":"velocidad","q":"Circula por una autovía con un límite señalizado de 100 km/h y llueve con mucha intensidad. ¿A qué velocidad debe circular?","o":["A la velocidad adecuada a las circunstancias, aunque sea inferior a 100 km/h.","A 100 km/h, porque es lo que indica la señal.","A 80 km/h exactos, porque con lluvia se reduce 20 km/h."],"c":0,"img":null,"e":"La señal marca un máximo. Con lluvia intensa hay que adecuar la velocidad a la visibilidad y la adherencia; no existe una rebaja fija de 20 km/h por lluvia.","r":"RGC, arts. 45 y 46","k":null,"d":1,"rev":null},{"id":"p702","src":"practica","bat":[],"t":"adelantamiento","q":"Va a adelantar a un camión en una recta con línea discontinua, pero el adelantamiento terminaría sobre un paso para peatones señalizado. ¿Puede hacerlo?","o":["Sí, si no hay peatones cruzando.","No, porque está prohibido adelantar en los pasos para peatones señalizados.","Sí, si avisa con el claxon."],"c":1,"img":null,"e":"La prohibición se refiere a realizar el adelantamiento en el paso. Si la maniobra no se puede completar antes, hay que esperar.","r":"RGC, art. 87.1.b","k":null,"d":1,"rev":null},{"id":"p703","src":"practica","bat":[],"t":"alumbrado","q":"De noche, por una carretera sin iluminar, se cruza con un ciclista que viene de frente por el arcén. ¿Qué debe hacer con las luces?","o":["Mantener la de carretera, porque es un ciclista.","Encender la antiniebla trasera.","Cambiar a la luz de cruce para no deslumbrarle."],"c":2,"img":null,"e":"La luz de carretera debe sustituirse por la de cruce para no deslumbrar a ningún usuario de la vía, también ciclistas y peatones.","r":"RGC, art. 100","k":null,"d":1,"rev":null},{"id":"p704","src":"practica","bat":[],"t":"prioridad","q":"Llega a una intersección con un semáforo apagado y una señal de ceda el paso. ¿Qué debe obedecer?","o":["La señal de ceda el paso.","Nada: si el semáforo no funciona, rige la regla de la derecha.","Debe detenerse siempre, como en un stop."],"c":0,"img":null,"e":"Si el semáforo no funciona, se obedece la señalización vertical existente. Solo si no hubiera ninguna señal se aplicaría la regla de la derecha.","r":"RGC, arts. 133 y 151","k":null,"d":1,"rev":null},{"id":"p705","src":"practica","bat":[],"t":"senales","q":"En una intersección hay un semáforo en verde y, en el mismo punto, una señal de stop. ¿Qué debe hacer?","o":["Detenerse por completo, porque el stop obliga siempre.","Pasar, porque el semáforo prevalece sobre la señal vertical.","Detenerse solo si viene alguien."],"c":1,"img":null,"e":"El orden de prevalencia es: agentes, señalización circunstancial, semáforos, señales verticales y marcas viales. Con el semáforo funcionando en verde se puede pasar, con precaución.","r":"RGC, art. 133","k":null,"d":1,"rev":null},{"id":"p706","src":"practica","bat":[],"t":"senales","q":"Un semáforo está en ámbar intermitente y en la misma intersección hay una señal de stop. ¿Qué hace?","o":["Pasar con precaución, porque el ámbar intermitente lo permite.","Esperar a que el semáforo se ponga verde.","Detenerse por completo y ceder el paso, como indica el stop."],"c":2,"img":null,"e":"El ámbar intermitente obliga a extremar la precaución y a respetar la señalización que haya. Si hay un stop, hay que detenerse.","r":"RGC, arts. 146 y 151","k":null,"d":1,"rev":null},{"id":"p707","src":"practica","bat":[],"t":"maniobras","q":"Quiere cambiar de sentido en una vía de doble sentido separada por una línea continua. ¿Puede hacerlo?","o":["No, porque tendría que atravesar la línea continua.","Sí, si no viene nadie.","Sí, en vías urbanas."],"c":0,"img":null,"e":"La línea continua no se puede atravesar, tampoco para cambiar de sentido o girar a la izquierda.","r":"RGC, arts. 79 y 167","k":null,"d":1,"rev":null},{"id":"p708","src":"practica","bat":[],"t":"factor","q":"Ha tomado un antihistamínico cuyo prospecto advierte de que produce somnolencia. ¿Qué es lo correcto?","o":["Conducir con las ventanillas abiertas.","No conducir mientras dure el efecto o consultar al médico por una alternativa.","Conducir, porque los medicamentos no cuentan como drogas."],"c":1,"img":null,"e":"Muchos antihistamínicos producen somnolencia y reducen la atención. Si el prospecto lo advierte, no hay que conducir mientras dure su efecto.","r":"Manual DGT, medicamentos","k":null,"d":1,"rev":null},{"id":"p709","src":"practica","bat":[],"t":"documentacion","q":"Conduce con el permiso de conducción caducado por no haberlo renovado a tiempo. ¿Qué comete?","o":["Un delito, igual que si no lo tuviera.","Nada, si lo renueva en el plazo de un mes.","Una infracción administrativa, no un delito."],"c":2,"img":null,"e":"Conducir con el permiso caducado es una infracción administrativa. El delito se reserva a quien conduce sin haberlo obtenido nunca, tras perder todos los puntos o con privación judicial.","r":"LSV; Código Penal, art. 384","k":null,"d":1,"rev":null},{"id":"p710","src":"practica","bat":[],"t":"alcohol","q":"Un ciclista da 0,40 mg/l en aire espirado en un control. ¿Qué ocurre?","o":["Comete una infracción, porque las tasas de alcohol también se aplican a los ciclistas.","Nada, porque las tasas son para vehículos a motor.","Solo recibe una advertencia."],"c":0,"img":null,"e":"Las tasas máximas se aplican a los conductores de cualquier vehículo, incluidas las bicicletas.","r":"RGC, art. 20","k":null,"d":1,"rev":null},{"id":"p711","src":"practica","bat":[],"t":"prioridad","q":"En un estrechamiento sin señalizar y en terreno llano, dos turismos se encuentran de frente. ¿Quién tiene preferencia?","o":["El que circule más rápido.","El que haya entrado primero en el estrechamiento.","El que venga por la derecha."],"c":1,"img":null,"e":"En los estrechamientos sin señalizar tiene preferencia el vehículo que haya entrado primero. El otro debe esperar o retroceder si es necesario.","r":"RGC (paso en estrechamientos)","k":null,"d":1,"rev":null},{"id":"p712","src":"practica","bat":[],"t":"adelantamiento","q":"El vehículo que le precede se detiene ante un paso para peatones. ¿Puede adelantarle?","o":["Sí, si no ve a ningún peatón.","Sí, por la derecha.","No: puede haber un peatón cruzando oculto tras él y está prohibido adelantar en el paso."],"c":2,"img":null,"e":"Un vehículo detenido ante un paso de peatones suele estar dejando cruzar a alguien que usted no ve. Además, está prohibido adelantar en los pasos para peatones señalizados.","r":"RGC, art. 87","k":null,"d":1,"rev":null},{"id":"p713","src":"practica","bat":[],"t":"senales","q":"En una zona de obras hay marcas viales amarillas que contradicen las blancas. ¿Cuáles obedece?","o":["Las amarillas, porque son provisionales y prevalecen.","Las blancas, porque son las permanentes.","Ninguna: hay que circular por el centro."],"c":0,"img":null,"e":"Las marcas amarillas de obras sustituyen temporalmente a las blancas y prevalecen sobre ellas.","r":"RGC, art. 133 y 167","k":null,"d":1,"rev":null},{"id":"p714","src":"practica","bat":[],"t":"accidentes","q":"Un herido está inconsciente y no respira. Tras avisar al 112, ¿qué debe hacer?","o":["Colocarlo en posición lateral de seguridad y esperar.","Iniciar la reanimación cardiopulmonar (compresiones torácicas).","Darle agua para reanimarlo."],"c":1,"img":null,"e":"La posición lateral de seguridad es para quien está inconsciente pero respira. Si no respira, hay que iniciar las compresiones torácicas (30 compresiones y 2 ventilaciones si se sabe hacerlo).","r":"Manual DGT, primeros auxilios","k":null,"d":1,"rev":null},{"id":"p715","src":"practica","bat":[],"t":"factor","q":"¿Es adecuado conducir de noche con gafas de sol?","o":["Sí, porque reducen los deslumbramientos.","Sí, en autopista.","No, porque reducen la luz que llega al ojo y empeoran la visión."],"c":2,"img":null,"e":"De noche ya llega poca luz. Las gafas de sol la reducen aún más y empeoran la percepción de obstáculos y peatones.","r":"Manual DGT, visión","k":null,"d":1,"rev":null},{"id":"p716","src":"practica","bat":[],"t":"velocidad","q":"En una calle urbana de un carril por sentido circula detrás de un ciclista. ¿Qué distancia mínima debe mantener?","o":["5 metros.","1,5 metros.","2 segundos."],"c":0,"img":null,"e":"Desde la reforma de 2026, en vía urbana los vehículos a motor deben mantener al menos 5 metros de distancia con el ciclista que les precede. El 1,5 m es la separación lateral al adelantar.","r":"RGC (RD 518/2026)","k":"5 m detrás; 1,5 m al lado.","d":1,"rev":null},{"id":"p717","src":"practica","bat":[],"t":"circulacion","q":"En ciudad, un ciclista circula por el centro del carril y no pegado a la derecha. ¿Es correcto?","o":["No, los ciclistas siempre deben ir pegados a la derecha.","Sí: tras la reforma de 2026 circulan preferentemente por el centro del carril.","No, solo si el carril es exclusivo para bicicletas."],"c":1,"img":null,"e":"Desde octubre de 2026 los ciclistas circulan preferentemente por el centro del carril en vías urbanas, lo que les hace más visibles y evita adelantamientos peligrosos dentro del mismo carril.","r":"RGC (RD 518/2026)","k":null,"d":1,"rev":null},{"id":"p718","src":"practica","bat":[],"t":"mantenimiento","q":"Se enciende en el cuadro el testigo de presión de los neumáticos. ¿Qué debe hacer?","o":["Ignorarlo hasta la próxima revisión.","Aumentar la velocidad para calentarlos.","Comprobar cuanto antes la presión y el estado de los neumáticos."],"c":2,"img":null,"e":"El testigo avisa de una pérdida de presión en algún neumático. Circular así aumenta el riesgo de reventón y empeora la frenada: hay que comprobarlo pronto.","r":"Manual del vehículo","k":null,"d":1,"rev":null},{"id":"p719","src":"practica","bat":[],"t":"eficiente","q":"Circulando en llano a 50 km/h con un turismo de cinco marchas, ¿qué es más eficiente?","o":["Ir en la marcha más larga que permita el motor sin tirones, normalmente cuarta o quinta.","Ir en segunda para tener más respuesta.","Ir en punto muerto."],"c":0,"img":null,"e":"Circular en marchas largas a bajas revoluciones reduce el consumo. A 50 km/h en llano suele ser posible usar cuarta o quinta.","r":"IDAE, conducción eficiente","k":null,"d":1,"rev":null},{"id":"p720","src":"practica","bat":[],"t":"seguridad","q":"¿Puede un pasajero llevar a un bebé en brazos en el asiento trasero en un trayecto corto?","o":["Sí, si el trayecto es urbano.","No: el bebé debe ir en su sistema de retención homologado.","Sí, si el pasajero lleva el cinturón."],"c":1,"img":null,"e":"Un bebé en brazos sale despedido en un choque incluso a baja velocidad, y el cinturón del adulto puede aplastarlo. Siempre debe ir en su sistema de retención.","r":"RGC, art. 117","k":null,"d":1,"rev":null},{"id":"p721","src":"practica","bat":[],"t":"adelantamiento","q":"En una autovía de dos carriles hay un vehículo averiado en el arcén con la V-16 encendida. ¿Qué debe hacer, si es posible?","o":["Pasar a su lado a la velocidad de la vía.","Detenerse detrás para ayudar.","Cambiarse al carril izquierdo o, si no puede, rebasarlo dejando 1,5 m y reduciendo 20 km/h."],"c":2,"img":null,"e":"Desde la reforma de 2026, al rebasar un vehículo inmovilizado por avería, accidente o auxilio hay que dejar al menos 1,5 m y reducir 20 km/h respecto al límite. Cambiarse de carril, si se puede, protege a quienes están junto al vehículo.","r":"RGC (RD 518/2026)","k":null,"d":1,"rev":null},{"id":"p722","src":"practica","bat":[],"t":"documentacion","q":"¿Cuántos puntos se pierden por conducir con un sistema de detección de radares o cinemómetros?","o":["3 puntos.","6 puntos.","Ninguno, solo multa."],"c":0,"img":null,"e":"Los detectores de radar están prohibidos y suponen 200 € y 3 puntos; los inhibidores (que interfieren el radar) son mucho más graves: 6.000 € y 6 puntos. Cuidado con confundirlos.","r":"LSV, Anexo II","k":null,"d":1,"rev":null},{"id":"p723","src":"practica","bat":[],"t":"circulacion","q":"¿Puede circular un turismo por un carril reservado para bicicletas para girar a la derecha?","o":["Sí, durante los últimos 20 metros.","No: debe ceder el paso a los ciclistas y girar sin circular por el carril bici.","Sí, si no hay ciclistas."],"c":1,"img":null,"e":"Los carriles bici están reservados para los ciclos. Al girar se cruzan cediendo el paso a los ciclistas, sin circular por ellos.","r":"RGC, arts. 36 y 64","k":null,"d":1,"rev":null},{"id":"p724","src":"practica","bat":[],"t":"alumbrado","q":"Su vehículo tiene luces de circulación diurna que se encienden solas. Entra en un túnel señalizado. ¿Es suficiente?","o":["Sí, porque ya lleva luces encendidas.","Sí, si el túnel está iluminado.","No: en el túnel debe llevar encendida la luz de corto alcance."],"c":2,"img":null,"e":"Las luces de circulación diurna no sustituyen a la de corto alcance donde esta es obligatoria, como en los túneles señalizados. Además, muchas no encienden las luces traseras.","r":"RGC, art. 104","k":null,"d":1,"rev":null},{"id":"p001","src":"practica","bat":[],"t":"accidentes","q":"Desde el 1 de enero de 2026, ¿qué dispositivo es obligatorio para señalizar un vehículo inmovilizado en la vía en turismos y furgonetas?","o":["Los dos triángulos de preseñalización de peligro.","La baliza luminosa V-16 conectada a la plataforma DGT 3.0.","Cualquier luz de emergencia de color amarillo."],"c":1,"img":null,"e":"Desde el 1 de enero de 2026 la única forma válida de preseñalizar un vehículo inmovilizado es la luz V-16 homologada y conectada, que envía su ubicación a la plataforma DGT 3.0. Los triángulos dejaron de ser válidos como preseñalización obligatoria y no sirve cualquier luz.","r":"RD 159/2021 (servicios de auxilio en las vías públicas) · DGT","k":"2026: V-16 conectada, los triángulos ya no valen.","d":0,"rev":null},{"id":"p002","src":"practica","bat":[],"t":"accidentes","q":"¿Dónde es recomendable colocar la baliza V-16 cuando el vehículo queda inmovilizado?","o":["En la parte más alta posible del vehículo, normalmente el techo, sin necesidad de salir a la calzada.","A 50 metros por detrás del vehículo, sobre la calzada.","En el salpicadero, por dentro del parabrisas."],"c":0,"img":null,"e":"La V-16 se diseñó para no tener que caminar por la calzada: se coloca en el techo (o en la parte más alta y visible) sacando el brazo por la ventanilla. Ponerla a 50 m obligaría a exponerse a un atropello y dentro del habitáculo se ve mucho peor.","r":"DGT · RGV","k":null,"d":0,"rev":null},{"id":"p003","src":"practica","bat":[],"t":"accidentes","q":"Su turismo se avería en un tramo interurbano y tiene que salir del vehículo. ¿Qué debe ponerse?","o":["Nada, si la avería se produce de día.","El chaleco reflectante de alta visibilidad homologado, antes de salir.","El chaleco solo si va a manipular el motor."],"c":1,"img":null,"e":"En vías interurbanas, el conductor (y los ocupantes) que salga del vehículo inmovilizado en la calzada o el arcén debe llevar puesto el chaleco reflectante, de día y de noche. Lo ideal es ponérselo antes de salir.","r":"RGC art. 118.3","k":null,"d":0,"rev":null},{"id":"p004","src":"practica","bat":[],"t":"velocidad","q":"¿Cuál es la velocidad máxima genérica para un turismo en una carretera convencional?","o":["100 km/h.","90 km/h.","80 km/h."],"c":1,"img":null,"e":"Desde la reforma de 2019, la velocidad máxima genérica de turismos y motocicletas en carreteras convencionales es 90 km/h (antes podía ser 100 con arcén ancho). En autopistas y autovías es 120.","r":"RGC art. 48","k":"Convencional: 90 para todos los turismos.","d":0,"rev":null},{"id":"p005","src":"practica","bat":[],"t":"velocidad","q":"En una vía urbana con un único carril por sentido de circulación, ¿cuál es la velocidad máxima genérica?","o":["50 km/h.","30 km/h.","20 km/h."],"c":1,"img":null,"e":"Desde mayo de 2021: 20 km/h en vías de plataforma única de calzada y acera, 30 km/h en vías de un carril por sentido y 50 km/h en vías de dos o más carriles por sentido.","r":"RGC art. 50","k":null,"d":0,"rev":null},{"id":"p006","src":"practica","bat":[],"t":"velocidad","q":"¿Puede un turismo superar la velocidad máxima de la vía para adelantar en una carretera convencional?","o":["Sí, en 20 km/h como máximo.","Sí, pero solo para adelantar a camiones.","No, nunca se puede superar la velocidad máxima permitida."],"c":2,"img":null,"e":"La posibilidad de superar en 20 km/h el límite para adelantar en carreteras convencionales se eliminó con el RD 970/2020 (en vigor desde enero de 2021). Hoy no se puede rebasar el límite en ningún caso, ni siquiera durante un adelantamiento. Es más: desde octubre de 2026, al adelantar a ciclistas en vía interurbana hay que reducir la velocidad al menos 20 km/h por debajo del límite.","r":"RGC art. 48 (RD 970/2020)","k":"Ya no existe el «+20 para adelantar».","d":1,"rev":null},{"id":"p007","src":"practica","bat":[],"t":"velocidad","q":"Por una autopista, ¿a qué velocidad mínima debe circular un turismo, salvo causa justificada?","o":["60 km/h.","50 km/h.","80 km/h."],"c":0,"img":null,"e":"En autopistas y autovías no se puede circular a menos de la mitad de la velocidad genérica del vehículo. Para un turismo (120 km/h) la mínima es 60 km/h.","r":"RGC art. 49","k":null,"d":0,"rev":null},{"id":"p008","src":"practica","bat":[],"t":"adelantamiento","q":"Al adelantar a un ciclista en una carretera convencional, ¿qué separación lateral mínima debe dejar?","o":["1 metro.","1,5 metros.","2 metros solo si llueve."],"c":1,"img":null,"e":"Hay que dejar al menos 1,5 m de separación lateral con ciclistas. Además, desde octubre de 2026, en vía interurbana hay que reducir la velocidad al menos 20 km/h respecto al límite y, si hay más de un carril por sentido, cambiar completamente de carril. Se puede invadir el carril contrario si es seguro.","r":"RGC art. 85.4 (RD 518/2026)","k":"Ciclista = 1,5 m mínimo.","d":0,"rev":null},{"id":"p009","src":"practica","bat":[],"t":"adelantamiento","q":"En una vía con dos carriles en el mismo sentido, ¿cómo debe adelantar a un ciclista que circula por el carril derecho?","o":["Cambiando completamente al carril izquierdo.","Manteniéndose en su carril si queda 1 metro de separación.","Tocando el claxon para que se aparte al arcén."],"c":0,"img":null,"e":"Desde 2022, en vías con más de un carril por sentido es obligatorio cambiar completamente de carril para adelantar a ciclistas o ciclomotores. No basta con mantener una separación dentro del mismo carril.","r":"RGC art. 85.4 (Ley 18/2021)","k":null,"d":1,"rev":null},{"id":"p010","src":"practica","bat":[],"t":"adelantamiento","q":"Hay una línea continua en el centro de la calzada. ¿Puede adelantar a un ciclista?","o":["No, la línea continua no puede rebasarse nunca.","Sí, si puede hacerlo sin peligro, aunque tenga que rebasar parcial o totalmente la línea continua.","Sí, pero solo si el ciclista circula a menos de 10 km/h."],"c":1,"img":null,"e":"Excepcionalmente, se permite rebasar la línea continua para adelantar a ciclistas cuando la maniobra puede hacerse sin peligro para nadie y la visibilidad lo permite.","r":"RGC art. 88.1","k":null,"d":1,"rev":null},{"id":"p011","src":"practica","bat":[],"t":"adelantamiento","q":"¿En cuál de estos lugares está prohibido adelantar, como norma general?","o":["En un paso para peatones señalizado.","En una recta con buena visibilidad.","En una autovía con tres carriles por sentido."],"c":0,"img":null,"e":"Está prohibido adelantar en pasos para peatones señalizados, en curvas y cambios de rasante de visibilidad reducida, en intersecciones (con excepciones) y en pasos a nivel. En una recta con visibilidad o una autovía se puede adelantar respetando las normas.","r":"RGC art. 87","k":null,"d":0,"rev":null},{"id":"p012","src":"practica","bat":[],"t":"adelantamiento","q":"¿Por qué lado se adelanta como norma general?","o":["Por la izquierda.","Por la derecha.","Por el lado en el que haya más espacio."],"c":0,"img":null,"e":"Por regla general se adelanta por la izquierda. Se adelanta por la derecha cuando el vehículo de delante ha indicado que va a girar a la izquierda y se ha desplazado para ello, o en poblado con carriles marcados.","r":"RGC art. 82","k":null,"d":0,"rev":null},{"id":"p013","src":"practica","bat":[],"t":"prioridad","q":"En una intersección sin señalizar, ¿quién tiene prioridad de paso como norma general?","o":["El vehículo que viene por la derecha.","El vehículo que circula a mayor velocidad.","El vehículo de mayor tamaño."],"c":0,"img":null,"e":"En intersecciones sin señalizar, hay que ceder el paso a los vehículos que se aproximan por la derecha, salvo excepciones: vías pavimentadas frente a no pavimentadas, vehículos sobre raíles y quienes circulan dentro de una glorieta.","r":"RGC art. 57","k":"Sin señales: manda la derecha.","d":0,"rev":null},{"id":"p014","src":"practica","bat":[],"t":"prioridad","q":"En una intersección sin señalizar, usted circula por una vía pavimentada y por su derecha llega un vehículo desde un camino de tierra. ¿Quién pasa primero?","o":["El vehículo que llega por la derecha.","Usted, porque circula por una vía pavimentada.","El que llegue primero a la intersección."],"c":1,"img":null,"e":"Es una excepción a la regla de la derecha: los vehículos que circulan por una vía pavimentada tienen preferencia sobre los que proceden de una vía sin pavimentar.","r":"RGC art. 57.1.a","k":null,"d":1,"rev":null},{"id":"p015","src":"practica","bat":[],"t":"senales","q":"¿Qué obliga esta señal?","o":["A detenerse siempre en la línea de detención y ceder el paso.","A ceder el paso, deteniéndose solo si viene alguien.","A reducir la velocidad a 20 km/h."],"c":0,"img":"img/senales/r2.svg","e":"La señal R-2 (STOP) obliga a detenerse completamente en la línea de detención (o antes de la intersección si no la hay) y a ceder el paso, haya o no vehículos. La de ceda el paso no obliga a detenerse si no viene nadie.","r":"RGC art. 151 (R-2)","k":"STOP = parar siempre, aunque no venga nadie.","d":0,"rev":null},{"id":"p016","src":"practica","bat":[],"t":"senales","q":"¿Qué indica esta señal?","o":["Prohibido el paso.","Obligación de ceder el paso en la próxima intersección.","Peligro por proximidad de intersección."],"c":1,"img":"img/senales/r1.svg","e":"La señal R-1 (triángulo con el vértice hacia abajo) obliga a ceder el paso a los vehículos que circulan por la vía a la que se aproxima. Solo hay que detenerse si es necesario.","r":"RGC art. 151 (R-1)","k":null,"d":0,"rev":null},{"id":"p017","src":"practica","bat":[],"t":"senales","q":"¿Qué indica esta señal?","o":["Prohibido estacionar.","Entrada prohibida a todos los vehículos.","Calle sin salida."],"c":1,"img":"img/senales/r101.svg","e":"La señal R-101 (círculo rojo con franja blanca horizontal) prohíbe la entrada a toda clase de vehículos. Suele indicar el inicio de una vía de sentido contrario.","r":"Catálogo de señales: R-101","k":null,"d":0,"rev":null},{"id":"p018","src":"practica","bat":[],"t":"senales","q":"Esta señal, ¿qué prohíbe?","o":["Adelantar a otros vehículos de motor, salvo a los de dos ruedas.","Circular a dos vehículos en paralelo.","Cambiar de carril."],"c":0,"img":"img/senales/r305.svg","e":"La R-305 prohíbe adelantar a los vehículos de motor que circulan por la calzada, pero permite adelantar a los vehículos de dos ruedas (motos, ciclomotores, bicicletas) si se hace con seguridad.","r":"Catálogo de señales: R-305","k":null,"d":1,"rev":null},{"id":"p019","src":"practica","bat":[],"t":"senales","q":"¿Qué indica esta señal?","o":["Velocidad mínima obligatoria de 50 km/h.","Velocidad máxima de 50 km/h a partir de la señal.","Velocidad recomendada de 50 km/h."],"c":1,"img":"img/senales/r301-50.svg","e":"La R-301 (círculo rojo con número) prohíbe circular a más de la velocidad indicada. La velocidad mínima se indica con una señal azul (R-411) y la recomendada, con una señal cuadrada azul (S-7).","r":"Catálogo de señales: R-301","k":"Redonda roja = máxima · Redonda azul = mínima · Cuadrada azul = recomendada.","d":0,"rev":null},{"id":"p020","src":"practica","bat":[],"t":"senales","q":"¿Qué indica esta señal?","o":["Intersección de sentido giratorio obligatorio (glorieta).","Prohibido cambiar de sentido.","Calle de doble sentido."],"c":0,"img":"img/senales/r402.svg","e":"La R-402 indica que en la intersección hay que circular en sentido giratorio, dejando el centro a la izquierda. Salvo otra señal, tienen prioridad los que ya están dentro.","r":"Catálogo de señales: R-402","k":null,"d":0,"rev":null},{"id":"p021","src":"practica","bat":[],"t":"senales","q":"¿Qué prohíbe esta señal?","o":["Solo estacionar.","Parar y estacionar.","Circular a vehículos de motor."],"c":1,"img":"img/senales/r307.svg","e":"La R-307 (fondo azul con borde rojo y aspa roja) prohíbe la parada y el estacionamiento. La R-308 (con una sola barra) prohíbe solo estacionar.","r":"Catálogo de señales: R-307","k":"Una barra: no estacionar · Aspa: ni parar ni estacionar.","d":0,"rev":null},{"id":"p022","src":"practica","bat":[],"t":"senales","q":"¿Qué prohíbe esta señal?","o":["Parar y estacionar.","Estacionar, pero permite parar.","El paso a vehículos de más de dos metros."],"c":1,"img":"img/senales/r308.svg","e":"La R-308 (una sola barra roja) prohíbe estacionar; parar sí está permitido. Si lleva paneles con días u horas, la prohibición solo rige en ese horario.","r":"Catálogo de señales: R-308","k":null,"d":0,"rev":null},{"id":"p023","src":"practica","bat":[],"t":"senales","q":"¿Qué indica esta señal?","o":["Peligro por proximidad de un paso para peatones.","Situación de un paso para peatones.","Zona peatonal: prohibido el paso de vehículos."],"c":1,"img":"img/senales/s13.svg","e":"La S-13 (cuadrada azul) indica la situación de un paso para peatones, donde los conductores deben dejarles pasar. La señal triangular P-20 advierte de que más adelante hay peatones o un paso.","r":"Catálogo de señales: S-13","k":null,"d":0,"rev":null},{"id":"p024","src":"practica","bat":[],"t":"senales","q":"¿Qué indica esta señal de peligro?","o":["Peligro por la proximidad de un lugar frecuentado por peatones o de un paso para peatones.","Paso para peatones con prioridad para los vehículos.","Calle peatonal."],"c":0,"img":"img/senales/p20.svg","e":"La P-20 advierte del peligro por la proximidad de un paso para peatones o de un lugar donde frecuentemente circulan peatones. Es una señal de advertencia (triangular, borde rojo).","r":"Catálogo de señales: P-20","k":null,"d":0,"rev":null},{"id":"p025","src":"practica","bat":[],"t":"senales","q":"¿Qué orden de prioridad tienen las señales de circulación?","o":["Semáforos, agentes, señales verticales, marcas viales.","Agentes, señalización circunstancial (balizamiento), semáforos, señales verticales y marcas viales.","Marcas viales, señales verticales, semáforos y agentes."],"c":1,"img":null,"e":"El orden es: 1) señales y órdenes de los agentes; 2) señalización circunstancial que modifica el régimen normal (balizamiento, señales de obras); 3) semáforos; 4) señales verticales; 5) marcas viales. Ante señales contradictorias, prevalece la más restrictiva del mismo tipo.","r":"RGC art. 133","k":"Agente > balizamiento > semáforo > vertical > marca vial.","d":0,"rev":null},{"id":"p026","src":"practica","bat":[],"t":"senales","q":"Un semáforo muestra una flecha verde que se ilumina junto con la luz roja. ¿Qué indica?","o":["Que puede pasar en la dirección de la flecha, cediendo el paso a peatones y vehículos que tengan prioridad.","Que debe detenerse en todo caso.","Que el semáforo está averiado."],"c":0,"img":null,"e":"Una flecha verde encendida al mismo tiempo que la luz roja permite avanzar solo en la dirección de la flecha, respetando a los peatones y vehículos que circulan con su propia luz verde.","r":"RGC art. 146","k":null,"d":0,"rev":null},{"id":"p027","src":"practica","bat":[],"t":"maniobras","q":"¿Por qué carril debe circular dentro de una glorieta si va a tomar la siguiente salida?","o":["Por el carril interior.","Por el carril exterior (derecho).","Por cualquiera, señalizando con el intermitente izquierdo."],"c":1,"img":null,"e":"Si vas a salir pronto, circula por el carril exterior. Para abandonar la glorieta hay que situarse con antelación en el carril exterior y señalizar con el intermitente derecho. Salir directamente desde el carril interior cortando el exterior es peligroso y sancionable.","r":"RGC art. 29 y criterios DGT de glorietas","k":"Para salir: carril exterior + intermitente derecho.","d":0,"rev":null},{"id":"p028","src":"practica","bat":[],"t":"maniobras","q":"Para salir de una glorieta, ¿qué intermitente debe utilizar?","o":["El izquierdo.","El derecho.","Ninguno, ya que la salida es obvia."],"c":1,"img":null,"e":"La salida de la glorieta es un desplazamiento hacia la derecha: se señaliza con el intermitente derecho con antelación suficiente.","r":"RGC art. 109","k":null,"d":0,"rev":null},{"id":"p029","src":"practica","bat":[],"t":"maniobras","q":"¿Dónde está prohibido cambiar el sentido de la marcha?","o":["En los pasos a nivel, túneles y donde esté prohibido adelantar, entre otros lugares.","En una calle con buena visibilidad y sin tráfico.","En una intersección señalizada para ello."],"c":0,"img":null,"e":"Se prohíbe el cambio de sentido en pasos a nivel y sus proximidades, túneles y pasos inferiores, tramos con visibilidad reducida, donde esté prohibido adelantar (salvo que se autorice), autopistas y autovías (salvo por los lugares habilitados).","r":"RGC art. 79","k":null,"d":0,"rev":null},{"id":"p030","src":"practica","bat":[],"t":"maniobras","q":"¿Qué distancia máxima puede recorrerse marcha atrás como maniobra complementaria?","o":["15 metros, sin invadir un cruce de vías.","10 metros, aunque se invada un cruce.","Sin límite, si se hace despacio."],"c":0,"img":null,"e":"La marcha atrás solo se permite como maniobra complementaria de otra (parada, estacionamiento, iniciar la marcha) y su recorrido no puede superar 15 m ni invadir un cruce. Está prohibida en autopistas y autovías.","r":"RGC art. 80","k":null,"d":0,"rev":null},{"id":"p031","src":"practica","bat":[],"t":"maniobras","q":"Al incorporarse a una autovía desde un carril de aceleración, ¿qué debe hacer?","o":["Detenerse al final del carril de aceleración y esperar.","Aprovechar el carril de aceleración para alcanzar una velocidad adecuada y ceder el paso a quienes circulan por la autovía.","Incorporarse con prioridad, ya que el carril termina."],"c":1,"img":null,"e":"El carril de aceleración sirve para adaptar la velocidad a la del tráfico de la autovía. Hay que ceder el paso a quienes ya circulan por ella y no detenerse salvo que sea imprescindible.","r":"RGC art. 72","k":null,"d":0,"rev":null},{"id":"p032","src":"practica","bat":[],"t":"circulacion","q":"En una autovía con tres carriles por sentido, ¿por qué carril debe circular normalmente un turismo?","o":["Por el de la izquierda, que es el más rápido.","Por el de la derecha, pudiendo usar los demás cuando la circulación lo requiera, sin entorpecer.","Por el central, siempre."],"c":1,"img":null,"e":"Como norma general se circula por el carril de la derecha. En vías con varios carriles por sentido se pueden usar los demás cuando la intensidad del tráfico lo aconseje, sin entorpecer y volviendo a la derecha en cuanto sea posible. El izquierdo es para adelantar.","r":"RGC art. 31","k":null,"d":0,"rev":null},{"id":"p033","src":"practica","bat":[],"t":"circulacion","q":"Por una vía interurbana sin acera, ¿por dónde deben circular los peatones como norma general?","o":["Por su derecha.","Por su izquierda, de frente a los vehículos.","Por el centro de la calzada."],"c":1,"img":null,"e":"En vías interurbanas los peatones deben circular por la izquierda, para ver venir a los vehículos de frente. Pueden ir por la derecha si hay razones de seguridad. De noche o con poca visibilidad deben llevar un elemento reflectante.","r":"RGC art. 122","k":null,"d":0,"rev":null},{"id":"p034","src":"practica","bat":[],"t":"circulacion","q":"¿Por dónde no pueden circular los patinetes eléctricos (vehículos de movilidad personal)?","o":["Por las aceras y zonas peatonales.","Por las calles de un carril por sentido limitadas a 30 km/h.","Por los carriles bici."],"c":0,"img":null,"e":"Los VMP tienen prohibido circular por aceras y zonas peatonales (la acera es solo para peatones), así como por autopistas, autovías, travesías y túneles urbanos. Desde la reforma de 2026, fuera de poblado pueden usar vías segregadas del tráfico a motor, como carriles bici, salvo prohibición señalizada. Su velocidad máxima de diseño es 25 km/h.","r":"RGC (RD 970/2020 y RD 518/2026)","k":null,"d":0,"rev":null},{"id":"p035","src":"practica","bat":[],"t":"estacionamiento","q":"¿Dónde está prohibido estacionar?","o":["En un carril reservado a bicicletas o a transporte público.","En una zona de estacionamiento señalizada con línea discontinua blanca.","En una calle ancha sin señalización que lo prohíba."],"c":0,"img":null,"e":"Entre otros lugares, está prohibido estacionar en carriles o partes de la vía reservados a ciclistas o al transporte público, pasos para peatones, intersecciones, curvas sin visibilidad, vados y en doble fila.","r":"RGC arts. 91 y 94","k":null,"d":0,"rev":null},{"id":"p036","src":"practica","bat":[],"t":"estacionamiento","q":"¿Qué diferencia hay entre parar y estacionar?","o":["Ninguna, son lo mismo.","Parar es una inmovilización de no más de 2 minutos sin que el conductor abandone el vehículo; estacionar no es ni parada ni detención.","Parar es apagar el motor y estacionar, dejarlo encendido."],"c":1,"img":null,"e":"Parada: inmovilización por un tiempo inferior a 2 minutos, sin que el conductor abandone el vehículo. Detención: inmovilización por necesidades de la circulación (semáforo, atasco). Estacionamiento: cualquier inmovilización que no sea parada ni detención.","r":"LSV anexo I","k":"Parar < 2 min y sin bajarte.","d":0,"rev":null},{"id":"p037","src":"practica","bat":[],"t":"estacionamiento","q":"Estaciona en una cuesta pronunciada hacia abajo, junto al bordillo derecho. ¿Cómo debe dejar las ruedas delanteras?","o":["Rectas.","Giradas hacia el bordillo.","Giradas hacia el centro de la calzada."],"c":1,"img":null,"e":"En pendiente descendente, las ruedas delanteras deben quedar giradas hacia el bordillo: si el vehículo se moviera, se detendría contra él. Además hay que poner el freno de mano y una marcha (primera o marcha atrás).","r":"RGC art. 92","k":null,"d":0,"rev":null},{"id":"p038","src":"practica","bat":[],"t":"alumbrado","q":"¿Cuándo debe utilizar la luz antiniebla trasera?","o":["Siempre que circule de noche.","Con niebla espesa, lluvia muy intensa, nevada densa o nubes de humo o polvo.","Cuando llueva un poco."],"c":1,"img":null,"e":"La antiniebla trasera solo se puede usar con condiciones meteorológicas o ambientales especialmente desfavorables (niebla espesa, lluvia muy intensa, nevada densa, humo o polvo). Usarla en otras situaciones deslumbra a quien va detrás.","r":"RGC art. 106.3","k":null,"d":0,"rev":null},{"id":"p039","src":"practica","bat":[],"t":"alumbrado","q":"¿En qué caso está prohibido usar la luz de carretera (largas)?","o":["En una vía interurbana sin iluminar sin vehículos cerca.","En vías urbanas suficientemente iluminadas y cuando puede deslumbrar a otros usuarios.","De noche en autovías sin tráfico."],"c":1,"img":null,"e":"Las luces largas están prohibidas en vías urbanas o interurbanas suficientemente iluminadas, cuando el vehículo está parado o estacionado y cuando pueden deslumbrar a otros usuarios (al cruzarse o al seguir a otro vehículo).","r":"RGC art. 99","k":null,"d":0,"rev":null},{"id":"p040","src":"practica","bat":[],"t":"alumbrado","q":"De día, ¿en qué situación es obligatorio llevar encendida la luz de cruce?","o":["Al circular por un carril reversible o adicional y en túneles.","Nunca, de día no hace falta.","Solo si el vehículo es de color oscuro."],"c":0,"img":null,"e":"De día es obligatorio el alumbrado de cruce al circular por túneles y pasos inferiores, por carriles reversibles, adicionales o en sentido contrario al habitual, además de en motocicletas en todo momento.","r":"RGC art. 104 y 106","k":null,"d":0,"rev":null},{"id":"p041","src":"practica","bat":[],"t":"alcohol","q":"Para un conductor con más de dos años de permiso B (no profesional), ¿cuál es la tasa máxima de alcohol en aire espirado?","o":["0,15 mg/l.","0,25 mg/l.","0,50 mg/l."],"c":1,"img":null,"e":"Tasas generales: 0,5 g/l en sangre o 0,25 mg/l en aire espirado. Para noveles (dos primeros años) y profesionales: 0,3 g/l en sangre o 0,15 mg/l en aire.","r":"RGC art. 20","k":"General 0,25 aire · Novel/profesional 0,15 aire.","d":0,"rev":null},{"id":"p042","src":"practica","bat":[],"t":"alcohol","q":"¿A partir de qué tasa de alcohol en aire espirado es delito conducir, aunque no se cometa ninguna otra infracción?","o":["0,25 mg/l.","0,60 mg/l.","1,00 mg/l."],"c":1,"img":null,"e":"Conducir con una tasa superior a 0,60 mg/l en aire espirado (o 1,2 g/l en sangre) es delito según el Código Penal. Por debajo, superar el límite es infracción administrativa (multa y puntos).","r":"Código Penal art. 379.2","k":null,"d":0,"rev":null},{"id":"p043","src":"practica","bat":[],"t":"documentacion","q":"¿Cuántos puntos tiene un conductor que obtiene su primer permiso de conducción?","o":["12 puntos.","8 puntos.","15 puntos."],"c":1,"img":null,"e":"El conductor novel empieza con 8 puntos. Si en sus dos primeros años no pierde puntos por sanciones firmes, pasa a 12. Después puede llegar a 14 y a 15 con bonificaciones.","r":"LSV art. 63","k":null,"d":0,"rev":null},{"id":"p044","src":"practica","bat":[],"t":"documentacion","q":"¿Cuántos puntos se pierden por conducir sujetando con la mano el teléfono móvil?","o":["3 puntos.","4 puntos.","6 puntos."],"c":2,"img":null,"e":"Desde la reforma de 2022, conducir sujetando con la mano el móvil u otro dispositivo de comunicación resta 6 puntos (y 200 € de multa). Usarlo con manos libres está permitido, aunque también distrae.","r":"LSV anexo II (Ley 18/2021)","k":"Móvil en la mano = 6 puntos.","d":0,"rev":null},{"id":"p045","src":"practica","bat":[],"t":"documentacion","q":"No utilizar el cinturón de seguridad, el sistema de retención infantil o el casco, ¿cuántos puntos resta?","o":["2 puntos.","4 puntos.","6 puntos."],"c":1,"img":null,"e":"No usar o usar incorrectamente el cinturón, el SRI, el casco u otros elementos de protección obligatorios resta 4 puntos (desde 2022; antes eran 3).","r":"LSV anexo II (Ley 18/2021)","k":null,"d":0,"rev":null},{"id":"p046","src":"practica","bat":[],"t":"documentacion","q":"Durante cuánto tiempo debe llevar la señal «L» un conductor que acaba de obtener el permiso B?","o":["Durante el primer año.","Durante los dos primeros años.","Durante seis meses."],"c":0,"img":null,"e":"La señal V-13 «L» de conductor novel es obligatoria durante el primer año de permiso, en la parte trasera izquierda. La consideración de novel a efectos de alcohol y puntos dura dos años.","r":"RGCond · RGV (V-13)","k":null,"d":1,"rev":null},{"id":"p047","src":"practica","bat":[],"t":"documentacion","q":"Con carácter general, ¿cada cuánto tiempo debe renovarse el permiso B de un conductor menor de 65 años?","o":["Cada 5 años.","Cada 10 años.","Cada 15 años."],"c":1,"img":null,"e":"El permiso B tiene una vigencia de 10 años hasta los 65 años de edad; a partir de esa edad, de 5 años (salvo que el reconocimiento médico establezca un plazo menor).","r":"RGCond art. 12","k":null,"d":0,"rev":null},{"id":"p048","src":"practica","bat":[],"t":"mantenimiento","q":"Un turismo de uso particular nuevo, ¿cuándo debe pasar su primera ITV?","o":["Al año de su matriculación.","A los 4 años de su matriculación.","A los 2 años de su matriculación."],"c":1,"img":null,"e":"Turismos de uso particular: exentos hasta los 4 años; de 4 a 10 años, cada 2 años; más de 10 años, cada año.","r":"RD 920/2017 (ITV)","k":"ITV turismo: 4 años, luego cada 2, desde los 10 cada año.","d":0,"rev":null},{"id":"p049","src":"practica","bat":[],"t":"mantenimiento","q":"¿Cuál es la profundidad mínima legal del dibujo de los neumáticos de un turismo?","o":["1 mm.","1,6 mm.","3 mm."],"c":1,"img":null,"e":"La profundidad mínima legal de las ranuras principales es 1,6 mm (los neumáticos tienen indicadores TWI a esa altura). Por seguridad, conviene cambiarlos antes, hacia los 3 mm, sobre todo en lluvia.","r":"Reglamento General de Vehículos","k":null,"d":0,"rev":null},{"id":"p050","src":"practica","bat":[],"t":"mantenimiento","q":"¿Cuándo debe comprobarse la presión de los neumáticos?","o":["En frío, con el vehículo parado y sin haber recorrido muchos kilómetros.","En caliente, después de un viaje largo.","Solo en la ITV."],"c":0,"img":null,"e":"La presión se mide en frío, porque al calentarse el aire se dilata y el manómetro marca más. Conviene revisarla cada 15 días aproximadamente y antes de viajes largos.","r":"Mantenimiento","k":null,"d":0,"rev":null},{"id":"p051","src":"practica","bat":[],"t":"seguridad","q":"Un niño mide 125 cm. ¿Cómo debe viajar en un turismo?","o":["Con el cinturón de seguridad normal en el asiento trasero.","En un sistema de retención infantil adaptado a su talla y peso, en un asiento trasero como norma general.","En brazos de un adulto en el asiento trasero."],"c":1,"img":null,"e":"Los menores de 135 cm de estatura deben usar un sistema de retención infantil homologado adecuado a su talla y peso y viajar en los asientos traseros, salvo excepciones (que no haya asientos traseros, estén ocupados por otros menores o no se pueda instalar el SRI).","r":"RGC art. 117","k":"Menos de 135 cm: SRI y detrás.","d":0,"rev":null},{"id":"p052","src":"practica","bat":[],"t":"seguridad","q":"Si se instala una silla infantil en el asiento delantero en sentido contrario a la marcha, ¿qué debe hacerse?","o":["Desactivar el airbag frontal del acompañante.","Nada, el airbag protege al niño.","Adelantar el asiento al máximo."],"c":0,"img":null,"e":"Con una silla en sentido contrario a la marcha en el asiento delantero hay que desactivar el airbag frontal: al desplegarse golpearía la silla y podría causar lesiones muy graves al bebé.","r":"RGC art. 117","k":null,"d":0,"rev":null},{"id":"p053","src":"practica","bat":[],"t":"seguridad","q":"¿A qué altura debe quedar la parte superior del reposacabezas?","o":["A la altura del cuello.","Al menos a la altura de los ojos, idealmente a la altura de la parte superior de la cabeza.","Lo más bajo posible para no molestar."],"c":1,"img":null,"e":"El borde superior del reposacabezas debe quedar a la altura de la parte superior de la cabeza (como mínimo, de los ojos) y lo más cerca posible de ella. Si queda a la altura del cuello, en un alcance puede actuar como palanca y agravar la lesión.","r":"Seguridad pasiva","k":null,"d":0,"rev":null},{"id":"p054","src":"practica","bat":[],"t":"seguridad","q":"Según la recomendación habitual, ¿cuántos segundos de distancia como mínimo conviene dejar con el vehículo de delante en vía seca?","o":["Al menos 2 segundos.","Medio segundo.","No hay que dejar distancia en autovía."],"c":0,"img":null,"e":"Una forma práctica de mantener la distancia de seguridad es la regla de los 2 segundos: cuando el vehículo de delante pase por un punto fijo, debes tardar al menos 2 s en llegar a él. Con lluvia o mala visibilidad, aumenta a 3 o más.","r":"RGC art. 54 (recomendación DGT)","k":"Regla de los 2 segundos (más con lluvia).","d":0,"rev":null},{"id":"p055","src":"practica","bat":[],"t":"velocidad","q":"Si la velocidad se duplica, ¿qué ocurre con la distancia de frenado?","o":["Se duplica.","Se multiplica aproximadamente por cuatro.","No cambia si los frenos están bien."],"c":1,"img":null,"e":"La distancia de frenado es proporcional al cuadrado de la velocidad: al doble de velocidad, aproximadamente cuatro veces más distancia de frenado. La de reacción, en cambio, crece de forma proporcional.","r":"Física de la conducción","k":null,"d":1,"rev":null},{"id":"p056","src":"practica","bat":[],"t":"eficiente","q":"Para una conducción eficiente, ¿qué es recomendable en un turismo de gasolina?","o":["Cambiar de marcha a altas revoluciones para ganar potencia.","Usar marchas largas y cambiar aproximadamente entre 2.000 y 2.500 rpm.","Acelerar al máximo y frenar en el último momento."],"c":1,"img":null,"e":"La conducción eficiente recomienda circular en la marcha más larga posible a bajas revoluciones, cambiar pronto (≈2.000–2.500 rpm en gasolina, ≈1.500–2.000 en diésel), mantener velocidad uniforme y anticiparse para no frenar bruscamente.","r":"IDAE / DGT: conducción eficiente","k":null,"d":0,"rev":null},{"id":"p057","src":"practica","bat":[],"t":"eficiente","q":"Ante una parada prolongada (más de un minuto aproximadamente), ¿qué recomienda la conducción eficiente?","o":["Mantener el motor al ralentí.","Apagar el motor.","Acelerar en vacío para que no se enfríe."],"c":1,"img":null,"e":"En paradas de más de unos 60 segundos conviene apagar el motor: un motor al ralentí consume combustible sin avanzar. Muchos vehículos lo hacen solos con el sistema start-stop.","r":"IDAE: conducción eficiente","k":null,"d":0,"rev":null},{"id":"p058","src":"practica","bat":[],"t":"eficiente","q":"Al bajar una pendiente pronunciada con una marcha engranada y sin pisar el acelerador, ¿cuánto combustible consume un motor de inyección moderno?","o":["Prácticamente nada.","Más que al ralentí.","Lo mismo que en llano."],"c":0,"img":null,"e":"Con una marcha engranada y sin acelerar (retención), la inyección corta el combustible: el consumo es prácticamente cero. En punto muerto el motor sí consume para mantenerse al ralentí, y además se pierde el freno motor.","r":"IDAE: conducción eficiente","k":null,"d":0,"rev":null},{"id":"p059","src":"practica","bat":[],"t":"eficiente","q":"¿Qué distintivo ambiental corresponde a un vehículo eléctrico de batería?","o":["Etiqueta ECO.","Etiqueta 0 emisiones (azul).","Etiqueta C (verde)."],"c":1,"img":null,"e":"Los distintivos de la DGT son: 0 emisiones (azul) para eléctricos y algunos híbridos enchufables con autonomía eléctrica de al menos 40 km; ECO para híbridos y gas; C (verde) y B (amarilla) para combustión según su norma Euro. Determinan el acceso a las zonas de bajas emisiones.","r":"RGV anexo II · DGT","k":null,"d":0,"rev":null},{"id":"p060","src":"practica","bat":[],"t":"accidentes","q":"Ante un accidente, ¿cuál es el orden correcto de actuación?","o":["Socorrer, Avisar y Proteger.","Proteger, Avisar y Socorrer (PAS).","Avisar, Socorrer y Proteger."],"c":1,"img":null,"e":"Primero Proteger (señalizar, chaleco, apagar motores), después Avisar al 112 con información precisa y, por último, Socorrer a las víctimas con las medidas básicas que se sepan aplicar.","r":"Primeros auxilios: conducta PAS","k":"PAS: Proteger, Avisar, Socorrer.","d":0,"rev":null},{"id":"p061","src":"practica","bat":[],"t":"accidentes","q":"Un motorista herido está consciente y lleva el casco puesto. Como norma general, ¿qué debe hacer?","o":["Quitarle el casco para que respire mejor.","No quitarle el casco, salvo que sea imprescindible (por ejemplo, porque no respira) y sepa hacerlo.","Quitarle el casco y darle agua."],"c":1,"img":null,"e":"Al motorista accidentado no se le quita el casco como norma general, porque puede tener una lesión cervical. Solo se retira si es imprescindible para mantener la vía aérea y por personas que sepan hacerlo, sujetando cabeza y cuello.","r":"Primeros auxilios","k":null,"d":0,"rev":null},{"id":"p062","src":"practica","bat":[],"t":"accidentes","q":"Un herido está inconsciente pero respira y no hay sospecha de lesión de columna. ¿En qué posición conviene colocarlo?","o":["Boca arriba con las piernas elevadas.","En posición lateral de seguridad (PLS).","Sentado."],"c":1,"img":null,"e":"Si está inconsciente y respira, la posición lateral de seguridad mantiene abierta la vía aérea y evita que se ahogue con vómitos. Si se sospecha lesión de columna, no se le moverá salvo peligro inminente.","r":"Primeros auxilios","k":null,"d":0,"rev":null},{"id":"p063","src":"practica","bat":[],"t":"accidentes","q":"¿Qué número debe marcar para avisar a los servicios de emergencia en España y en toda la Unión Europea?","o":["091.","112.","060."],"c":1,"img":null,"e":"El 112 es el número único de emergencias en España y en la UE; es gratuito y funciona aunque no haya saldo. Al llamar hay que indicar el lugar exacto (carretera y punto kilométrico), el número de heridos y su estado.","r":"Emergencias 112","k":null,"d":0,"rev":null},{"id":"p064","src":"practica","bat":[],"t":"accidentes","q":"¿Qué no se debe hacer, como norma general, con un herido en un accidente?","o":["Abrigarle.","Darle de beber o de comer.","Hablarle para tranquilizarle."],"c":1,"img":null,"e":"No se le da de beber ni de comer (podría necesitar cirugía o ahogarse). Sí se le abriga para evitar que pierda calor y se le habla con calma.","r":"Primeros auxilios","k":null,"d":0,"rev":null},{"id":"p065","src":"practica","bat":[],"t":"factor","q":"¿Cada cuánto tiempo se recomienda descansar en un viaje largo?","o":["Cada 2 horas o 200 km aproximadamente.","Cada 5 horas.","Solo cuando aparezca el sueño."],"c":0,"img":null,"e":"La recomendación es parar unos 20 minutos cada 2 horas o 200 km, aproximadamente, para prevenir la fatiga. Esperar a tener sueño es demasiado tarde.","r":"DGT: fatiga y sueño","k":null,"d":0,"rev":null},{"id":"p066","src":"practica","bat":[],"t":"factor","q":"¿Puede usar el navegador del móvil mientras conduce?","o":["Sí, sujetándolo con la mano.","Sí, si está en un soporte fijo y no lo manipula durante la marcha.","No, el GPS está prohibido."],"c":1,"img":null,"e":"Se puede usar el móvil como navegador si va en un soporte y no se manipula durante la marcha (se programa antes de salir). Sujetarlo con la mano resta 6 puntos.","r":"RGC art. 18.2","k":null,"d":0,"rev":null},{"id":"p067","src":"practica","bat":[],"t":"factor","q":"¿Está permitido conducir con auriculares conectados a un reproductor de sonido?","o":["Sí, si el volumen es bajo.","No, está prohibido conducir con cascos o auriculares conectados a aparatos receptores o reproductores de sonido.","Sí, si solo se lleva uno puesto."],"c":1,"img":null,"e":"Se prohíbe conducir utilizando cascos o auriculares conectados a aparatos receptores o reproductores de sonido (salvo durante la enseñanza y pruebas de moto, con sistemas autorizados). Resta 3 puntos.","r":"RGC art. 18.2","k":null,"d":0,"rev":null},{"id":"p068","src":"practica","bat":[],"t":"prioridad","q":"Un vehículo de urgencia con la señal luminosa y acústica activada se aproxima por detrás. ¿Qué debe hacer?","o":["Seguir igual, ya le adelantará.","Facilitarle el paso, apartándose normalmente a la derecha o deteniéndose si es necesario.","Acelerar para no entorpecerle."],"c":1,"img":null,"e":"Los vehículos prioritarios en servicio de urgencia (con señales luminosas y acústicas) tienen preferencia. Hay que facilitarles el paso, apartándose de forma ordenada (normalmente a la derecha) y deteniéndose si es preciso.","r":"RGC art. 69","k":null,"d":0,"rev":null},{"id":"p069","src":"practica","bat":[],"t":"prioridad","q":"En un tramo estrecho con fuerte pendiente sin señalizar, si no puede saberse quién entró primero, ¿quién tiene prioridad?","o":["El vehículo que circula en sentido ascendente.","El vehículo que circula en sentido descendente.","El de mayor tamaño, en todo caso."],"c":0,"img":null,"e":"En tramos estrechos de gran pendiente, si no puede determinarse quién entró primero, tiene preferencia el vehículo que sube, salvo que este pueda llegar antes a un apartadero. Si los vehículos son de distinto tipo, se aplica antes el orden de preferencia por tipo de vehículo.","r":"RGC arts. 62 y 63","k":null,"d":1,"rev":null},{"id":"p070","src":"practica","bat":[],"t":"circulacion","q":"En un túnel o paso inferior, ¿qué está prohibido como norma general?","o":["Circular con luz de cruce.","Parar, estacionar, cambiar de sentido y marcha atrás.","Circular a la velocidad indicada."],"c":1,"img":null,"e":"En túneles están prohibidos la parada, el estacionamiento, el cambio de sentido y la marcha atrás, y el adelantamiento si solo hay un carril por sentido (salvo que haya más carriles). Es obligatorio llevar la luz de cruce.","r":"RGC arts. 49, 79, 80 y 91","k":null,"d":0,"rev":null},{"id":"p071","src":"practica","bat":[],"t":"maniobras","q":"¿Cómo debe girar a la derecha en una intersección?","o":["Ciñéndose todo lo posible al borde derecho de la calzada, tras señalizar.","Abriéndose primero a la izquierda para tomar mejor la curva.","Desde el carril izquierdo."],"c":0,"img":null,"e":"Para girar a la derecha hay que señalizar con antelación, situarse lo más cerca posible del borde derecho y girar ciñéndose a él. Abrirse hacia la izquierda confunde a los demás y es peligroso para motos y bicis que van por la derecha.","r":"RGC art. 75","k":null,"d":0,"rev":null},{"id":"p072","src":"practica","bat":[],"t":"senales","q":"Una línea longitudinal continua en el centro de la calzada, ¿qué significa?","o":["Que ningún conductor debe atravesarla ni circular sobre ella.","Que se puede rebasar para adelantar a cualquier vehículo.","Que la vía es de sentido único."],"c":0,"img":null,"e":"La línea continua no puede ser atravesada ni pisada. Excepciones: para adelantar a ciclistas con seguridad y, en ciertos casos, para acceder a lugares situados al otro lado cuando así se permita, o cuando la marca está doblada con una discontinua de tu lado.","r":"RGC art. 167","k":null,"d":0,"rev":null},{"id":"p073","src":"practica","bat":[],"t":"senales","q":"Una línea continua junto a una discontinua en el centro de la calzada. Usted circula por el lado de la discontinua. ¿Puede rebasarlas para adelantar?","o":["Sí, porque la línea más próxima a usted es discontinua.","No, en ningún caso.","Solo si adelanta a un camión."],"c":0,"img":null,"e":"Cuando hay una línea continua y otra discontinua juntas, cada conductor obedece a la línea que tiene más cerca. Si la discontinua está de tu lado, puedes rebasarlas (para adelantar con seguridad) y volver; el que tiene la continua de su lado, no.","r":"RGC art. 167","k":"Manda la línea más cercana a ti.","d":0,"rev":null},{"id":"p074","src":"practica","bat":[],"t":"adelantamiento","q":"Desde el 1 de octubre de 2026, al adelantar a un ciclista en una vía interurbana, ¿qué debe hacer con la velocidad?","o":["Mantenerla, sin superar el límite de la vía.","Reducirla al menos 20 km/h respecto al límite de la vía.","Aumentarla para terminar antes el adelantamiento."],"c":1,"img":null,"e":"El RD 518/2026 obliga a quien adelanta a ciclistas en vía interurbana a reducir la velocidad al menos 20 km/h por debajo del límite de la vía, además de dejar 1,5 m de separación lateral y cambiar completamente de carril si hay más de uno por sentido.","r":"RGC art. 85 (RD 518/2026, en vigor desde el 1-10-2026)","k":"Ciclista: −20 km/h, 1,5 m y, si hay dos carriles, cambio completo.","d":1,"rev":null},{"id":"p075","src":"practica","bat":[],"t":"adelantamiento","q":"En una vía urbana, ¿qué distancia mínima debe mantener un turismo con un ciclista que circula delante por el mismo carril?","o":["2 metros.","5 metros.","1,5 metros."],"c":1,"img":null,"e":"Con la reforma de 2026, en vías urbanas los vehículos a motor deben dejar una separación mínima de 5 metros con los ciclistas que les preceden en el mismo carril. Los 1,5 m son la separación lateral al adelantar.","r":"RGC, título VI (RD 518/2026)","k":null,"d":1,"rev":null},{"id":"p076","src":"practica","bat":[],"t":"circulacion","q":"En vías urbanas, ¿por dónde circularán preferentemente los ciclistas según la reforma del Reglamento de 2026?","o":["Por el borde derecho del carril, pegados a los coches aparcados.","Por el centro del carril.","Por la acera, si no hay carril bici."],"c":1,"img":null,"e":"Desde el 1 de octubre de 2026 los ciclistas circulan preferentemente por el centro del carril en vías urbanas, lo que les hace más visibles y evita el riesgo de las puertas de los coches aparcados. La acera es para peatones.","r":"RGC, título VI (RD 518/2026)","k":null,"d":0,"rev":null},{"id":"p077","src":"practica","bat":[],"t":"seguridad","q":"¿Es obligatorio el casco para los ciclistas en vías interurbanas?","o":["Sí, para todos los ciclistas, sin las exenciones que existían antes.","Solo para menores de 16 años.","No, si hace mucho calor o es una rampa prolongada."],"c":0,"img":null,"e":"La reforma de 2026 suprimió las exenciones (calor intenso, rampas prolongadas, competiciones…): todos los ciclistas deben llevar casco en vías interurbanas.","r":"RGC art. 118 (RD 518/2026)","k":null,"d":1,"rev":null},{"id":"p078","src":"practica","bat":[],"t":"circulacion","q":"¿Cuál es la edad mínima para conducir un patinete eléctrico (VMP) según el Reglamento vigente desde octubre de 2026?","o":["15 años.","16 años.","No hay edad mínima."],"c":0,"img":null,"e":"El RD 518/2026 fija en 15 años la edad mínima para conducir un VMP y hace obligatorio el casco, además del chaleco reflectante de noche o con poca visibilidad.","r":"RGC (RD 518/2026)","k":null,"d":0,"rev":null},{"id":"p079","src":"practica","bat":[],"t":"seguridad","q":"¿Qué equipamiento es obligatorio para el conductor de un patinete eléctrico (VMP)?","o":["Ninguno, salvo que lo exija la ordenanza municipal.","Casco de protección, y chaleco reflectante de noche o con escasa visibilidad.","Solo guantes."],"c":1,"img":null,"e":"Desde el 1 de octubre de 2026 el casco es obligatorio para los usuarios de VMP y el chaleco reflectante, de noche o con escasa visibilidad. Además, desde el 1 de octubre de 2027 deberán llevar el alumbrado encendido siempre.","r":"RGC (RD 518/2026)","k":null,"d":0,"rev":null},{"id":"p080","src":"practica","bat":[],"t":"seguridad","q":"Para los conductores y pasajeros de motocicletas, ¿qué es obligatorio en vías interurbanas desde octubre de 2026, además del casco?","o":["Guantes de protección (y calzado cerrado en cualquier vía).","Traje de cuero completo.","Airbag de chaleco."],"c":0,"img":null,"e":"La reforma obliga a usar guantes de protección en vías interurbanas y calzado cerrado en todo tipo de vías (infracción grave, 200 €). El traje de cuero y el airbag siguen siendo recomendables, no obligatorios.","r":"RGC art. 118 (RD 518/2026)","k":null,"d":0,"rev":null},{"id":"p081","src":"practica","bat":[],"t":"circulacion","q":"En una autopista con retención, los vehículos avanzan a paso de peatón. Hay dos carriles por sentido. ¿Cómo deben colocarse para formar el carril de emergencia?","o":["Todos a la derecha, dejando libre el carril izquierdo.","Los del carril izquierdo se orillan a la izquierda y los del derecho a la derecha, dejando libre el espacio central.","No hay que moverse; los servicios de emergencia usan el arcén."],"c":1,"img":null,"e":"Con dos carriles, los vehículos se orillan a ambos lados dejando libre el espacio central. Con tres carriles, el izquierdo se orilla a la izquierda y el central y el derecho a la derecha, abriendo el hueco entre el izquierdo y el central.","r":"RGC (RD 518/2026): carril de emergencia","k":"Carril de emergencia: el hueco siempre a la derecha del carril más a la izquierda.","d":1,"rev":null},{"id":"p082","src":"practica","bat":[],"t":"circulacion","q":"En una autovía de tres carriles por sentido se forma una retención. Usted circula por el carril central. ¿Hacia dónde debe orillarse?","o":["Hacia la izquierda.","Hacia la derecha.","Debe quedarse en el centro del carril."],"c":1,"img":null,"e":"En vías de tres carriles, el carril izquierdo se orilla a la izquierda y el central y el derecho se orillan a la derecha: el carril de emergencia queda entre el izquierdo y el central.","r":"RGC (RD 518/2026): carril de emergencia","k":null,"d":1,"rev":null},{"id":"p083","src":"practica","bat":[],"t":"adelantamiento","q":"Circulando por una autovía, la circulación se ve dificultada por la nieve. ¿Qué norma rige?","o":["Se puede adelantar con normalidad si se llevan cadenas.","Está prohibido adelantar y se circula solo por el carril derecho, dejando libre el izquierdo para emergencias y quitanieves.","Se debe circular por el carril izquierdo, que suele estar más limpio."],"c":1,"img":null,"e":"Desde octubre de 2026, en autopistas y autovías con circulación dificultada por la nieve está prohibido adelantar y hay que ir por el carril derecho, dejando el izquierdo libre para vehículos de emergencia y quitanieves.","r":"RGC (RD 518/2026)","k":null,"d":0,"rev":null},{"id":"p084","src":"practica","bat":[],"t":"adelantamiento","q":"Va a rebasar a una grúa que está atendiendo a un vehículo averiado en el arcén. ¿Qué debe hacer?","o":["Pasar a la velocidad de la vía, ya que están en el arcén.","Dejar una separación lateral de al menos 1,5 m y reducir la velocidad al menos 20 km/h respecto al límite.","Tocar el claxon para avisar de su paso."],"c":1,"img":null,"e":"Al rebasar vehículos inmovilizados por accidente, avería, labores de auxilio, mantenimiento o regulación del tráfico hay que dejar 1,5 m de separación lateral y reducir al menos 20 km/h respecto al límite de la vía (RD 518/2026).","r":"RGC (RD 518/2026)","k":"Vehículo detenido con personas trabajando: 1,5 m y −20 km/h.","d":0,"rev":null},{"id":"p085","src":"practica","bat":[],"t":"circulacion","q":"En una vía con congestión de tráfico, ¿puede una motocicleta circular por el arcén derecho?","o":["Sí, en cualquier vía y a cualquier velocidad.","Sí, cuando el tramo esté señalizado para ello y sin superar los 30 km/h.","No, nunca."],"c":1,"img":null,"e":"La reforma de 2026 permite a las motocicletas circular por el arcén derecho cuando haya congestión, solo en tramos señalizados y sin superar los 30 km/h.","r":"RGC (RD 518/2026)","k":null,"d":1,"rev":null},{"id":"p086","src":"practica","bat":[],"t":"prioridad","q":"En una calle de plataforma única (calzada y acera al mismo nivel), ¿quién tiene prioridad?","o":["Los vehículos a motor.","Los peatones.","Las bicicletas."],"c":1,"img":null,"e":"En las calles de plataforma única los peatones tienen prioridad (RD 518/2026). Además, la velocidad máxima genérica en ellas es de 20 km/h.","r":"RGC, título VI (RD 518/2026) · RGC art. 50","k":null,"d":0,"rev":null},{"id":"p087","src":"practica","bat":[],"t":"seguridad","q":"Un taxista circula por ciudad con un pasajero. ¿Debe llevar abrochado el cinturón de seguridad?","o":["No, los taxistas están exentos en ciudad.","Sí, desde octubre de 2026 se suprimió esa exención y debe llevarlo siempre.","Solo si circula a más de 50 km/h."],"c":1,"img":null,"e":"El RD 518/2026 eliminó las exenciones del cinturón para conductores de taxi, de vehículos de mercancías y de vehículos de enseñanza de la conducción: deben llevarlo en todo momento.","r":"RGC (RD 518/2026)","k":null,"d":1,"rev":null},{"id":"p088","src":"practica","bat":[],"t":"circulacion","q":"Un repartidor (rider) trabaja con una bicicleta. ¿Qué debe llevar?","o":["Casco y chaleco reflectante en todo momento.","Solo casco en vías interurbanas.","Nada específico por ser profesional."],"c":0,"img":null,"e":"Quienes usan bicicleta, VMP, ciclomotor o motocicleta para una actividad profesional deben llevar casco y chaleco reflectante en todo momento (RD 518/2026).","r":"RGC (RD 518/2026)","k":null,"d":0,"rev":null}];
